```javascript
import http from 'k6/http';
import { check, fail } from 'k6';
import { parseHTML } from 'k6/html';

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

function assert(condition, name) {
  if (!check(condition, { [name]: (value) => value })) {
    fail(name);
  }
}

function json(response) {
  try {
    return JSON.parse(response.body);
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return null;
}

function resolveLocation(location, from) {
  assert(typeof location === 'string' && location.length > 0, 'location is present');
  if (/^https?:\/\//i.test(location)) {
    assert(
      location === BASE || location.startsWith(BASE + '/') || location.startsWith(BASE + '?'),
      'location stays on target'
    );
    return location;
  }
  assert(!location.startsWith('//'), 'location stays on target');
  if (location.startsWith('/')) return BASE + location;
  const withoutQuery = from.split('?')[0];
  if (location.startsWith('?')) return withoutQuery + location;
  return withoutQuery.slice(0, withoutQuery.lastIndexOf('/') + 1) + location;
}

function raw(state, method, url, payload, headers) {
  const requestHeaders = Object.assign({}, headers || {});
  let body = null;
  if (payload !== null && payload !== undefined) {
    requestHeaders['Content-Type'] = 'application/json';
    body = JSON.stringify(payload);
  }
  return http.request(method, url, body, {
    jar: state.jar,
    redirects: 0,
    headers: requestHeaders,
  });
}

function captureCsrf(state, response) {
  const data = json(response);
  if (data && typeof data.csrf === 'string' && data.csrf.length > 0) {
    state.csrf = data.csrf;
  }
}

function formCsrf(body) {
  const document = parseHTML(body);
  const loginCandidates = [];
  const otherCandidates = [];

  document.find('form').each((_, form) => {
    const action = (form.attr('action') || '').trim();
    const isLoginForm = /(?:^|\/)v2\/login\/?(?:[?#]|$)/i.test(action);
    form.find('input').each((__, input) => {
      const name = input.attr('name');
      const type = (input.attr('type') || '').trim().toLowerCase();
      const value = input.attr('value');
      if (name === 'csrf' && type === 'hidden' &&
          typeof value === 'string' && value.length > 0) {
        (isLoginForm ? loginCandidates : otherCandidates).push(value);
      }
    });
  });

  const candidates = loginCandidates.length > 0 ? loginCandidates : otherCandidates;
  assert(candidates.length === 1, 'one login form hidden csrf input');
  return candidates[0];
}

function login(state) {
  const form = raw(state, 'GET', BASE + '/v2/login-form', null, {});
  assert(form.status === 200, 'login form returned 200');
  const token = formCsrf(form.body);
  state.csrf = token;

  const response = raw(state, 'POST', BASE + '/v2/login', {
    username: state.username,
    password: 'bench',
    csrf: token,
  }, {});
  assert(response.status === 200 || response.status === 302, 'login succeeded');
  captureCsrf(state, response);

  if (response.status === 302) {
    const destination = resolveLocation(header(response, 'Location'), BASE + '/v2/login');
    const landing = raw(state, 'GET', destination, null, {});
    assert(landing.status === 200, 'login redirect returned 200');
    captureCsrf(state, landing);
  }
  assert(typeof state.csrf === 'string' && state.csrf.length > 0, 'session csrf available');
}

function recoverSession(state, reason) {
  if (reason === 'expired') {
    const renewed = raw(state, 'POST', BASE + '/v2/session/renew', {}, {
      'X-CSRF-Token': state.csrf,
    });
    const renewalBody = json(renewed);
    if (renewed.status === 401 && renewalBody && renewalBody.error === 'session') {
      login(state);
    } else {
      assert(renewed.status >= 200 && renewed.status < 300, 'session renewed');
      assert(
        renewalBody && typeof renewalBody.csrf === 'string' && renewalBody.csrf.length > 0,
        'renewal supplied csrf'
      );
      state.csrf = renewalBody.csrf;
    }
  } else {
    login(state);
  }

  if (state.cartId !== null) {
    const recovered = raw(
      state,
      'POST',
      BASE + '/v2/carts/' + encodeURIComponent(String(state.cartId)) + '/recover',
      {},
      { 'X-CSRF-Token': state.csrf }
    );
    assert(recovered.status >= 200 && recovered.status < 300, 'cart recovered');
    captureCsrf(state, recovered);
  }
}

function authorized(state, method, url, payload, extraHeaders) {
  function send() {
    const headers = Object.assign({}, extraHeaders || {});
    if (method !== 'GET') headers['X-CSRF-Token'] = state.csrf;
    return raw(state, method, url, payload, headers);
  }

  let response = send();
  if (response.status === 401) {
    const data = json(response);
    if (data && (data.error === 'expired' || data.error === 'session')) {
      recoverSession(state, data.error);
      response = send();
    }
  }
  if (response.status >= 200 && response.status < 300) {
    captureCsrf(state, response);
  }
  return response;
}

function availableProduct(state) {
  let url = BASE + '/v2/catalog';
  let pages = 0;

  while (url !== null) {
    const response = authorized(state, 'GET', url, null, {});
    assert(response.status === 200, 'catalog returned 200');
    const result = json(response);
    assert(result && result.data, 'catalog has data');

    let products = [];
    if (Array.isArray(result.data.products)) {
      products = result.data.products;
    } else if (result.data.product) {
      products = [result.data.product];
    }

    for (const product of products) {
      if (!product || product.id === undefined || product.id === null ||
          !Array.isArray(product.variants)) continue;
      for (const variant of product.variants) {
        if (variant && variant.in_stock === true &&
            variant.id !== undefined && variant.id !== null) {
          return { productId: product.id, variantId: variant.id };
        }
      }
    }

    if (!result.next) break;
    assert(pages < 3, 'catalog page traversal is bounded');
    url = resolveLocation(result.next, url);
    pages += 1;
  }

  assert(false, 'catalog contains an in-stock variant');
}

function readCart(state) {
  const url = BASE + '/v2/carts/' + encodeURIComponent(String(state.cartId));
  const response = authorized(state, 'GET', url, null, {});
  assert(response.status === 200, 'cart read returned 200');
  const etag = header(response, 'ETag');
  assert(typeof etag === 'string' && etag.length > 0, 'cart has etag');
  return etag;
}

export default function () {
  const state = {
    jar: new http.CookieJar(),
    username: 'bench-' + __VU,
    csrf: null,
    cartId: null,
  };

  login(state);
  const selection = availableProduct(state);

  const created = authorized(state, 'POST', BASE + '/v2/carts', {
    product_id: selection.productId,
    variant_id: selection.variantId,
  }, {});
  assert(created.status === 201, 'cart created');
  const cart = json(created);
  assert(cart && cart.id !== undefined && cart.id !== null, 'cart id returned');
  state.cartId = cart.id;

  const cartUrl = BASE + '/v2/carts/' + encodeURIComponent(String(state.cartId));
  const patchPayload = { quantity: 1 };
  let etag = readCart(state);
  let patched = authorized(state, 'PATCH', cartUrl, patchPayload, { 'If-Match': etag });
  if (patched.status === 412) {
    etag = readCart(state);
    patched = authorized(state, 'PATCH', cartUrl, patchPayload, { 'If-Match': etag });
  }
  assert(patched.status >= 200 && patched.status < 300, 'cart quantity updated');

  etag = readCart(state);
  const order = authorized(state, 'POST', BASE + '/v2/orders', {
    cart_id: state.cartId,
  }, {
    'If-Match': etag,
    'Idempotency-Key': 'cart-' + String(state.cartId),
  });
  const orderBody = json(order);
  assert(
    order.status === 201 && orderBody && orderBody.accepted === true &&
      orderBody.id !== undefined && orderBody.id !== null,
    'order accepted'
  );
}
