import itertools
import os
import uuid
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"].rstrip("/")
_base = urlsplit(BASE_URL)
if (
    _base.scheme != "http"
    or _base.hostname != "127.0.0.1"
    or _base.port != 8000
    or _base.username is not None
    or _base.password is not None
    or _base.path not in ("", "/")
    or _base.query
    or _base.fragment
):
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

_user_numbers = itertools.count(1)
_finished_users = 0


class FlowAbort(Exception):
    pass


def checked_url(url, relative_to=None):
    absolute = urljoin(relative_to or BASE_URL + "/", url)
    parts = urlsplit(absolute)
    if (
        parts.scheme != "http"
        or parts.hostname != "127.0.0.1"
        or parts.port != 8000
        or parts.username is not None
        or parts.password is not None
        or parts.fragment
    ):
        raise ValueError("URL is outside the permitted target")
    return absolute


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.current = None
        self.outside = {"attrs": {}, "inputs": []}

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if tag == "form":
            form = {"attrs": attributes, "inputs": []}
            self.forms.append(form)
            self.current = form
        elif tag == "input":
            (self.current or self.outside)["inputs"].append(attributes)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag == "form":
            self.current = None

    def handle_endtag(self, tag):
        if tag == "form":
            self.current = None

    def csrf(self):
        candidates = []
        for form in self.forms + [self.outside]:
            tokens = [
                item.get("value")
                for item in form["inputs"]
                if item.get("name") == "csrf"
                and (item.get("type") or "").lower() == "hidden"
                and item.get("value")
            ]
            if not tokens:
                continue
            attrs = form["attrs"]
            action = urlsplit(attrs.get("action") or "").path.rstrip("/")
            names = {item.get("name") for item in form["inputs"]}
            has_password = any(
                (item.get("type") or "").lower() == "password"
                for item in form["inputs"]
            )
            score = (
                4 * (action == "/v2/login")
                + 2 * has_password
                + ("username" in names)
            )
            candidates.append((score, tokens[0]))
        if not candidates:
            raise ValueError("login form has no hidden csrf input")
        return max(candidates, key=lambda candidate: candidate[0])[1]


def json_object(response):
    try:
        value = response.json()
    except ValueError:
        return None
    return value if isinstance(value, dict) else None


def require_object(body):
    if not isinstance(body, dict):
        raise ValueError("expected a JSON object")
    return body


def require_token(body):
    token = require_object(body).get("csrf")
    if not isinstance(token, str) or not token:
        raise ValueError("missing csrf")
    return token


def require_etag(response):
    etag = response.headers.get("ETag")
    if not etag:
        raise ValueError("missing ETag")
    return etag


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = "bench-%d" % (((next(_user_numbers) - 1) % 16) + 1)
        self.iterations = 0
        self.csrf = None
        self.cart_id = None

    def request_checked(
        self,
        method,
        url,
        statuses,
        *,
        payload=None,
        headers=None,
        authenticated=False,
        validate=None,
        auto_recover=True,
    ):
        method = method.upper()
        url = checked_url(url)
        operation_headers = dict(headers or {})

        for attempt in range(2):
            request_headers = dict(operation_headers)
            if authenticated and method != "GET":
                if not self.csrf:
                    raise FlowAbort("missing authenticated csrf")
                request_headers["X-CSRF-Token"] = self.csrf

            recovery_reason = None
            failure = None
            result = None
            with self.client.request(
                method,
                url,
                json=payload,
                headers=request_headers,
                allow_redirects=False,
                catch_response=True,
            ) as response:
                body = json_object(response)
                error = body.get("error") if body else None
                if (
                    authenticated
                    and auto_recover
                    and attempt == 0
                    and response.status_code == 401
                    and error in ("expired", "session")
                ):
                    response.success()
                    recovery_reason = error
                elif response.status_code not in statuses:
                    failure = "unexpected HTTP %s%s" % (
                        response.status_code,
                        " (%s)" % error if error else "",
                    )
                    response.failure(failure)
                else:
                    try:
                        result = validate(response, body) if validate else None
                        if method != "GET" and response.status_code < 300 and body:
                            token = body.get("csrf")
                            if isinstance(token, str) and token:
                                self.csrf = token
                    except (ValueError, TypeError, KeyError) as exc:
                        failure = str(exc)
                        response.failure(failure)

            if failure is not None:
                raise FlowAbort(failure)
            if recovery_reason is None:
                return response, body, result

            self.recover_session(recovery_reason)
            if "If-Match" in operation_headers and self.cart_id is not None:
                operation_headers["If-Match"] = self.read_cart_etag(
                    auto_recover=False
                )

        raise FlowAbort("authentication recovery exhausted")

    def login(self):
        def parse_form(response, _body):
            parser = LoginFormParser()
            parser.feed(response.text)
            return parser.csrf()

        _, _, form_token = self.request_checked(
            "GET", "/v2/login-form", {200}, validate=parse_form
        )

        def validate_login(response, body):
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    raise ValueError("login redirect has no Location")
                return checked_url(location, response.url)
            require_token(body)
            if not body.get("user"):
                raise ValueError("login response has no user")
            return None

        response, body, location = self.request_checked(
            "POST",
            "/v2/login",
            {200, 302},
            payload={
                "username": self.username,
                "password": "bench",
                "csrf": form_token,
            },
            validate=validate_login,
        )
        if response.status_code == 302:
            _, body, _ = self.request_checked("GET", location, {200})
            if body and isinstance(body.get("csrf"), str) and body["csrf"]:
                self.csrf = body["csrf"]
        if not self.csrf:
            raise FlowAbort("login did not supply a session csrf")

    def recover_session(self, reason):
        if reason == "expired":
            self.request_checked(
                "POST",
                "/v2/session/renew",
                {200},
                payload={},
                authenticated=True,
                validate=lambda _response, body: require_token(body),
                auto_recover=False,
            )
        else:
            self.csrf = None
            self.login()

        if self.cart_id is not None:
            self.request_checked(
                "POST",
                "/v2/carts/%s/recover" % quote(str(self.cart_id), safe=""),
                {200, 204},
                payload={},
                authenticated=True,
                auto_recover=False,
            )

    def read_cart_etag(self, auto_recover=True):
        _, _, etag = self.request_checked(
            "GET",
            "/v2/carts/%s" % quote(str(self.cart_id), safe=""),
            {200},
            authenticated=True,
            validate=lambda response, _body: require_etag(response),
            auto_recover=auto_recover,
        )
        return etag

    def journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.login()

        def choose_product(_response, body):
            data = require_object(body).get("data")
            if not isinstance(data, dict) or not isinstance(
                data.get("products"), list
            ):
                raise ValueError("invalid catalog")
            for product in data["products"]:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                for variant in product.get("variants") or []:
                    if (
                        isinstance(variant, dict)
                        and variant.get("id") is not None
                        and variant.get("in_stock") is True
                    ):
                        return product["id"], variant["id"]
            raise ValueError("catalog has no in-stock variant")

        _, _, selection = self.request_checked(
            "GET",
            "/v2/catalog",
            {200},
            authenticated=True,
            validate=choose_product,
        )
        product_id, variant_id = selection

        def validate_cart(response, body):
            cart = require_object(body)
            if cart.get("id") is None:
                raise ValueError("cart has no id")
            require_token(cart)
            require_etag(response)
            return cart["id"]

        _, _, self.cart_id = self.request_checked(
            "POST",
            "/v2/carts",
            {201},
            payload={"product_id": product_id, "variant_id": variant_id},
            authenticated=True,
            validate=validate_cart,
        )

        cart_url = "/v2/carts/%s" % quote(str(self.cart_id), safe="")
        etag = self.read_cart_etag()
        response, _, _ = self.request_checked(
            "PATCH",
            cart_url,
            {200, 204, 412},
            payload={"quantity": 2},
            headers={"If-Match": etag},
            authenticated=True,
        )
        if response.status_code == 412:
            etag = self.read_cart_etag()
            response, _, _ = self.request_checked(
                "PATCH",
                cart_url,
                {200, 204},
                payload={"quantity": 2},
                headers={"If-Match": etag},
                authenticated=True,
            )
        etag = response.headers.get("ETag") or self.read_cart_etag()

        def validate_order(_response, body):
            order = require_object(body)
            if order.get("accepted") is not True or order.get("id") is None:
                raise ValueError("order was not accepted")
            require_token(order)

        self.request_checked(
            "POST",
            "/v2/orders",
            {201},
            payload={"cart_id": self.cart_id},
            headers={
                "Idempotency-Key": str(uuid.uuid4()),
                "If-Match": etag,
            },
            authenticated=True,
            validate=validate_order,
        )

    @task
    def run_journey(self):
        global _finished_users
        try:
            self.journey()
        except FlowAbort:
            pass
        finally:
            self.iterations += 1
            if self.iterations >= 2:
                _finished_users += 1
                raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        remaining = 2 - _finished_users
        if remaining <= 0:
            return None
        return remaining, 2
