import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static String jsonString(String value) {
    StringBuilder out = new StringBuilder("\"");
    for (int i = 0; i < value.length(); i++) {
      char c = value.charAt(i);
      switch (c) {
        case '"': out.append("\\\""); break;
        case '\\': out.append("\\\\"); break;
        case '\b': out.append("\\b"); break;
        case '\f': out.append("\\f"); break;
        case '\n': out.append("\\n"); break;
        case '\r': out.append("\\r"); break;
        case '\t': out.append("\\t"); break;
        default:
          if (c < 0x20) {
            out.append(String.format("\\u%04x", (int) c));
          } else {
            out.append(c);
          }
      }
    }
    return out.append('"').toString();
  }

  private static String baseUrl() {
    String configured = System.getenv("BASE_URL");
    return configured == null || configured.isEmpty()
        ? "http://127.0.0.1:8000"
        : configured;
  }

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(baseUrl())
          .disableFollowRedirect();

  private final ScenarioBuilder journey =
      scenario("Select an in-stock variant and order")
          .repeat(2).on(
              exec(session ->
                  session.remove("csrf")
                      .remove("loginCsrf")
                      .remove("loginLocation")
                      .remove("loginStatus")
                      .remove("productIds")
                      .remove("productId")
                      .remove("variantId")
                      .remove("cartId")
                      .remove("cartETag")
                      .set("username", "bench-" + ((session.userId() % 16) + 1))
              )
              .exec(
                  http("login form")
                      .get("/v2/login-form")
                      .check(
                          status().is(200),
                          css("input[name=csrf]", "value").saveAs("loginCsrf")
                      )
              )
              .exitHereIfFailed()
              .exec(
                  http("login")
                      .post("/v2/login")
                      .header("Content-Type", "application/json")
                      .body(StringBody(session ->
                          "{\"username\":" + jsonString(session.getString("username"))
                              + ",\"password\":\"bench\""
                              + ",\"csrf\":" + jsonString(session.getString("loginCsrf"))
                              + "}"
                      ))
                      .check(
                          status().in(200, 302).saveAs("loginStatus"),
                          header("Location").optional().saveAs("loginLocation"),
                          checkIf(session -> session.getInt("loginStatus") == 200)
                              .then(jsonPath("$.csrf").saveAs("csrf"))
                      )
              )
              .exitHereIfFailed()
              .doIf(session -> session.getInt("loginStatus") == 302).then(
                  exec(
                      http("login redirect")
                          .get("#{loginLocation}")
                          .check(
                              status().is(200),
                              jsonPath("$.csrf").saveAs("csrf")
                          )
                  )
              )
              .exitHereIfFailed()
              .exec(
                  http("catalog")
                      .get("/v2/catalog")
                      .check(
                          status().is(200),
                          jsonPath("$.data.products[*].id")
                              .findAll().saveAs("productIds"),
                          jsonPath("$.data.products[*].variants[?(@.in_stock == true)].id")
                              .exists()
                      )
              )
              .exitHereIfFailed()
              .exec(session -> session.set("productIndex", 0))
              .asLongAs(session ->
                  session.getInt("productIndex") < session.getList("productIds").size()
                      && !session.contains("variantId")
              ).on(
                  exec(
                      http("inspect product")
                          .get("/v2/catalog")
                          .check(
                              status().is(200),
                              jsonPath("$.data.products[#{productIndex}].id")
                                  .saveAs("productId"),
                              jsonPath("$.data.products[#{productIndex}].variants[?(@.in_stock == true)].id")
                                  .find().optional().saveAs("variantId")
                          )
                  )
                  .exitHereIfFailed()
                  .exec(session ->
                      session.set("productIndex", session.getInt("productIndex") + 1)
                  )
              )
              .exec(session ->
                  session.contains("productId") && session.contains("variantId")
                      ? session
                      : session.markAsFailed()
              )
              .exitHereIfFailed()
              .exec(
                  http("create cart")
                      .post("/v2/carts")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .body(StringBody(session ->
                          "{\"product_id\":" + jsonString(session.getString("productId"))
                              + ",\"variant_id\":" + jsonString(session.getString("variantId"))
                              + "}"
                      ))
                      .check(
                          status().is(201),
                          jsonPath("$.id").saveAs("cartId"),
                          header("ETag").saveAs("cartETag"),
                          jsonPath("$.csrf").optional().saveAs("csrf")
                      )
              )
              .exitHereIfFailed()
              .exec(
                  http("submit order")
                      .post("/v2/orders")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .header("If-Match", "#{cartETag}")
                      .header("Idempotency-Key", "order-#{cartId}")
                      .body(StringBody(session ->
                          "{\"cart_id\":" + jsonString(session.getString("cartId")) + "}"
                      ))
                      .check(
                          status().is(201),
                          jsonPath("$.accepted").ofBoolean().is(true),
                          jsonPath("$.id").exists(),
                          jsonPath("$.csrf").optional().saveAs("csrf")
                      )
              )
              .exitHereIfFailed()
          );

  public ModelSimulation() {
    setUp(journey.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}
