                              status().is(200),
                              jsonPath("$.data.products[#{productIndex}].id")
                                  .saveAs("productId"),
                              jsonPath("$.data.products[#{productIndex}].variants[?(@.in_stock == true)].id")
                                  .find().optional().saveAs("variantId")
                          )
                  )
                  .exitHereIfFailed()
                  .exec(session ->
                      session.set("productIndex", session.getInt("productIndex") + 1)
                  )
              )
              .exec(session ->
                  session.contains("productId") && session.contains("variantId")
                      ? session
                      : session.markAsFailed()
              )
              .exitHereIfFailed()
              .exec(
                  http("create cart")
                      .post("/v2/carts")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .body(StringBody(session ->
                          "{\"product_id\":" + jsonString(session.getString("productId"))
                              + ",\"variant_id\":" + jsonString(session.getString("variantId"))
                              + "}"
                      ))
                      .check(
                          status().is(201),
                          jsonPath("$.id").saveAs("cartId"),
                          header("ETag").saveAs("cartETag"),
                          jsonPath("$.csrf").optional().saveAs("csrf")
                      )
              )
              .exitHereIfFailed()
              .exec(
                  http("submit order")
                      .post("/v2/orders")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .header("If-Match", "#{cartETag}")
                      .header("Idempotency-Key", "order-#{cartId}")
                      .body(StringBody(session ->
                          "{\"cart_id\":" + jsonString(session.getString("cartId")) + "}"
                      ))
                      .check(
                          status().is(201),
                          jsonPath("$.accepted").ofBoolean().is(true),
                          jsonPath("$.id").exists(),
                          jsonPath("$.csrf").optional().saveAs("csrf")
                      )
              )
              .exitHereIfFailed()
          );

  public ModelSimulation() {
    setUp(journey.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}
