```javascript
import http from 'k6/http';
import { check, fail } from 'k6';
import { parseHTML } from 'k6/html';

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '1m',
    },
  },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

function requireCheck(name, condition) {
  const assertions = {};
  assertions[name] = (value) => value === true;
  if (!check(Boolean(condition), assertions)) fail(name);
}

function json(response) {
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return null;
}

function captureCsrf(state, response) {
  const body = json(response);
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function locationUrl(location) {
  requireCheck('login redirect has a location', typeof location === 'string' && location.length > 0);

  if (/^https?:\/\//i.test(location)) {
    requireCheck(
      'login redirect stays on target',
      location === BASE || location.startsWith(BASE + '/') || location.startsWith(BASE + '?')
    );
    return location;
  }

  requireCheck('login redirect is not scheme-relative', !location.startsWith('//'));
  requireCheck('login redirect has no other scheme', !/^[a-z][a-z0-9+.-]*:/i.test(location));

  if (location.startsWith('/')) return BASE + location;
  if (location.startsWith('?')) return BASE + '/v2/login' + location;
  return BASE + '/v2/' + location;
}

function login(state) {
  state.csrf = null;

  const form = http.get(BASE + '/v2/login-form', { redirects: 0 });
  requireCheck('login form returned 200', form.status === 200);

  let formCsrf = null;
  try {
    formCsrf = parseHTML(form.body).find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    formCsrf = null;
  }
  requireCheck('login form contains csrf', typeof formCsrf === 'string' && formCsrf.length > 0);

  const response = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: state.username, password: 'bench', csrf: formCsrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );
  requireCheck('login returned 200 or 302', response.status === 200 || response.status === 302);
  captureCsrf(state, response);

  if (response.status === 302) {
    const destination = locationUrl(header(response, 'Location'));
    const landing = http.get(destination, { redirects: 0 });
    requireCheck('login redirect destination returned 200', landing.status === 200);
    captureCsrf(state, landing);
  }

  requireCheck('login supplied session csrf', typeof state.csrf === 'string' && state.csrf.length > 0);
}

function postJson(state, path, payload, extraHeaders) {
  return http.post(BASE + path, JSON.stringify(payload), {
    headers: Object.assign(
      { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
      extraHeaders || {}
    ),
    redirects: 0,
  });
}

function recoverSession(state, reason) {
  if (reason === 'expired') {
    const renewal = postJson(state, '/v2/session/renew', {});
    if (renewal.status >= 200 && renewal.status < 300) {
      captureCsrf(state, renewal);
    } else {
      const body = json(renewal);
      if (renewal.status === 401 && body && body.error === 'session') {
        login(state);
      } else {
        requireCheck('expired session renewed', false);
      }
    }
  } else {
    login(state);
  }

  if (state.cartId !== null) {
    const recovery = postJson(
      state,
      '/v2/carts/' + encodeURIComponent(String(state.cartId)) + '/recover',
      {}
    );
    requireCheck('existing cart recovered', recovery.status >= 200 && recovery.status < 300);
    captureCsrf(state, recovery);
  }
}

function authenticated(state, operation, afterRecovery) {
  let response = operation();
  if (response.status === 401) {
    const body = json(response);
    const reason = body && body.error;
    if (reason === 'expired' || reason === 'session') {
      recoverSession(state, reason);
      if (afterRecovery) afterRecovery();
      response = operation();
    }
  }
  if (response.status >= 200 && response.status < 300) captureCsrf(state, response);
  return response;
}

function readCart(state, allowRecovery) {
  const operation = () =>
    http.get(BASE + '/v2/carts/' + encodeURIComponent(String(state.cartId)), {
      redirects: 0,
    });
  const response = allowRecovery ? authenticated(state, operation) : operation();
  requireCheck('cart read returned 200', response.status === 200);
  const etag = header(response, 'ETag');
  requireCheck('cart read supplied ETag', typeof etag === 'string' && etag.length > 0);
  state.etag = etag;
}

export default function () {
  requireCheck('configured target is local shop', BASE === 'http://127.0.0.1:8000');

  const state = {
    username: 'bench-' + __VU,
    csrf: null,
    cartId: null,
    etag: null,
  };

  login(state);

  const catalog = authenticated(state, () =>
    http.get(BASE + '/v2/catalog', { redirects: 0 })
  );
  requireCheck('catalog returned 200', catalog.status === 200);

  const catalogBody = json(catalog);
  const products = catalogBody && catalogBody.data && catalogBody.data.products;
  requireCheck('catalog contains products array', Array.isArray(products));

  let selectedProduct = null;
  let selectedVariant = null;
  for (const product of products) {
    if (!product || product.id === null || product.id === undefined || !Array.isArray(product.variants)) {
      continue;
    }
    for (const variant of product.variants) {
      if (variant && variant.in_stock === true && variant.id !== null && variant.id !== undefined) {
        selectedProduct = product;
        selectedVariant = variant;
        break;
      }
    }
    if (selectedVariant !== null) break;
  }
  requireCheck('an in-stock parent and child were selected', selectedProduct !== null && selectedVariant !== null);

  const cart = authenticated(state, () =>
    postJson(state, '/v2/carts', {
      product_id: selectedProduct.id,
      variant_id: selectedVariant.id,
    })
  );
  requireCheck('cart created', cart.status === 201);
  const cartBody = json(cart);
  requireCheck('cart creation supplied an ID', !!cartBody && cartBody.id !== null && cartBody.id !== undefined);
  state.cartId = cartBody.id;

  readCart(state, true);

  const idempotencyKey = 'order-cart-' + String(state.cartId);
  const order = authenticated(
    state,
    () =>
      postJson(state, '/v2/orders', { cart_id: state.cartId }, {
        'Idempotency-Key': idempotencyKey,
        'If-Match': state.etag,
      }),
    () => readCart(state, false)
  );
  requireCheck('order returned 201', order.status === 201);
  const orderBody = json(order);
  requireCheck(
    'order accepted with an ID',
    !!orderBody && orderBody.accepted === true && orderBody.id !== null && orderBody.id !== undefined
  );
}
