import os
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


_finished_users = 0
_next_user = 0


class JourneyError(Exception):
    pass


def require(condition, message):
    if not condition:
        raise ValueError(message)


def valid_id(value):
    return (
        isinstance(value, (str, int))
        and not isinstance(value, bool)
        and value != ""
    )


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form_action = None
        self.in_form = False
        self.tokens = []

    def handle_starttag(self, tag, attrs):
        attrs = {key.lower(): value for key, value in attrs}
        if tag.lower() == "form":
            self.in_form = True
            self.form_action = attrs.get("action", "")
        elif tag.lower() == "input" and attrs.get("name") == "csrf":
            value = attrs.get("value")
            if value:
                action_path = urlsplit(self.form_action or "").path
                priority = 0 if action_path == "/v2/login" else (
                    1 if self.in_form else 2
                )
                self.tokens.append((priority, value))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.in_form = False
            self.form_action = None

    def token(self):
        require(bool(self.tokens), "login form has no CSRF input")
        return min(self.tokens, key=lambda item: item[0])[1]


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]

    def on_start(self):
        global _next_user
        _next_user += 1
        self.username = f"bench-{_next_user}"
        self.iterations_done = 0
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None

    def call(
        self,
        method,
        path,
        expected,
        *,
        payload=None,
        headers=None,
        authenticated=True,
        validate=None,
        allow_recovery=True,
    ):
        for attempt in range(2):
            request_headers = dict(headers or {})
            if authenticated and method != "GET":
                if not self.csrf:
                    raise JourneyError("missing authenticated CSRF token")
                request_headers["X-CSRF-Token"] = self.csrf
            if "If-Match" in request_headers and self.cart_etag:
                request_headers["If-Match"] = self.cart_etag

            problem = None
            recovery_reason = None
            result = None

            kwargs = {
                "headers": request_headers,
                "catch_response": True,
                "allow_redirects": False,
                "timeout": 10,
            }
            if payload is not None:
                kwargs["json"] = payload

            with self.client.request(method, path, **kwargs) as response:
                try:
                    data = response.json()
                except (ValueError, TypeError):
                    data = None

                if response.status_code == 401 and 401 not in expected:
                    error = data.get("error") if isinstance(data, dict) else None
                    if (
                        authenticated
                        and allow_recovery
                        and attempt == 0
                        and error in ("expired", "session")
                    ):
                        response.success()
                        recovery_reason = error
                    else:
                        problem = f"unexpected 401: {error!r}"
                        response.failure(problem)
                elif response.status_code not in expected:
                    problem = (
                        f"{method} {path}: expected {sorted(expected)}, "
                        f"got {response.status_code}"
                    )
                    response.failure(problem)
                else:
                    try:
                        if validate is not None:
                            result = validate(data, response)
                        else:
                            result = data
                        if isinstance(data, dict):
                            token = data.get("csrf")
                            if isinstance(token, str) and token:
                                self.csrf = token
                        if response.status_code >= 400:
                            response.success()
                    except Exception as exc:
                        problem = f"{method} {path}: {exc}"
                        response.failure(problem)

            if problem:
                raise JourneyError(problem)
            if recovery_reason:
                self.recover_session()
                continue
            return result

        raise JourneyError("operation recovery exhausted")

    def login(self):
        self.csrf = None

        def parse_form(_data, response):
            parser = LoginFormParser()
            parser.feed(response.text)
            return parser.token()

        form_csrf = self.call(
            "GET",
            "/v2/login-form",
            {200},
            authenticated=False,
            validate=parse_form,
            allow_recovery=False,
        )

        def parse_login(data, response):
            if response.status_code == 200:
                require(isinstance(data, dict), "login response is not JSON")
                require(
                    isinstance(data.get("csrf"), str) and bool(data["csrf"]),
                    "login response has no CSRF token",
                )
                require(data.get("user") is not None, "login response has no user")
                return None

            location = response.headers.get("Location")
            require(bool(location), "login redirect has no Location")
            destination = urljoin(response.url, location)
            parsed = urlsplit(destination)
            require(
                parsed.scheme == "http" and parsed.netloc == "127.0.0.1:8000",
                "login redirect points outside the target",
            )
            return destination

        location = self.call(
            "POST",
            "/v2/login",
            {200, 302},
            payload={
                "username": self.username,
                "password": "bench",
                "csrf": form_csrf,
            },
            authenticated=False,
            validate=parse_login,
            allow_recovery=False,
        )

        if location is not None:
            self.call(
                "GET",
                location,
                {200},
                authenticated=False,
                allow_recovery=False,
            )
            if not self.csrf:
                raise JourneyError("login redirect did not provide a CSRF token")

    def recover_session(self):
        def parse_renewal(data, response):
            require(isinstance(data, dict), "renewal response is not JSON")
            if response.status_code == 401:
                require(data.get("error") == "session", "renewal was denied")
                return False
            require(
                isinstance(data.get("csrf"), str) and bool(data["csrf"]),
                "renewal did not provide a CSRF token",
            )
            return True

        renewed = self.call(
            "POST",
            "/v2/session/renew",
            {200, 401},
            payload={},
            validate=parse_renewal,
            allow_recovery=False,
        )
        if not renewed:
            self.login()

        if self.cart_id is not None:
            def parse_recovery(_data, response):
                etag = response.headers.get("ETag")
                if etag:
                    self.cart_etag = etag

            self.call(
                "POST",
                f"/v2/carts/{self.cart_id}/recover",
                {200, 204},
                payload={},
                validate=parse_recovery,
                allow_recovery=False,
            )

    def journey(self):
        self.cart_id = None
        self.cart_etag = None
        self.login()

        def select_variant(data, _response):
            require(isinstance(data, dict), "catalog is not a JSON object")
            nested = data.get("data")
            require(isinstance(nested, dict), "catalog has no data object")
            products = nested.get("products")
            require(isinstance(products, list), "catalog has no products list")

            for product in products:
                if not isinstance(product, dict) or not valid_id(product.get("id")):
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("in_stock") is True
                        and valid_id(variant.get("id"))
                    ):
                        return product["id"], variant["id"]
            raise ValueError("catalog has no in-stock variant")

        product_id, variant_id = self.call(
            "GET", "/v2/catalog", {200}, validate=select_variant
        )

        def parse_cart(data, response):
            require(isinstance(data, dict), "cart response is not JSON")
            require(valid_id(data.get("id")), "cart response has no ID")
            return data["id"], response.headers.get("ETag")

        self.cart_id, self.cart_etag = self.call(
            "POST",
            "/v2/carts",
            {201},
            payload={"product_id": product_id, "variant_id": variant_id},
            validate=parse_cart,
        )

        order_headers = {"Idempotency-Key": str(uuid.uuid4())}
        if self.cart_etag:
            order_headers["If-Match"] = self.cart_etag

        def parse_order(data, _response):
            require(isinstance(data, dict), "order response is not JSON")
            require(data.get("accepted") is True, "order was not accepted")
            require(valid_id(data.get("id")), "order response has no ID")

        self.call(
            "POST",
            "/v2/orders",
            {201},
            payload={"cart_id": self.cart_id},
            headers=order_headers,
            validate=parse_order,
        )

    @task
    def run_journey(self):
        global _finished_users
        try:
            self.journey()
        except JourneyError:
            _finished_users += 1
            raise StopUser()

        self.iterations_done += 1
        if self.iterations_done >= 2:
            _finished_users += 1
            raise StopUser()


class TwoUserShape(LoadTestShape):
    def tick(self):
        if _finished_users >= 2:
            return None
        return (2 - _finished_users, 2)
