import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

public class ModelSimulation extends Simulation {
  private static final String BASE_URL =
      System.getenv("BASE_URL") == null || System.getenv("BASE_URL").isEmpty()
          ? "http://127.0.0.1:8000"
          : System.getenv("BASE_URL");

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(BASE_URL).disableFollowRedirect();

  private final ScenarioBuilder journey =
      scenario("Paginated checkout")
          .repeat(2).on(
              exec(flushCookieJar())
                  .exec(session -> session
                      .remove("csrf")
                      .remove("newCsrf")
                      .remove("loginLocation")
                      .remove("productId")
                      .remove("variantId")
                      .remove("cartId")
                      .remove("orderId")
                      .set("username",
                          "bench-" + (Math.floorMod(session.userId() - 1, 16) + 1)))

                  .exec(
                      http("Login form")
                          .get("/v2/login-form")
                          .check(
                              status().is(200),
                              css("input[name=csrf]", "value").saveAs("loginCsrf")
                          )
                  )
                  .exitHereIfFailed()

                  .exec(
                      http("Login")
                          .post("/v2/login")
                          .asJson()
                          .body(StringBody(
                              "{\"username\":\"#{username}\","
                                  + "\"password\":\"bench\","
                                  + "\"csrf\":\"#{loginCsrf}\"}"))
                          .check(
                              status().in(200, 302),
                              status().saveAs("loginStatus"),
                              checkIf((response, session) -> response.status().code() == 200)
                                  .then(jsonPath("$.csrf").saveAs("csrf")),
                              checkIf((response, session) -> response.status().code() == 302)
                                  .then(header("Location").saveAs("loginLocation"))
                          )
                  )
                  .exitHereIfFailed()
                  .doIf(session -> session.getInt("loginStatus") == 302).then(
                      exec(
                          http("Login redirect")
                              .get("#{loginLocation}")
                              .check(
                                  status().is(200),
                                  jsonPath("$.csrf").saveAs("csrf")
                              )
                      )
                  )
                  .exitHereIfFailed()

                  .exec(session -> session
                      .set("cursor", "/v2/catalog/page")
                      .set("pageCount", 0))
                  .asLongAs(session ->
                      session.getInt("pageCount") < 3
                          && !session.contains("variantId")
                          && !session.getString("cursor").isEmpty()
                  ).on(
                      exec(session -> session
                          .remove("pageProduct")
                          .remove("pageVariant")
                          .remove("pageNext"))
                          .exec(
                              http("Catalog page")
                                  .get("#{cursor}")
                                  .check(
                                      status().is(200),
                                      jsonPath("$.data.products[0].id")
                                          .saveAs("pageProduct"),
                                      jsonPath(
                                          "$.data.products[0].variants[?(@.in_stock == true)].id")
                                          .find()
                                          .optional()
                                          .saveAs("pageVariant"),
                                      jsonPath("$.next")
                                          .optional()
                                          .saveAs("pageNext")
                                  )
                          )
                          .exitHereIfFailed()
                          .exec(session -> {
                            String next = session.contains("pageNext")
                                ? session.getString("pageNext") : "";
                            if (next == null || next.isEmpty()
                                || "null".equals(next)
                                || next.startsWith("//")
                                || next.contains("://")) {
                              next = "";
                            }

                            session = session
                                .set("cursor", next)
                                .set("pageCount", session.getInt("pageCount") + 1);

                            if (session.contains("pageVariant")) {
                              String variant = session.getString("pageVariant");
                              if (variant != null && !variant.isEmpty()
                                  && !"null".equals(variant)) {
                                session = session
                                    .set("productId", session.getString("pageProduct"))
                                    .set("variantId", variant);
                              }
                            }
                            return session;
                          })
                  )
                  .exec(session ->
                      session.contains("productId") && session.contains("variantId")
                          ? session : session.markAsFailed())
                  .exitHereIfFailed()

                  .exec(session -> session.remove("newCsrf"))
                  .exec(
                      http("Create cart")
                          .post("/v2/carts")
                          .header("X-CSRF-Token", "#{csrf}")
                          .asJson()
                          .body(StringBody(
                              "{\"product_id\":\"#{productId}\","
                                  + "\"variant_id\":\"#{variantId}\"}"))
                          .check(
                              status().is(201),
                              jsonPath("$.id").saveAs("cartId"),
                              header("ETag").saveAs("cartETag"),
                              jsonPath("$.csrf").optional().saveAs("newCsrf")
                          )
                  )
                  .exitHereIfFailed()
                  .exec(session -> {
                    if (session.contains("newCsrf")) {
                      String token = session.getString("newCsrf");
                      if (token != null && !token.isEmpty() && !"null".equals(token)) {
                        session = session.set("csrf", token);
                      }
                    }
                    return session.remove("newCsrf");
                  })

                  .exec(
                      http("Create order")
                          .post("/v2/orders")
                          .header("X-CSRF-Token", "#{csrf}")
                          .header("Idempotency-Key", "order-#{cartId}")
                          .header("If-Match", "#{cartETag}")
                          .asJson()
                          .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                          .check(
                              status().is(201),
                              jsonPath("$.accepted").is("true"),
                              jsonPath("$.id").saveAs("orderId"),
                              jsonPath("$.csrf").optional().saveAs("newCsrf")
                          )
                  )
                  .exitHereIfFailed()
                  .exec(session -> {
                    if (session.contains("newCsrf")) {
                      String token = session.getString("newCsrf");
                      if (token != null && !token.isEmpty() && !"null".equals(token)) {
                        session = session.set("csrf", token);
                      }
                    }
                    return session.remove("newCsrf");
                  })
          );

  public ModelSimulation() {
    setUp(journey.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}
