```javascript
import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

export const options = {
  scenarios: {
    pagination: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

function json(response) {
  try {
    return response ? response.json() : null;
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  if (!response || !response.headers) return null;
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return null;
}

function hasId(value) {
  return value !== null && value !== undefined && String(value).length > 0;
}

function retainCsrf(state, response) {
  const body = json(response);
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function resolveLink(link, currentUrl) {
  if (typeof link !== 'string' || !link || /[\s\\]/.test(link)) return null;
  if (/^https?:\/\//i.test(link)) {
    if (link === BASE || link.startsWith(BASE + '/') || link.startsWith(BASE + '?')) {
      return link;
    }
    return null;
  }
  if (link.startsWith('//') || /^[a-z][a-z0-9+.-]*:/i.test(link)) return null;
  if (link.startsWith('/')) return BASE + link;

  const current = currentUrl.split('#')[0];
  if (link.startsWith('?')) return current.split('?')[0] + link;
  const path = current.split('?')[0];
  return path.substring(0, path.lastIndexOf('/') + 1) + link;
}

function clearCookies() {
  const jar = http.cookieJar();
  const urls = [
    BASE + '/',
    BASE + '/v2/login-form',
    BASE + '/v2/catalog/page',
    BASE + '/v2/carts',
  ];
  for (const url of urls) {
    const cookies = jar.cookiesForURL(url);
    for (const name in cookies) jar.clear(url, name);
  }
}

function login(state, freshJourney) {
  if (freshJourney) clearCookies();

  const form = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login_form' },
  });
  if (!check(form, { 'login form returned 200': (r) => r.status === 200 })) {
    return false;
  }

  let csrf = null;
  try {
    csrf = parseHTML(form.body).find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    csrf = null;
  }
  if (!check(csrf, { 'login form has csrf': (v) => typeof v === 'string' && v.length > 0 })) {
    return false;
  }

  const response = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: 'bench-' + __VU, password: 'bench', csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );
  if (!check(response, {
    'login returned 200 or 302': (r) => r.status === 200 || r.status === 302,
  })) {
    return false;
  }

  let result = response;
  if (response.status === 302) {
    const location = resolveLink(header(response, 'Location'), BASE + '/v2/login');
    if (!check(location, { 'login redirect has an allowed location': (v) => !!v })) {
      return false;
    }
    result = http.get(location, {
      redirects: 0,
      tags: { name: 'login_redirect' },
    });
    if (!check(result, { 'login redirect returned 200': (r) => r.status === 200 })) {
      return false;
    }
  }

  const body = json(result);
  if (!check(body, {
    'login returned csrf': (b) => !!b && typeof b.csrf === 'string' && b.csrf.length > 0,
  })) {
    return false;
  }
  state.csrf = body.csrf;
  return true;
}

function recoverSession(state, reason) {
  if (reason === 'expired') {
    const renewal = http.post(BASE + '/v2/session/renew', '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
      tags: { name: 'session_renew' },
    });
    if (!check(renewal, { 'session renewal returned 200': (r) => r.status === 200 })) {
      return false;
    }
    retainCsrf(state, renewal);
  } else if (reason === 'session') {
    if (!login(state, false)) return false;
  } else {
    return false;
  }

  if (hasId(state.cartId)) {
    const cartUrl = BASE + '/v2/carts/' + encodeURIComponent(String(state.cartId));
    const recovery = http.post(cartUrl + '/recover', '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
      tags: { name: 'cart_recover' },
    });
    if (!check(recovery, { 'cart recovery returned 200': (r) => r.status === 200 })) {
      return false;
    }
    retainCsrf(state, recovery);

    const cart = http.get(cartUrl, {
      redirects: 0,
      tags: { name: 'cart_read' },
    });
    if (!check(cart, { 'recovered cart returned 200': (r) => r.status === 200 })) {
      return false;
    }
    state.etag = header(cart, 'ETag');
    if (!check(state.etag, { 'recovered cart has ETag': (v) => !!v })) return false;
  }
  return true;
}

function authenticatedRequest(state, method, url, payload, tag, extraHeaders) {
  for (let attempt = 0; attempt < 2; attempt++) {
    const headers = {};
    if (method !== 'GET') {
      headers['Content-Type'] = 'application/json';
      headers['X-CSRF-Token'] = state.csrf;
    }
    if (extraHeaders) {
      const extra = extraHeaders(state);
      for (const key in extra) {
        if (extra[key] !== null && extra[key] !== undefined) headers[key] = extra[key];
      }
    }

    const response = http.request(
      method,
      url,
      payload === null ? null : JSON.stringify(payload),
      { headers, redirects: 0, tags: { name: tag } }
    );

    if (response.status === 401 && attempt === 0) {
      const body = json(response);
      const reason = body && body.error;
      if (reason === 'expired' || reason === 'session') {
        if (!recoverSession(state, reason)) return null;
        continue;
      }
    }

    if (method !== 'GET' && response.status >= 200 && response.status < 300) {
      retainCsrf(state, response);
    }
    return response;
  }
  return null;
}

export default function () {
  const state = { csrf: null, cartId: null, etag: null };
  if (!login(state, true)) return;

  let url = BASE + '/v2/catalog/page';
  const visited = {};
  let selected = null;

  for (let page = 0; page < 3; page++) {
    if (!check(url, { 'catalog cursor is valid and not repeated': (v) => !!v && !visited[v] })) {
      return;
    }
    visited[url] = true;

    const response = authenticatedRequest(state, 'GET', url, null, 'catalog_page');
    if (!check(response || {}, { 'catalog page returned 200': (r) => r.status === 200 })) {
      return;
    }

    const body = json(response);
    if (!check(body, {
      'catalog page has products and next': (b) =>
        !!b && !!b.data && Array.isArray(b.data.products) &&
        Object.prototype.hasOwnProperty.call(b, 'next'),
    })) {
      return;
    }

    for (const product of body.data.products) {
      if (!product || !hasId(product.id) || !Array.isArray(product.variants)) continue;
      for (const variant of product.variants) {
        if (variant && hasId(variant.id) && variant.in_stock === true) {
          selected = { product_id: product.id, variant_id: variant.id };
          break;
        }
      }
      if (selected) break;
    }

    if (selected || body.next === null) break;
    url = resolveLink(body.next, url);
  }

  if (!check(selected, { 'eligible in-stock variant found within three pages': (v) => !!v })) {
    return;
  }

  const cartResponse = authenticatedRequest(
    state, 'POST', BASE + '/v2/carts', selected, 'cart_create'
  );
  const cart = json(cartResponse);
  if (!check(cartResponse || {}, { 'cart created': (r) => r.status === 201 }) ||
      !check(cart, { 'cart ID extracted': (b) => !!b && hasId(b.id) })) {
    return;
  }
  state.cartId = cart.id;
  state.etag = header(cartResponse, 'ETag');
  if (!check(state.etag, { 'created cart has ETag': (v) => !!v })) return;

  const idempotencyKey = 'pagination-order-' + String(state.cartId);
  const orderResponse = authenticatedRequest(
    state,
    'POST',
    BASE + '/v2/orders',
    { cart_id: state.cartId },
    'order_create',
    (s) => ({ 'Idempotency-Key': idempotencyKey, 'If-Match': s.etag })
  );
  const order = json(orderResponse);
  if (!check(orderResponse || {}, { 'order returned 201': (r) => r.status === 201 }) ||
      !check(order, {
        'order accepted and ID extracted': (b) => !!b && b.accepted === true && hasId(b.id),
      })) {
    return;
  }

  console.log(JSON.stringify({ cart_id: state.cartId, order_id: order.id }));
}
