import os
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"].rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

_started_users = 0
_finished_users = 0


class JourneyError(Exception):
    pass


class CSRFParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.values = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attributes = dict(attrs)
        if attributes.get("name") == "csrf" and attributes.get("value"):
            self.values.append(attributes["value"])

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def require(condition, message):
    if not condition:
        raise ValueError(message)


def json_object(response):
    body = response.json()
    require(isinstance(body, dict), "Expected a JSON object")
    return body


def valid_id(value):
    return value is not None and value != "" and not isinstance(value, bool)


def local_link(current_path, link):
    require(isinstance(link, str) and bool(link), "Missing dynamic link")
    resolved = urlsplit(urljoin(BASE_URL + current_path, link))
    require(
        resolved.scheme == "http" and resolved.netloc == "127.0.0.1:8000",
        "Dynamic link points outside the target",
    )
    require(not resolved.fragment, "Dynamic link contains a fragment")
    return resolved.path + (("?" + resolved.query) if resolved.query else "")


class ShopUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        global _started_users
        _started_users += 1
        self.username = "bench-{}".format(_started_users)
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.iterations_done = 0
        self.finished = False

    def finish(self):
        global _finished_users
        if not self.finished:
            self.finished = True
            _finished_users += 1
        raise StopUser()

    def request_checked(
        self,
        method,
        path,
        statuses,
        check,
        *,
        payload=None,
        headers=None,
        authenticated=True,
        recover=True,
        name=None,
    ):
        for attempt in range(2):
            request_headers = dict(headers or {})
            if authenticated and method != "GET":
                request_headers["X-CSRF-Token"] = self.csrf or ""
                if "If-Match" in request_headers and self.cart_etag:
                    request_headers["If-Match"] = self.cart_etag

            recovery_reason = None
            failure = None
            result = None

            with self.client.request(
                method,
                path,
                json=payload,
                headers=request_headers,
                name=name,
                allow_redirects=False,
                catch_response=True,
                timeout=10,
            ) as response:
                if response.status_code == 401 and authenticated:
                    try:
                        error = json_object(response).get("error")
                    except Exception:
                        error = None
                    if recover and attempt == 0 and error in ("expired", "session"):
                        response.success()
                        recovery_reason = error
                    else:
                        failure = "Unexpected or repeated 401: {}".format(error)
                        response.failure(failure)
                elif response.status_code not in statuses:
                    failure = "Unexpected HTTP status {}".format(response.status_code)
                    response.failure(failure)
                else:
                    try:
                        result = check(response)
                        if authenticated and method != "GET":
                            try:
                                body = response.json()
                            except ValueError:
                                body = None
                            if isinstance(body, dict) and body.get("csrf"):
                                self.csrf = body["csrf"]
                    except Exception as exc:
                        failure = "Assertion failed: {}".format(exc)
                        response.failure(failure)

            if failure:
                raise JourneyError(failure)
            if recovery_reason:
                self.recover_session(recovery_reason)
                continue
            return result

        raise JourneyError("Recovery retry exhausted")

    def login(self):
        self.csrf = None

        def check_form(response):
            parser = CSRFParser()
            parser.feed(response.text)
            require(bool(parser.values), "Login form has no csrf input")
            return parser.values[0]

        form_csrf = self.request_checked(
            "GET", "/v2/login-form", (200,), check_form,
            authenticated=False, recover=False,
        )

        def check_login(response):
            if response.status_code == 302:
                location = response.headers.get("Location")
                path = local_link("/v2/login", location)
                try:
                    body = response.json()
                except ValueError:
                    body = None
                if isinstance(body, dict) and body.get("csrf"):
                    self.csrf = body["csrf"]
                return path

            body = json_object(response)
            require(bool(body.get("csrf")), "Login did not return csrf")
            require(body.get("user") is not None, "Login did not return user")
            self.csrf = body["csrf"]
            return None

        redirect = self.request_checked(
            "POST",
            "/v2/login",
            (200, 302),
            check_login,
            payload={"username": self.username, "password": "bench", "csrf": form_csrf},
            authenticated=False,
            recover=False,
        )

        if redirect:
            def check_redirect(response):
                try:
                    body = response.json()
                except ValueError:
                    body = None
                if isinstance(body, dict) and body.get("csrf"):
                    self.csrf = body["csrf"]
                require(bool(self.csrf), "Login redirect did not supply csrf")

            self.request_checked(
                "GET", redirect, (200,), check_redirect,
                authenticated=False, recover=False, name="/v2/login-redirect",
            )

    def recover_session(self, reason):
        if reason == "expired":
            def check_renew(response):
                body = json_object(response)
                require(bool(body.get("csrf")), "Renew did not return csrf")

            self.request_checked(
                "POST", "/v2/session/renew", (200,), check_renew,
                payload={}, recover=False,
            )
        else:
            self.login()

        if self.cart_id is not None:
            def check_recover(response):
                etag = response.headers.get("ETag")
                if etag:
                    self.cart_etag = etag

            self.request_checked(
                "POST",
                "/v2/carts/{}/recover".format(self.cart_id),
                (200, 201, 204),
                check_recover,
                payload={},
                recover=False,
                name="/v2/carts/[id]/recover",
            )

    def find_item(self):
        path = "/v2/catalog/page"
        seen = set()

        for page_number in range(1, 4):
            seen.add(path)

            def check_page(response):
                body = json_object(response)
                require("next" in body, "Catalog page has no next field")
                data = body.get("data")
                if isinstance(data, dict) and "products" in data:
                    products = data["products"]
                elif isinstance(data, dict) and "product" in data:
                    products = [data["product"]]
                elif "product" in body:
                    products = [body["product"]]
                else:
                    raise ValueError("Catalog page has no products")

                require(isinstance(products, list), "Products is not a list")
                selected = None
                for product in products:
                    require(isinstance(product, dict), "Invalid product")
                    require(valid_id(product.get("id")), "Product has no ID")
                    variants = product.get("variants")
                    require(isinstance(variants, list), "Invalid variants")
                    for variant in variants:
                        require(isinstance(variant, dict), "Invalid variant")
                        require(valid_id(variant.get("id")), "Variant has no ID")
                        require(
                            isinstance(variant.get("in_stock"), bool),
                            "Invalid stock flag",
                        )
                        if variant["in_stock"]:
                            selected = (product["id"], variant["id"])
                            break
                    if selected:
                        break

                if selected:
                    return selected, None

                next_link = body["next"]
                require(next_link is not None, "No eligible item in catalog")
                require(page_number < 3, "Catalog traversal exceeded three pages")
                next_path = local_link(path, next_link)
                require(next_path not in seen, "Catalog cursor cycle")
                return None, next_path

            selected, next_path = self.request_checked(
                "GET", path, (200,), check_page, name="/v2/catalog/page"
            )
            if selected:
                return selected
            path = next_path

        raise JourneyError("No eligible item found")

    def journey(self):
        self.cart_id = None
        self.cart_etag = None
        self.login()
        product_id, variant_id = self.find_item()

        def check_cart(response):
            body = json_object(response)
            require(valid_id(body.get("id")), "Cart has no ID")
            etag = response.headers.get("ETag")
            require(bool(etag), "Cart has no ETag")
            return body["id"], etag

        self.cart_id, self.cart_etag = self.request_checked(
            "POST",
            "/v2/carts",
            (201,),
            check_cart,
            payload={"product_id": product_id, "variant_id": variant_id},
        )

        idempotency_key = uuid.uuid4().hex

        def check_order(response):
            body = json_object(response)
            require(body.get("accepted") is True, "Order was not accepted")
            require(valid_id(body.get("id")), "Order has no ID")
            return body["id"]

        order_id = self.request_checked(
            "POST",
            "/v2/orders",
            (201,),
            check_order,
            payload={"cart_id": self.cart_id},
            headers={
                "Idempotency-Key": idempotency_key,
                "If-Match": self.cart_etag,
            },
        )
        self.last_cart_id = self.cart_id
        self.last_order_id = order_id

    @task
    def run_iteration(self):
        if self.iterations_done >= 2:
            self.finish()
        try:
            self.journey()
        except JourneyError:
            self.finish()
        self.iterations_done += 1
        if self.iterations_done >= 2:
            self.finish()


class JourneyShape(LoadTestShape):
    def tick(self):
        if _finished_users >= 2 or self.get_run_time() >= 120:
            return None
        return (2, 2)
