import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static String jsonValue(Object value) {
    if (value == null) {
      return "null";
    }
    if (value instanceof Number || value instanceof Boolean) {
      return value.toString();
    }

    String text = value.toString();
    StringBuilder result = new StringBuilder("\"");
    for (int i = 0; i < text.length(); i++) {
      char c = text.charAt(i);
      switch (c) {
        case '"': result.append("\\\""); break;
        case '\\': result.append("\\\\"); break;
        case '\b': result.append("\\b"); break;
        case '\f': result.append("\\f"); break;
        case '\n': result.append("\\n"); break;
        case '\r': result.append("\\r"); break;
        case '\t': result.append("\\t"); break;
        default:
          if (c < 0x20) {
            result.append(String.format("\\u%04x", (int) c));
          } else {
            result.append(c);
          }
      }
    }
    return result.append('"').toString();
  }

  private static Session selectInStockVariant(Session session) {
    Object productsValue = session.get("products");
    if (!(productsValue instanceof List)) {
      return session.markAsFailed();
    }

    for (Object productValue : (List<?>) productsValue) {
      if (!(productValue instanceof Map)) {
        continue;
      }
      Map<?, ?> product = (Map<?, ?>) productValue;
      Object productId = product.get("id");
      Object variantsValue = product.get("variants");
      if (productId == null || !(variantsValue instanceof List)) {
        continue;
      }

      for (Object variantValue : (List<?>) variantsValue) {
        if (!(variantValue instanceof Map)) {
          continue;
        }
        Map<?, ?> variant = (Map<?, ?>) variantValue;
        Object variantId = variant.get("id");
        if (variantId != null && Boolean.TRUE.equals(variant.get("in_stock"))) {
          return session.set("productId", productId).set("variantId", variantId);
        }
      }
    }
    return session.markAsFailed();
  }

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(System.getenv("BASE_URL"))
          .disableFollowRedirect()
          .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

  private final ScenarioBuilder scenario =
      scenario("Conditional cart update")
          .exec(session ->
              session.set("username",
                  "bench-" + (Math.floorMod(session.userId() - 1, 16) + 1)))
          .repeat(2).on(
              exec(session -> session
                  .remove("loginCsrf")
                  .remove("loginLocation")
                  .remove("cartId")
                  .remove("etag")
                  .remove("products")
                  .remove("productId")
                  .remove("variantId"))

              .exec(
                  http("Login form")
                      .get("/v2/login-form")
                      .check(
                          status().is(200),
                          css("input[name=csrf]", "value").saveAs("formCsrf")
                      )
              )
              .exitHereIfFailed()

              .exec(
                  http("Login")
                      .post("/v2/login")
                      .header("Content-Type", "application/json")
                      .body(StringBody(session ->
                          "{\"username\":" + jsonValue(session.getString("username"))
                              + ",\"password\":\"bench\""
                              + ",\"csrf\":" + jsonValue(session.getString("formCsrf"))
                              + "}"))
                      .check(
                          status().in(200, 302),
                          status().saveAs("loginStatus"),
                          header("Location").optional().saveAs("loginLocation"),
                          regex("\"csrf\"\\s*:\\s*\"([^\"\\\\]*)\"")
                              .optional().saveAs("loginCsrf")
                      )
              )
              .exitHereIfFailed()

              .doIf(session -> session.getInt("loginStatus") == 302).then(
                  exec(
                      http("Login redirect")
                          .get("#{loginLocation}")
                          .check(
                              status().is(200),
                              jsonPath("$.csrf").saveAs("csrf")
                          )
                  ).exitHereIfFailed()
              )
              .doIf(session -> session.getInt("loginStatus") == 200).then(
                  exec(session -> {
                    if (!session.contains("loginCsrf")) {
                      return session.markAsFailed();
                    }
                    return session.set("csrf", session.getString("loginCsrf"));
                  }).exitHereIfFailed()
              )

              .exec(
                  http("Catalog")
                      .get("/v2/catalog")
                      .check(
                          status().is(200),
                          jsonPath("$.data.products").ofType(List.class).saveAs("products")
                      )
              )
              .exitHereIfFailed()
              .exec(ModelSimulation::selectInStockVariant)
              .exitHereIfFailed()

              .exec(
                  http("Create cart")
                      .post("/v2/carts")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .body(StringBody(session ->
                          "{\"product_id\":" + jsonValue(session.get("productId"))
                              + ",\"variant_id\":" + jsonValue(session.get("variantId"))
                              + "}"))
                      .check(
                          status().is(201),
                          jsonPath("$.id").saveAs("cartId"),
                          jsonPath("$.csrf").optional().saveAs("csrf"),
                          header("ETag").saveAs("etag")
                      )
              )
              .exitHereIfFailed()

              .exec(
                  http("Update cart")
                      .patch("/v2/carts/#{cartId}")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .header("If-Match", "#{etag}")
                      .body(StringBody("{\"quantity\":2}"))
                      .check(
                          status().in(200, 412),
                          status().saveAs("updateStatus"),
                          regex("\"csrf\"\\s*:\\s*\"([^\"\\\\]*)\"")
                              .optional().saveAs("csrf")
                      )
              )
              .exitHereIfFailed()

              .doIf(session -> session.getInt("updateStatus") == 412).then(
                  exec(
                      http("Re-read cart after conflict")
                          .get("/v2/carts/#{cartId}")
                          .check(
                              status().is(200),
                              header("ETag").saveAs("etag")
                          )
                  )
                  .exitHereIfFailed()
                  .exec(
                      http("Retry cart update")
                          .patch("/v2/carts/#{cartId}")
                          .header("Content-Type", "application/json")
                          .header("X-CSRF-Token", "#{csrf}")
                          .header("If-Match", "#{etag}")
                          .body(StringBody("{\"quantity\":2}"))
                          .check(
                              status().is(200),
                              jsonPath("$.csrf").optional().saveAs("csrf")
                          )
                  )
                  .exitHereIfFailed()
              )

              .exec(
                  http("Read updated cart revision")
                      .get("/v2/carts/#{cartId}")
                      .check(
                          status().is(200),
                          header("ETag").saveAs("etag")
                      )
              )
              .exitHereIfFailed()

              .exec(
                  http("Create order")
                      .post("/v2/orders")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .header("If-Match", "#{etag}")
                      .header("Idempotency-Key", "order-#{cartId}")
                      .body(StringBody(session ->
                          "{\"cart_id\":" + jsonValue(session.get("cartId")) + "}"))
                      .check(
                          status().is(201),
                          jsonPath("$.accepted").ofType(Boolean.class).is(true),
                          jsonPath("$.id").exists(),
                          jsonPath("$.csrf").optional().saveAs("csrf")
                      )
              )
              .exitHereIfFailed()
          );

  {
    setUp(scenario.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}

