                  .remove("cartId")
                  .remove("etag")
                  .remove("productIds")
                  .remove("productId")
                  .remove("variantId"))

              .exec(
                  http("Login form")
                      .get("/v2/login-form")
                      .check(
                          status().is(200),
                          css("input[name=csrf]", "value").saveAs("formCsrf")
                      )
              )
              .exitHereIfFailed()

              .exec(
                  http("Login")
                      .post("/v2/login")
                      .header("Content-Type", "application/json")
                      .body(StringBody(session ->
                          "{\"username\":" + jsonValue(session.getString("username"))
                              + ",\"password\":\"bench\""
                              + ",\"csrf\":" + jsonValue(session.getString("formCsrf"))
                              + "}"))
                      .check(
                          status().in(200, 302),
                          status().saveAs("loginStatus"),
                          header("Location").optional().saveAs("loginLocation"),
                          regex("\"csrf\"\\s*:\\s*\"([^\"\\\\]*)\"")
                              .optional().saveAs("loginCsrf")
                      )
              )
              .exitHereIfFailed()

              .doIf(session -> session.getInt("loginStatus") == 302).then(
                  exec(
                      http("Login redirect")
                          .get("#{loginLocation}")
                          .check(
                              status().is(200),
                              jsonPath("$.csrf").saveAs("csrf")
                          )
                  ).exitHereIfFailed()
              )
              .doIf(session -> session.getInt("loginStatus") == 200).then(
                  exec(session -> {
                    if (!session.contains("loginCsrf")) {
                      return session.markAsFailed();
                    }
                    return session.set("csrf", session.getString("loginCsrf"));
                  }).exitHereIfFailed()
              )

              .exec(
                  http("Catalog")
                      .get("/v2/catalog")
                      .check(
                          status().is(200),
                          jsonPath("$.data.products[*].id")
                              .findAll().saveAs("productIds")
                      )
              )
              .exitHereIfFailed()
              .exec(session -> session.set("productIndex", 0))
              .asLongAs(session ->
                  !session.contains("variantId")
                      && session.getInt("productIndex")
                          < ((List<?>) session.get("productIds")).size()
              ).on(
                  exec(
                      http("Find in-stock variant")
                          .get("/v2/catalog")
                          .check(
                              status().is(200),
                              jsonPath("$.data.products[#{productIndex}].variants[?(@.in_stock == true)].id")
                                  .find().optional().saveAs("variantId")
                          )
                  )
                  .exitHereIfFailed()
                  .exec(session -> {
                    int index = session.getInt("productIndex");
                    if (session.contains("variantId")) {
                      List<?> ids = session.get("productIds");
                      session = session.set("productId", ids.get(index));
                    }
                    return session.set("productIndex", index + 1);
                  })
              )
              .exec(session -> {
                if (!session.contains("productId") || !session.contains("variantId")) {
                  return session.markAsFailed();
                }
                return session;
              })
              .exitHereIfFailed()

              .exec(
                  http("Create cart")
                      .post("/v2/carts")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .body(StringBody(session ->
                          "{\"product_id\":" + jsonValue(session.get("productId"))
                              + ",\"variant_id\":" + jsonValue(session.get("variantId"))
                              + "}"))
                      .check(
                          status().is(201),
                          jsonPath("$.id").saveAs("cartId"),
                          jsonPath("$.csrf").optional().saveAs("csrf"),
                          header("ETag").saveAs("etag")
                      )
              )
              .exitHereIfFailed()

              .exec(
                  http("Update cart")
                      .patch("/v2/carts/#{cartId}")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .header("If-Match", "#{etag}")
                      .body(StringBody("{\"quantity\":2}"))
                      .check(
                          status().in(200, 412),
                          status().saveAs("updateStatus"),
                          regex("\"csrf\"\\s*:\\s*\"([^\"\\\\]*)\"")
                              .optional().saveAs("csrf")
                      )
              )
              .exitHereIfFailed()

              .doIf(session -> session.getInt("updateStatus") == 412).then(
                  exec(
                      http("Re-read cart after conflict")
                          .get("/v2/carts/#{cartId}")
                          .check(
                              status().is(200),
                              header("ETag").saveAs("etag")
                          )
                  )
                  .exitHereIfFailed()
                  .exec(
                      http("Retry cart update")
                          .patch("/v2/carts/#{cartId}")
                          .header("Content-Type", "application/json")
                          .header("X-CSRF-Token", "#{csrf}")
                          .header("If-Match", "#{etag}")
                          .body(StringBody("{\"quantity\":2}"))
                          .check(
                              status().is(200),
                              jsonPath("$.csrf").optional().saveAs("csrf")
                          )
                  )
                  .exitHereIfFailed()
              )

              .exec(
                  http("Read updated cart revision")
                      .get("/v2/carts/#{cartId}")
                      .check(
                          status().is(200),
                          header("ETag").saveAs("etag")
                      )
              )
              .exitHereIfFailed()

              .exec(
                  http("Create order")
                      .post("/v2/orders")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .header("If-Match", "#{etag}")
                      .header("Idempotency-Key", "order-#{cartId}")
                      .body(StringBody(session ->
                          "{\"cart_id\":" + jsonValue(session.get("cartId")) + "}"))
                      .check(
                          status().is(201),
                          jsonPath("$.accepted").is("true"),
                          jsonPath("$.id").exists(),
                          jsonPath("$.csrf").optional().saveAs("csrf")
                      )
              )
              .exitHereIfFailed()
          );

  {
    setUp(scenario.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}

import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

function json(res) {
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function header(res, name) {
  const wanted = name.toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === wanted) return res.headers[key];
  }
  return null;
}

function rememberCsrf(state, res) {
  const body = json(res);
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function locationUrl(location, requestPath) {
  if (!location) return null;
  if (/^https?:\/\//i.test(location)) {
    return location === BASE || location.indexOf(BASE + '/') === 0 ||
      location.indexOf(BASE + '?') === 0 ? location : null;
  }
  if (location.indexOf('//') === 0) return null;
  if (location.charAt(0) === '/') return BASE + location;
  if (location.charAt(0) === '?') return BASE + requestPath + location;
  const directory = requestPath.slice(0, requestPath.lastIndexOf('/') + 1);
  return BASE + directory + location;
}

function login(state) {
  state.csrf = null;
  const form = http.get(BASE + '/v2/login-form', { redirects: 0 });
  if (!check(form, { 'login form returns 200': (r) => r.status === 200 })) {
    return false;
  }

  let formCsrf = null;
  try {
    formCsrf = parseHTML(form.body)
      .find('input[name="csrf"]')
      .first()
      .attr('value');
  } catch (_) {
    formCsrf = null;
  }
  if (!check(formCsrf, {
    'login form contains csrf': (v) => typeof v === 'string' && v.length > 0,
  })) {
    return false;
  }

  const response = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: state.username, password: 'bench', csrf: formCsrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );
  if (!check(response, {
    'login succeeds or redirects': (r) => r.status === 200 || r.status === 302,
  })) {
    return false;
  }

  rememberCsrf(state, response);
  if (response.status === 302) {
    const target = locationUrl(header(response, 'Location'), '/v2/login');
    if (!check(target, { 'login redirect has a local location': (v) => !!v })) {
      return false;
    }
    const landing = http.get(target, { redirects: 0 });
    if (!check(landing, { 'login redirect completes': (r) => r.status === 200 })) {
      return false;
    }
    rememberCsrf(state, landing);
  }

  return check(state.csrf, {
    'authenticated csrf obtained': (v) => typeof v === 'string' && v.length > 0,
  });
}

function rawRequest(state, method, path, body, extraHeaders) {
  const headers = {};
  if (extraHeaders) {
    for (const key in extraHeaders) headers[key] = extraHeaders[key];
  }
  if (method !== 'GET') {
    headers['Content-Type'] = 'application/json';
    headers['X-CSRF-Token'] = state.csrf;
  }
  const res = http.request(method, BASE + path, body, { headers, redirects: 0 });
  if (res.status >= 200 && res.status < 300) rememberCsrf(state, res);
  return res;
}

function recoverSession(state, reason) {
  if (reason === 'expired') {
    const renewal = rawRequest(state, 'POST', '/v2/session/renew', '{}');
    if (renewal.status < 200 || renewal.status >= 300) {
      const body = json(renewal);
      if (renewal.status === 401 && body && body.error === 'session') {
        if (!login(state)) return false;
      } else {
        check(renewal, { 'expired session renews': (r) => r.status >= 200 && r.status < 300 });
        return false;
      }
    }
  } else if (reason === 'session') {
    if (!login(state)) return false;
  } else {
    return false;
  }

  if (state.cartId !== null) {
    const path = '/v2/carts/' + encodeURIComponent(String(state.cartId)) + '/recover';
    const recovered = rawRequest(state, 'POST', path, '{}');
    if (!check(recovered, {
      'cart recovery succeeds': (r) => r.status >= 200 && r.status < 300,
    })) {
      return false;
    }
  }
  return true;
}

function request(state, method, path, body, extraHeaders) {
  let res = rawRequest(state, method, path, body, extraHeaders);
  if (res.status !== 401) return res;

  const data = json(res);
  const reason = data && data.error;
  if (reason !== 'expired' && reason !== 'session') {
    check(res, { 'authorization is not denied': () => false });
    return res;
  }
  if (!recoverSession(state, reason)) return res;

  res = rawRequest(state, method, path, body, extraHeaders);
  return res;
}

function readCart(state, path, label) {
  const res = request(state, 'GET', path, null);
  const etag = header(res, 'ETag');
  const ok = check(res, {
    [label + ' returns 200']: (r) => r.status === 200,
    [label + ' has ETag']: () => typeof etag === 'string' && etag.length > 0,
  });
  return ok ? etag : null;
}

export default function () {
  const state = {
    username: 'bench-' + __VU,
    csrf: null,
    cartId: null,
  };

  if (!login(state)) return;

  const catalog = request(state, 'GET', '/v2/catalog', null);
  const catalogBody = json(catalog);
  const products = catalogBody && catalogBody.data && catalogBody.data.products;
  if (!check(catalog, {
    'catalog returns products': (r) => r.status === 200 && Array.isArray(products),
  })) {
    return;
  }

  let productId = null;
  let variantId = null;
  for (const product of products) {
    if (!product || product.id === undefined || product.id === null ||
        !Array.isArray(product.variants)) continue;
    for (const variant of product.variants) {
      if (variant && variant.in_stock === true &&
          variant.id !== undefined && variant.id !== null) {
        productId = product.id;
        variantId = variant.id;
        break;
      }
    }
    if (variantId !== null) break;
  }
  if (!check(variantId, { 'in-stock variant found': (v) => v !== null })) return;

  const created = request(
    state,
    'POST',
    '/v2/carts',
    JSON.stringify({ product_id: productId, variant_id: variantId })
  );
  const createdBody = json(created);
  if (!check(created, {
    'cart created once': (r) => r.status === 201 &&
      createdBody && createdBody.id !== undefined && createdBody.id !== null,
  })) {
    return;
  }
  state.cartId = createdBody.id;
  const cartPath = '/v2/carts/' + encodeURIComponent(String(state.cartId));

  const initialEtag = readCart(state, cartPath, 'initial cart read');
  if (!initialEtag) return;

  const payload = JSON.stringify({ quantity: 2 });
  const firstUpdate = request(state, 'PATCH', cartPath, payload, {
    'If-Match': initialEtag,
  });
  if (!check(firstUpdate, {
    'scheduled stale update receives 412': (r) => r.status === 412,
  })) {
    return;
  }

  const refreshedEtag = readCart(state, cartPath, 'conflict cart reread');
  if (!refreshedEtag) return;

  const retry = request(state, 'PATCH', cartPath, payload, {
    'If-Match': refreshedEtag,
  });
  if (!check(retry, {
    'conditional update retry succeeds': (r) => r.status >= 200 && r.status < 300,
  })) {
    return;
  }

  const checkoutEtag = readCart(state, cartPath, 'post-update cart read');
  if (!checkoutEtag) return;

  const orderKey = 'etag-' + __VU + '-' + __ITER + '-' +
    encodeURIComponent(String(state.cartId));
  const order = request(
    state,
    'POST',
    '/v2/orders',
    JSON.stringify({ cart_id: state.cartId }),
    { 'If-Match': checkoutEtag, 'Idempotency-Key': orderKey }
  );
  const orderBody = json(order);
  check(order, {
    'order committed and accepted': (r) => r.status === 201 &&
      orderBody && orderBody.accepted === true &&
      orderBody.id !== undefined && orderBody.id !== null,
  });
}

