import itertools
import os
import uuid
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit, urlunsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must target http://127.0.0.1:8000")

_user_numbers = itertools.count(1)
_finished_users = 0


class JourneyError(Exception):
    pass


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form_action = None
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        attrs = {key.lower(): value for key, value in attrs}
        tag = tag.lower()
        if tag == "form":
            self.form_action = attrs.get("action", "")
        elif tag == "input" and attrs.get("name") == "csrf":
            value = attrs.get("value")
            if value:
                self.candidates.append((self.form_action, value))

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.form_action = None

    def csrf(self):
        for action, value in self.candidates:
            if action and urlsplit(action).path.rstrip("/") == "/v2/login":
                return value
        if len(self.candidates) == 1:
            return self.candidates[0][1]
        raise ValueError("Could not uniquely identify login CSRF input")


def require_dict(value):
    if not isinstance(value, dict):
        raise ValueError("Expected a JSON object")
    return value


def require_field(obj, name):
    value = require_dict(obj).get(name)
    if value is None or value == "":
        raise ValueError("Missing " + name)
    return value


def require_etag(response):
    etag = response.headers.get("ETag")
    if not etag:
        raise ValueError("Missing ETag")
    return etag


def local_location(location, response_url):
    if not location:
        raise ValueError("Missing redirect Location")
    resolved = urlsplit(urljoin(response_url, location))
    target = urlsplit(BASE_URL)
    if resolved.scheme != target.scheme or resolved.netloc != target.netloc:
        raise ValueError("Redirect points outside the target")
    return urlunsplit(("", "", resolved.path or "/", resolved.query, ""))


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = "bench-{}".format(next(_user_numbers))
        self.iterations_done = 0
        self.csrf = None
        self.cart_id = None

    def request_checked(
        self,
        method,
        path,
        expected,
        *,
        payload=None,
        headers=None,
        authenticated=True,
        validator=None,
        allow_recovery=True,
    ):
        method = method.upper()
        for attempt in range(2):
            request_headers = dict(headers or {})
            if authenticated and method != "GET":
                if not self.csrf:
                    raise JourneyError("Missing CSRF token")
                request_headers["X-CSRF-Token"] = self.csrf

            kwargs = {
                "headers": request_headers,
                "allow_redirects": False,
                "catch_response": True,
            }
            if payload is not None:
                kwargs["json"] = payload

            recovery_reason = None
            failure = None
            result = None

            with self.client.request(method, path, **kwargs) as response:
                try:
                    data = response.json()
                except (ValueError, TypeError):
                    data = None

                if (
                    response.status_code == 401
                    and authenticated
                    and allow_recovery
                    and attempt == 0
                    and isinstance(data, dict)
                    and data.get("error") in ("expired", "session")
                ):
                    recovery_reason = data["error"]
                    response.success()
                elif response.status_code not in expected:
                    failure = "Unexpected HTTP {} for {} {}".format(
                        response.status_code, method, path
                    )
                    response.failure(failure)
                else:
                    try:
                        if authenticated and method != "GET" and isinstance(data, dict):
                            fresh_csrf = data.get("csrf")
                            if fresh_csrf:
                                self.csrf = fresh_csrf
                        value = validator(response, data) if validator else data
                        result = (response.status_code, value)
                        response.success()
                    except Exception as exc:
                        failure = "Invalid response for {} {}: {}".format(
                            method, path, exc
                        )
                        response.failure(failure)

            if failure:
                raise JourneyError(failure)
            if recovery_reason:
                self.recover_session(recovery_reason)
                continue
            return result

        raise JourneyError("Recovery retry exhausted")

    def login(self):
        def parse_form(response, _data):
            parser = LoginFormParser()
            parser.feed(response.text)
            return parser.csrf()

        _, login_csrf = self.request_checked(
            "GET",
            "/v2/login-form",
            {200},
            authenticated=False,
            validator=parse_form,
            allow_recovery=False,
        )

        def parse_login(response, data):
            if response.status_code == 302:
                return (
                    "redirect",
                    local_location(response.headers.get("Location"), response.url),
                )
            return ("complete", require_field(data, "csrf"))

        _, login_result = self.request_checked(
            "POST",
            "/v2/login",
            {200, 302},
            payload={
                "username": self.username,
                "password": "bench",
                "csrf": login_csrf,
            },
            authenticated=False,
            validator=parse_login,
            allow_recovery=False,
        )

        if login_result[0] == "redirect":
            _, token = self.request_checked(
                "GET",
                login_result[1],
                {200},
                authenticated=False,
                validator=lambda response, data: require_field(data, "csrf"),
                allow_recovery=False,
            )
            self.csrf = token
        else:
            self.csrf = login_result[1]

    def recover_session(self, reason):
        if reason == "expired":
            def renewed(_response, data):
                return require_field(data, "csrf")

            _, token = self.request_checked(
                "POST",
                "/v2/session/renew",
                {200},
                payload={},
                validator=renewed,
                allow_recovery=False,
            )
            self.csrf = token
        else:
            self.login()

        if self.cart_id is not None:
            self.request_checked(
                "POST",
                self.cart_path() + "/recover",
                {200, 204},
                payload={},
                allow_recovery=False,
            )

    def cart_path(self):
        return "/v2/carts/" + quote(str(self.cart_id), safe="")

    def get_cart_etag(self):
        _, etag = self.request_checked(
            "GET",
            self.cart_path(),
            {200},
            validator=lambda response, data: require_etag(response),
        )
        return etag

    def journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.login()

        def select_variant(_response, data):
            products = require_field(require_dict(data), "data")
            products = require_field(products, "products")
            if not isinstance(products, list):
                raise ValueError("Catalog products must be a list")
            for product in products:
                if not isinstance(product, dict):
                    continue
                product_id = product.get("id")
                variants = product.get("variants")
                if product_id is None or not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("in_stock") is True
                        and variant.get("id") is not None
                    ):
                        return product_id, variant["id"]
            raise ValueError("No in-stock catalog variant")

        _, (product_id, variant_id) = self.request_checked(
            "GET", "/v2/catalog", {200}, validator=select_variant
        )

        def created(response, data):
            return require_field(data, "id"), require_etag(response)

        _, (self.cart_id, etag) = self.request_checked(
            "POST",
            "/v2/carts",
            {201},
            payload={"product_id": product_id, "variant_id": variant_id},
            validator=created,
        )

        update = {"quantity": 2}
        status, _ = self.request_checked(
            "PATCH",
            self.cart_path(),
            {200, 204, 412},
            payload=update,
            headers={"If-Match": etag},
        )
        if status == 412:
            etag = self.get_cart_etag()
            self.request_checked(
                "PATCH",
                self.cart_path(),
                {200, 204},
                payload=update,
                headers={"If-Match": etag},
            )

        # Read the committed revision for the conditional checkout.
        etag = self.get_cart_etag()
        order_key = uuid.uuid4().hex

        def accepted(_response, data):
            data = require_dict(data)
            if data.get("accepted") is not True:
                raise ValueError("Order was not accepted")
            return require_field(data, "id")

        self.request_checked(
            "POST",
            "/v2/orders",
            {201},
            payload={"cart_id": self.cart_id},
            headers={"If-Match": etag, "Idempotency-Key": order_key},
            validator=accepted,
        )

    @task
    def run_iteration(self):
        global _finished_users
        try:
            self.journey()
        except JourneyError:
            # The corresponding HTTP sample has already been marked failed.
            pass
        finally:
            self.iterations_done += 1
            if self.iterations_done >= 2:
                _finished_users += 1
                raise StopUser()


class TwoUserShape(LoadTestShape):
    def tick(self):
        if _finished_users >= 2:
            return None
        return (2, 2)
