import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final AtomicInteger USER_NUMBERS = new AtomicInteger();

  private static ChainBuilder login() {
    return exec(
        http("login form")
            .get("/v2/login-form")
            .check(
                status().is(200),
                css("input[name='csrf']", "value").saveAs("loginCsrf")))
        .exitHereIfFailed()
        .exec(
            http("login")
                .post("/v2/login")
                .asJson()
                .body(StringBody(
                    "{\"username\":\"#{username}\",\"password\":\"bench\","
                        + "\"csrf\":\"#{loginCsrf}\"}"))
                .check(
                    status().saveAs("loginStatus"),
                    status().in(200, 302),
                    checkIf(s -> s.getInt("loginStatus") == 200)
                        .then(jsonPath("$.csrf").saveAs("csrf")),
                    checkIf(s -> s.getInt("loginStatus") == 200)
                        .then(jsonPath("$.user").exists()),
                    checkIf(s -> s.getInt("loginStatus") == 302)
                        .then(header("Location").saveAs("loginLocation"))))
        .exitHereIfFailed()
        .doIf(s -> s.getInt("loginStatus") == 302)
        .then(
            exec(
                http("login redirect")
                    .get("#{loginLocation}")
                    .check(
                        status().is(200),
                        jsonPath("$.csrf").saveAs("csrf"),
                        jsonPath("$.user").exists()))
                .exitHereIfFailed());
  }

  private static ChainBuilder recover() {
    return doIf(s -> "expired".equals(s.getString("reason")))
        .then(
            exec(
                http("renew session")
                    .post("/v2/session/renew")
                    .header("X-CSRF-Token", "#{csrf}")
                    .asJson()
                    .body(StringBody("{}"))
                    .check(
                        status().saveAs("renewStatus"),
                        status().in(200, 401),
                        checkIf(s -> s.getInt("renewStatus") == 200)
                            .then(jsonPath("$.csrf").saveAs("csrf")),
                        checkIf(s -> s.getInt("renewStatus") == 401)
                            .then(jsonPath("$.error").is("session").saveAs("reason"))))
                .exitHereIfFailed())
        .doIf(s -> "session".equals(s.getString("reason")))
        .then(login())
        .doIf(s -> s.contains("cartId"))
        .then(
            exec(
                http("recover cart")
                    .post("/v2/carts/#{cartId}/recover")
                    .header("X-CSRF-Token", "#{csrf}")
                    .asJson()
                    .body(StringBody("{}"))
                    .check(
                        status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        header("ETag").optional().saveAs("etag")))
                .exitHereIfFailed());
  }

  private static ChainBuilder catalogRequest(boolean retry) {
    return exec(
        http(retry ? "catalog retry" : "catalog")
            .get("/v2/catalog")
            .check(
                status().saveAs("operationStatus"),
                status().in(200, 401),
                checkIf(s -> retry).then(status().is(200)),
                checkIf(s -> s.getInt("operationStatus") == 401)
                    .then(jsonPath("$.error").in("expired", "session").saveAs("reason")),
                checkIf(s -> s.getInt("operationStatus") == 200)
                    .then(jsonPath("$.data.products").exists()),
                checkIf(s -> s.getInt("operationStatus") == 200)
                    .then(bodyString().saveAs("catalogBody"))))
        .exitHereIfFailed();
  }

  private static ChainBuilder catalog() {
    return exec(catalogRequest(false))
        .doIf(s -> s.getInt("operationStatus") == 401)
        .then(exec(recover()).exec(catalogRequest(true)))
        .exec(s -> {
          try {
            Object root = new JsonReader(s.getString("catalogBody")).read();
            Map<?, ?> data = (Map<?, ?>) ((Map<?, ?>) root).get("data");
            List<?> products = (List<?>) data.get("products");
            for (Object item : products) {
              Map<?, ?> product = (Map<?, ?>) item;
              Object productId = product.get("id");
              List<?> variants = (List<?>) product.get("variants");
              for (Object variantItem : variants) {
                Map<?, ?> variant = (Map<?, ?>) variantItem;
                Object variantId = variant.get("id");
                if (productId != null && variantId != null
                    && Boolean.TRUE.equals(variant.get("in_stock"))) {
                  String body = "{\"product_id\":" + jsonScalar(productId)
                      + ",\"variant_id\":" + jsonScalar(variantId) + "}";
                  return s.set("cartBody", body);
                }
              }
            }
            return s.markAsFailed();
          } catch (RuntimeException e) {
            return s.markAsFailed();
          }
        })
        .exitHereIfFailed();
  }

  private static ChainBuilder cartRequest(boolean retry) {
    return exec(
        http(retry ? "create cart retry" : "create cart")
            .post("/v2/carts")
            .header("X-CSRF-Token", "#{csrf}")
            .asJson()
            .body(StringBody("#{cartBody}"))
            .check(
                status().saveAs("operationStatus"),
                status().in(201, 401),
                checkIf(s -> retry).then(status().is(201)),
                checkIf(s -> s.getInt("operationStatus") == 401)
                    .then(jsonPath("$.error").in("expired", "session").saveAs("reason")),
                checkIf(s -> s.getInt("operationStatus") == 201)
                    .then(jsonPath("$.id").saveAs("cartId")),
                checkIf(s -> s.getInt("operationStatus") == 201)
                    .then(header("ETag").saveAs("etag")),
                checkIf(s -> s.getInt("operationStatus") == 201)
                    .then(jsonPath("$.csrf").optional().saveAs("csrf"))))
        .exitHereIfFailed();
  }

  private static ChainBuilder createCart() {
    return exec(cartRequest(false))
        .doIf(s -> s.getInt("operationStatus") == 401)
        .then(exec(recover()).exec(cartRequest(true)))
        .exec(s -> s.set("orderBody",
            "{\"cart_id\":" + jsonScalar(s.getString("cartId")) + "}"));
  }

  private static ChainBuilder readCartRequest(boolean retry) {
    return exec(
        http(retry ? "read cart retry" : "read cart")
            .get("/v2/carts/#{cartId}")
            .check(
                status().saveAs("operationStatus"),
                status().in(200, 401),
                checkIf(s -> retry).then(status().is(200)),
                checkIf(s -> s.getInt("operationStatus") == 401)
                    .then(jsonPath("$.error").in("expired", "session").saveAs("reason")),
                checkIf(s -> s.getInt("operationStatus") == 200)
                    .then(header("ETag").saveAs("etag"))))
        .exitHereIfFailed();
  }

  private static ChainBuilder readCart() {
    return exec(readCartRequest(false))
        .doIf(s -> s.getInt("operationStatus") == 401)
        .then(exec(recover()).exec(readCartRequest(true)));
  }

  private static ChainBuilder orderRequest(boolean retry) {
    return exec(
        http(retry ? "checkout retry" : "checkout")
            .post("/v2/orders")
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{etag}")
            .header("Idempotency-Key", "checkout-#{username}-#{cartId}")
            .asJson()
            .body(StringBody("#{orderBody}"))
            .check(
                status().saveAs("operationStatus"),
                status().in(201, 401),
                checkIf(s -> retry).then(status().is(201)),
                checkIf(s -> s.getInt("operationStatus") == 401)
                    .then(jsonPath("$.error").in("expired", "session").saveAs("reason")),
                checkIf(s -> s.getInt("operationStatus") == 201)
                    .then(jsonPath("$.accepted").is("true")),
                checkIf(s -> s.getInt("operationStatus") == 201)
                    .then(jsonPath("$.id").exists()),
                checkIf(s -> s.getInt("operationStatus") == 201)
                    .then(jsonPath("$.csrf").optional().saveAs("csrf"))))
        .exitHereIfFailed();
  }

  private static ChainBuilder checkout() {
    return exec(orderRequest(false))
        .doIf(s -> s.getInt("operationStatus") == 401)
        .then(exec(recover()).exec(orderRequest(true)));
  }

  private static String jsonScalar(Object value) {
    if (value instanceof Number || value instanceof Boolean) {
      return value.toString();
    }
    if (!(value instanceof String)) {
      throw new IllegalArgumentException("Invalid identifier");
    }
    StringBuilder out = new StringBuilder("\"");
    for (char c : ((String) value).toCharArray()) {
      switch (c) {
        case '"': out.append("\\\""); break;
        case '\\': out.append("\\\\"); break;
        case '\b': out.append("\\b"); break;
        case '\f': out.append("\\f"); break;
        case '\n': out.append("\\n"); break;
        case '\r': out.append("\\r"); break;
        case '\t': out.append("\\t"); break;
        default:
          if (c < 0x20) {
            out.append(String.format("\\u%04x", (int) c));
          } else {
            out.append(c);
          }
      }
    }
    return out.append('"').toString();
  }

  private static final class JsonReader {
    private final String text;
    private int pos;

    JsonReader(String text) {
      this.text = text;
    }

    Object read() {
      Object result = value();
      whitespace();
      if (pos != text.length()) throw new IllegalArgumentException("Trailing JSON");
      return result;
    }

    private void whitespace() {
      while (pos < text.length() && Character.isWhitespace(text.charAt(pos))) pos++;
    }

    private boolean take(char c) {
      whitespace();
      if (pos < text.length() && text.charAt(pos) == c) {
        pos++;
        return true;
      }
      return false;
    }

    private void expect(char c) {
      if (!take(c)) throw new IllegalArgumentException("Invalid JSON");
    }

    private Object value() {
      whitespace();
      if (pos >= text.length()) throw new IllegalArgumentException("Incomplete JSON");
      char c = text.charAt(pos);
      if (c == '"') return string();
      if (c == '{') return object();
      if (c == '[') return array();
      if (text.startsWith("true", pos)) {
        pos += 4;
        return Boolean.TRUE;
      }
      if (text.startsWith("false", pos)) {
        pos += 5;
        return Boolean.FALSE;
      }
      if (text.startsWith("null", pos)) {
        pos += 4;
        return null;
      }
      int start = pos;
      while (pos < text.length()
          && "-+0123456789.eE".indexOf(text.charAt(pos)) >= 0) pos++;
      if (start == pos) throw new IllegalArgumentException("Invalid JSON value");
      return new BigDecimal(text.substring(start, pos));
    }

    private Map<String, Object> object() {
      expect('{');
      Map<String, Object> result = new LinkedHashMap<>();
      if (take('}')) return result;
      do {
        whitespace();
        String key = string();
        expect(':');
        result.put(key, value());
      } while (take(','));
      expect('}');
      return result;
    }

    private List<Object> array() {
      expect('[');
      List<Object> result = new ArrayList<>();
      if (take(']')) return result;
      do {
        result.add(value());
      } while (take(','));
      expect(']');
      return result;
    }

    private String string() {
      expect('"');
      StringBuilder result = new StringBuilder();
      while (pos < text.length()) {
        char c = text.charAt(pos++);
        if (c == '"') return result.toString();
        if (c != '\\') {
          result.append(c);
          continue;
        }
        if (pos >= text.length()) throw new IllegalArgumentException("Invalid escape");
        char escaped = text.charAt(pos++);
        switch (escaped) {
          case '"': result.append('"'); break;
          case '\\': result.append('\\'); break;
          case '/': result.append('/'); break;
          case 'b': result.append('\b'); break;
          case 'f': result.append('\f'); break;
          case 'n': result.append('\n'); break;
          case 'r': result.append('\r'); break;
          case 't': result.append('\t'); break;
          case 'u':
            if (pos + 4 > text.length()) throw new IllegalArgumentException("Invalid unicode");
            result.append((char) Integer.parseInt(text.substring(pos, pos + 4), 16));
            pos += 4;
            break;
          default: throw new IllegalArgumentException("Invalid escape");
        }
      }
      throw new IllegalArgumentException("Unterminated string");
    }
  }

  public ModelSimulation() {
    String baseUrl = System.getenv("BASE_URL");
    if (baseUrl == null || baseUrl.isEmpty()) baseUrl = "http://127.0.0.1:8000";

    setUp(
        scenario("expiry recovery")
            .exec(s -> s.set("username", "bench-" + USER_NUMBERS.incrementAndGet()))
            .repeat(2).on(
                exec(s -> s.remove("cartId").remove("etag").remove("reason"))
                    .exec(login())
                    .exec(catalog())
                    .exec(createCart())
                    .exec(readCart())
                    .exec(checkout()))
            .injectOpen(atOnceUsers(2)))
        .protocols(http.baseUrl(baseUrl).disableFollowRedirect());
  }
}

