import http from 'k6/http';
import { check, fail } from 'k6';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '1m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (BASE !== 'http://127.0.0.1:8000') {
  throw new Error('BASE_URL must target http://127.0.0.1:8000');
}

const authStatuses = http.expectedStatuses({ min: 200, max: 299 }, 401);
const loginStatuses = http.expectedStatuses(200, 302);

function assert(condition, name) {
  const passed = check({ condition }, {
    [name]: (value) => value.condition === true,
  });
  if (!passed) fail(name);
}

function json(response) {
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key of Object.keys(response.headers || {})) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return null;
}

function hasId(value) {
  return (typeof value === 'string' && value.length > 0) ||
    (typeof value === 'number' && Number.isFinite(value));
}

function locationUrl(location, fromPath) {
  assert(typeof location === 'string' && location.length > 0, 'redirect has a Location');
  assert(!location.includes('\\'), 'redirect Location is safe');

  if (/^https?:\/\//i.test(location)) {
    assert(
      location === BASE || location.startsWith(BASE + '/') || location.startsWith(BASE + '?'),
      'redirect stays on target'
    );
    return location;
  }

  assert(!location.startsWith('//'), 'redirect stays on target');
  if (location.startsWith('/')) return BASE + location;
  if (location.startsWith('?')) return BASE + fromPath + location;

  const directory = fromPath.slice(0, fromPath.lastIndexOf('/') + 1);
  const parts = (directory + location).split('/');
  const normalized = [];
  for (const part of parts) {
    if (!part || part === '.') continue;
    if (part === '..') {
      normalized.pop();
    } else {
      normalized.push(part);
    }
  }
  return BASE + '/' + normalized.join('/');
}

function updateCsrf(state, response) {
  const body = json(response);
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function login(state) {
  const form = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login form' },
  });
  assert(form.status === 200, 'login form returned 200');

  let csrf = null;
  try {
    csrf = form.html().find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    csrf = null;
  }
  assert(typeof csrf === 'string' && csrf.length > 0, 'login form contains CSRF');

  const response = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: state.username, password: 'bench', csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      responseCallback: loginStatuses,
      tags: { name: 'login' },
    }
  );
  assert(response.status === 200 || response.status === 302, 'login succeeded');

  let result = response;
  if (response.status === 302) {
    const destination = locationUrl(header(response, 'Location'), '/v2/login');
    result = http.get(destination, {
      redirects: 0,
      tags: { name: 'login redirect' },
    });
    assert(result.status === 200, 'login redirect returned 200');
  }

  const body = json(result);
  assert(
    body !== null && typeof body.csrf === 'string' && body.csrf.length > 0,
    'login supplied session CSRF'
  );
  state.csrf = body.csrf;
}

function recoverSession(state, reason) {
  if (reason === 'expired') {
    const renewed = http.post(BASE + '/v2/session/renew', '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
      tags: { name: 'session renew' },
    });
    assert(renewed.status === 200, 'expired session renewed');

    const body = json(renewed);
    assert(
      body !== null && typeof body.csrf === 'string' && body.csrf.length > 0,
      'renew supplied session CSRF'
    );
    state.csrf = body.csrf;
  } else {
    login(state);
  }

  if (state.cartId !== null) {
    const recovered = http.post(
      BASE + '/v2/carts/' + encodeURIComponent(String(state.cartId)) + '/recover',
      '{}',
      {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
        },
        redirects: 0,
        tags: { name: 'cart recover' },
      }
    );
    assert(
      recovered.status >= 200 && recovered.status < 300,
      'existing cart recovered'
    );
    updateCsrf(state, recovered);
    const etag = header(recovered, 'ETag');
    if (etag) state.etag = etag;
  }
}

function authorized(state, method, path, payload, extraHeaders, name) {
  function send() {
    const headers = Object.assign({}, extraHeaders ? extraHeaders() : {});
    if (method !== 'GET') {
      headers['Content-Type'] = 'application/json';
      headers['X-CSRF-Token'] = state.csrf;
    }
    return http.request(method, BASE + path, payload === null ? null : JSON.stringify(payload), {
      headers,
      redirects: 0,
      responseCallback: authStatuses,
      tags: { name },
    });
  }

  let response = send();
  if (response.status === 401) {
    const body = json(response);
    const reason = body && body.error;
    assert(
      reason === 'expired' || reason === 'session',
      '401 is a recoverable expired or revoked session'
    );
    recoverSession(state, reason);
    response = send();
    assert(response.status !== 401, 'interrupted operation retried at most once');
  }

  if (method !== 'GET' && response.status >= 200 && response.status < 300) {
    updateCsrf(state, response);
  }
  return response;
}

export default function () {
  const state = {
    username: 'bench-' + __VU,
    csrf: null,
    cartId: null,
    etag: null,
  };

  login(state);

  const catalog = authorized(state, 'GET', '/v2/catalog', null, null, 'catalog');
  assert(catalog.status === 200, 'catalog returned 200');
  const catalogBody = json(catalog);
  const products = catalogBody && catalogBody.data && catalogBody.data.products;
  assert(Array.isArray(products), 'catalog contains products');

  let selection = null;
  for (const product of products) {
    if (!product || !hasId(product.id) || !Array.isArray(product.variants)) continue;
    for (const variant of product.variants) {
      if (variant && hasId(variant.id) && variant.in_stock === true) {
        selection = { product_id: product.id, variant_id: variant.id };
        break;
      }
    }
    if (selection) break;
  }
  assert(selection !== null, 'catalog contains an in-stock variant');

  const created = authorized(state, 'POST', '/v2/carts', selection, null, 'create cart');
  assert(created.status === 201, 'cart created');
  const cart = json(created);
  assert(cart !== null && hasId(cart.id), 'created cart has an ID');
  state.cartId = cart.id;
  state.etag = header(created, 'ETag');
  assert(typeof state.etag === 'string' && state.etag.length > 0, 'created cart has an ETag');

  const idempotencyKey =
    'order-' + __VU + '-' + __ITER + '-' + String(state.cartId) + '-' +
    Date.now() + '-' + Math.random().toString(36).slice(2);

  const order = authorized(
    state,
    'POST',
    '/v2/orders',
    { cart_id: state.cartId },
    () => ({
      'Idempotency-Key': idempotencyKey,
      'If-Match': state.etag,
    }),
    'checkout'
  );
  assert(order.status === 201, 'checkout returned 201');
  const orderBody = json(order);
  assert(
    orderBody !== null && orderBody.accepted === true && hasId(orderBody.id),
    'checkout accepted one order'
  );
}
