import itertools
import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


USER_COUNT = 2
ITERATIONS = 2
ORIGIN = "http://127.0.0.1:8000"

_user_numbers = itertools.count(1)
_finished_users = 0


class JourneyFailure(Exception):
    pass


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input" or self.csrf is not None:
            return
        attributes = dict(attrs)
        if (attributes.get("name") or "").lower() == "csrf":
            value = attributes.get("value")
            if value:
                self.csrf = value

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def safe_location(location):
    if not isinstance(location, str) or not location:
        return False
    try:
        parsed = urlsplit(urljoin(ORIGIN + "/", location))
        return parsed.scheme == "http" and parsed.netloc == "127.0.0.1:8000"
    except ValueError:
        return False


def csrf_in(data):
    if isinstance(data, dict):
        token = data.get("csrf")
        if isinstance(token, str) and token:
            return token
    return None


def available_product(data):
    if not isinstance(data, dict):
        return None
    catalog = data.get("data")
    if not isinstance(catalog, dict):
        return None
    products = catalog.get("products")
    if not isinstance(products, list):
        return None
    for product in products:
        if not isinstance(product, dict) or product.get("id") is None:
            continue
        variants = product.get("variants")
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if (
                isinstance(variant, dict)
                and variant.get("id") is not None
                and variant.get("in_stock") is True
            ):
                return product["id"], variant["id"]
    return None


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", ORIGIN)
    wait_time = constant(0)

    def on_start(self):
        self.username = "bench-{}".format(next(_user_numbers))
        self.iterations_done = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.form_csrf = None

    def on_stop(self):
        global _finished_users
        _finished_users += 1

    def call(
        self,
        method,
        path,
        expected,
        *,
        body=None,
        authenticated=True,
        recover=True,
        check=None,
        extra_headers=None,
        use_etag=False,
    ):
        for attempt in range(2):
            headers = dict(extra_headers or {})
            if authenticated and method != "GET":
                if self.csrf:
                    headers["X-CSRF-Token"] = self.csrf
            if use_etag and self.etag:
                headers["If-Match"] = self.etag

            kwargs = {
                "headers": headers,
                "catch_response": True,
                "allow_redirects": False,
                "timeout": 10,
            }
            if body is not None:
                kwargs["json"] = body

            expiry = None
            failure = None
            data = None
            response_headers = None

            with self.client.request(method, path, **kwargs) as response:
                try:
                    if response.content:
                        try:
                            data = response.json()
                        except ValueError:
                            data = None
                    response_headers = response.headers.copy()

                    if response.status_code == 401:
                        error = data.get("error") if isinstance(data, dict) else None
                        if (
                            authenticated
                            and recover
                            and attempt == 0
                            and error in ("expired", "session")
                        ):
                            expiry = error
                            response.success()
                        else:
                            failure = "Unexpected or unrecoverable 401: {}".format(error)
                            response.failure(failure)
                    elif response.status_code not in expected:
                        failure = "Unexpected HTTP status {}".format(response.status_code)
                        response.failure(failure)
                    else:
                        failure = check(response, data) if check else None
                        if failure:
                            response.failure(failure)
                        else:
                            if authenticated and method != "GET":
                                token = csrf_in(data)
                                if token:
                                    self.csrf = token
                            response.success()
                except Exception as exc:
                    failure = "Response validation failed: {}".format(exc)
                    response.failure(failure)

            if failure:
                raise JourneyFailure(failure)
            if expiry:
                self.recover_session(expiry)
                continue
            return data, response_headers

        raise JourneyFailure("Recovery retry exhausted")

    def login(self):
        self.client.cookies.clear()
        self.csrf = None
        self.form_csrf = None

        def check_form(response, data):
            parser = LoginFormParser()
            parser.feed(response.text)
            parser.close()
            if not parser.csrf:
                return "Login form did not contain a CSRF token"
            self.form_csrf = parser.csrf
            return None

        self.call(
            "GET",
            "/v2/login-form",
            {200},
            authenticated=False,
            recover=False,
            check=check_form,
        )

        def check_login(response, data):
            if response.status_code == 302:
                if not safe_location(response.headers.get("Location")):
                    return "Login redirect has an invalid Location"
            elif not csrf_in(data):
                return "Login response did not contain a CSRF token"
            return None

        data, headers = self.call(
            "POST",
            "/v2/login",
            {200, 302},
            body={
                "username": self.username,
                "password": "bench",
                "csrf": self.form_csrf,
            },
            authenticated=False,
            recover=False,
            check=check_login,
        )

        token = csrf_in(data)
        location = headers.get("Location")
        if location:
            def check_redirect(response, redirected_data):
                if not csrf_in(redirected_data) and not token:
                    return "Login redirect did not provide a CSRF token"
                return None

            redirected_data, _ = self.call(
                "GET",
                location,
                {200},
                authenticated=False,
                recover=False,
                check=check_redirect,
            )
            token = csrf_in(redirected_data) or token

        if not token:
            raise JourneyFailure("Login did not establish a CSRF token")
        self.csrf = token

    def recover_session(self, error):
        if error == "expired":
            def check_renew(response, data):
                if not csrf_in(data):
                    return "Renewal did not provide a fresh CSRF token"
                return None

            self.call(
                "POST",
                "/v2/session/renew",
                {200},
                body={},
                recover=False,
                check=check_renew,
            )
        else:
            self.login()

        if self.cart_id is not None:
            path = "/v2/carts/{}/recover".format(
                quote(str(self.cart_id), safe="")
            )
            _, headers = self.call(
                "POST",
                path,
                {200, 201, 204},
                body={},
                recover=False,
            )
            if headers.get("ETag"):
                self.etag = headers["ETag"]

    @task
    def journey(self):
        try:
            self.cart_id = None
            self.etag = None
            self.login()

            def check_catalog(response, data):
                if available_product(data) is None:
                    return "Catalog contained no in-stock variant"
                return None

            catalog, _ = self.call(
                "GET",
                "/v2/catalog",
                {200},
                check=check_catalog,
            )
            product_id, variant_id = available_product(catalog)

            def check_cart(response, data):
                if not isinstance(data, dict) or data.get("id") is None:
                    return "Cart creation did not return a cart ID"
                if not response.headers.get("ETag"):
                    return "Cart creation did not return an ETag"
                return None

            cart, headers = self.call(
                "POST",
                "/v2/carts",
                {201},
                body={"product_id": product_id, "variant_id": variant_id},
                check=check_cart,
            )
            self.cart_id = cart["id"]
            self.etag = headers["ETag"]
            idempotency_key = uuid4().hex

            def check_order(response, data):
                if not isinstance(data, dict):
                    return "Order response was not a JSON object"
                if data.get("accepted") is not True or data.get("id") is None:
                    return "Order was not accepted"
                return None

            self.call(
                "POST",
                "/v2/orders",
                {201},
                body={"cart_id": self.cart_id},
                extra_headers={"Idempotency-Key": idempotency_key},
                use_etag=True,
                check=check_order,
            )
        except JourneyFailure:
            raise StopUser()

        self.iterations_done += 1
        if self.iterations_done >= ITERATIONS:
            raise StopUser()


