              .check(status().saveAs("loginStatus"))
              .check(header("Location").optional().saveAs("loginLocation"))
              .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"")
                  .optional().saveAs("newCsrf")))
          .exitHereIfFailed()
          .exec(ModelSimulation::updateCsrf)
          .exec(session -> {
            if (session.getInt("loginStatus") == 302
                && !session.contains("loginLocation")) {
              return session.markAsFailed();
            }
            return session;
          })
          .exitHereIfFailed()
          .doIf(session -> session.getInt("loginStatus") == 302).then(
              exec(http("login redirect")
                  .get("#{loginLocation}")
                  .check(status().is(200))
                  .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"")
                      .optional().saveAs("newCsrf")))
              .exitHereIfFailed()
              .exec(ModelSimulation::updateCsrf)
          )

          .exec(session -> session
              .set("catalogIndex", 0)
              .set("catalogHasProduct", true)
              .set("catalogFound", false))
          .asLongAs(session ->
              session.getInt("catalogIndex") < 64
                  && session.getBoolean("catalogHasProduct")
                  && !session.getBoolean("catalogFound"))
          .on(
              exec(session -> session
                  .remove("candidateProduct")
                  .remove("candidateVariant"))
              .exec(http("catalog")
                  .get("/v2/catalog")
                  .check(status().is(200))
                  .check(jsonPath("$.data.products[#{catalogIndex}].id")
                      .optional().saveAs("candidateProduct"))
                  .check(jsonPath(
                      "$.data.products[#{catalogIndex}].variants[?(@.in_stock == true)].id")
                      .find().optional().saveAs("candidateVariant")))
              .exitHereIfFailed()
              .exec(session -> {
                boolean hasProduct = session.contains("candidateProduct");
                boolean found = hasProduct && session.contains("candidateVariant");
                session = session
                    .set("catalogHasProduct", hasProduct)
                    .set("catalogFound", found)
                    .set("catalogIndex", session.getInt("catalogIndex") + 1);
                if (found) {
                  session = session
                      .set("productId", session.getString("candidateProduct"))
                      .set("variantId", session.getString("candidateVariant"));
                }
                return session;
              })
          )
          .exec(session -> session.getBoolean("catalogFound")
              ? session : session.markAsFailed())
          .exitHereIfFailed()

          .exec(http("create cart")
              .post("/v2/carts")
              .header("Content-Type", "application/json")
              .header("X-CSRF-Token", "#{csrf}")
              .body(StringBody(
                  "{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}"))
              .check(status().is(201))
              .check(jsonPath("$.id").saveAs("cartId"))
              .check(jsonPath("$.csrf").optional().saveAs("newCsrf")))
          .exitHereIfFailed()
          .exec(ModelSimulation::updateCsrf)

          .exec(http("request reservation")
              .post("/v2/reservations")
              .header("Content-Type", "application/json")
              .header("X-CSRF-Token", "#{csrf}")
              .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
              .check(status().is(202))
              .check(jsonPath("$.status_url").saveAs("statusUrl"))
              .check(jsonPath("$.job_id").optional().saveAs("jobIdFromResponse"))
              .check(jsonPath("$.id").optional().saveAs("responseId"))
              .check(jsonPath("$.csrf").optional().saveAs("newCsrf")))
          .exitHereIfFailed()
          .exec(ModelSimulation::updateCsrf)
          .exec(session -> {
            try {
              URI uri = URI.create(session.getString("statusUrl"));
              URI base = URI.create(BASE_URL);
              URI resolved = base.resolve(uri);
              if (!"http".equalsIgnoreCase(resolved.getScheme())
                  || !base.getHost().equalsIgnoreCase(resolved.getHost())
                  || resolved.getPort() != base.getPort()
                  || resolved.getUserInfo() != null) {
                return session.markAsFailed();
              }

              String jobId;
              if (session.contains("jobIdFromResponse")) {
                jobId = session.getString("jobIdFromResponse");
              } else if (session.contains("responseId")) {
                jobId = session.getString("responseId");
              } else {
                String path = uri.getPath();
                if (path == null || path.isEmpty()) {
                  return session.markAsFailed();
                }
                while (path.endsWith("/") && path.length() > 1) {
                  path = path.substring(0, path.length() - 1);
                }
                if (path.endsWith("/status")) {
                  path = path.substring(0, path.length() - "/status".length());
                }
                jobId = path.substring(path.lastIndexOf('/') + 1);
              }
              if (jobId == null || jobId.isEmpty()) {
                return session.markAsFailed();
              }
              return session.set("jobId", jobId)
                  .set("polls", 0)
                  .set("ready", false);
            } catch (IllegalArgumentException e) {
              return session.markAsFailed();
            }
          })
          .exitHereIfFailed()

          .asLongAs(session ->
              session.getInt("polls") < 5 && !session.getBoolean("ready"))
          .on(
              pause(Duration.ofMillis(50))
              .exec(session -> session.remove("reservationId"))
              .exec(http("poll reservation job")
                  .get("#{statusUrl}")
                  .check(status().is(200))
                  .check(jsonPath("$.status")
                      .in("pending", "ready").saveAs("jobStatus"))
                  .check(jsonPath("$.reservation_id")
                      .optional().saveAs("reservationId")))
              .exitHereIfFailed()
              .exec(session -> {
                boolean ready = "ready".equals(session.getString("jobStatus"));
                session = session
                    .set("polls", session.getInt("polls") + 1)
                    .set("ready", ready);
                if (ready && !session.contains("reservationId")) {
                  return session.markAsFailed();
                }
                return session;
              })
              .exitHereIfFailed()
          )
          .exec(session -> session.getBoolean("ready")
              && session.contains("reservationId")
              ? session : session.markAsFailed())
          .exitHereIfFailed()

          .exec(http("read cart version")
              .get("/v2/carts/#{cartId}")
              .check(status().is(200))
              .check(header("ETag").saveAs("cartEtag")))
          .exitHereIfFailed()

          .exec(http("checkout")
              .post("/v2/orders")
              .header("Content-Type", "application/json")
              .header("X-CSRF-Token", "#{csrf}")
              .header("If-Match", "#{cartEtag}")
              .header("Idempotency-Key", "reservation-order-#{cartId}")
              .body(StringBody(
                  "{\"cart_id\":\"#{cartId}\",\"reservation_id\":\"#{reservationId}\"}"))
              .check(status().is(201))
              .check(jsonPath("$.accepted").is("true"))
              .check(jsonPath("$.id").exists())
              .check(jsonPath("$.csrf").optional().saveAs("newCsrf")))
          .exitHereIfFailed()
          .exec(ModelSimulation::updateCsrf)
      );

  {
    setUp(JOURNEYS.injectOpen(atOnceUsers(2))).protocols(HTTP);
  }
}

