import http from 'k6/http';
import { check, sleep } from 'k6';
import { parseHTML } from 'k6/html';

export const options = {
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const EXPECTED_BASE = 'http://127.0.0.1:8000';

function present(value) {
  return value !== undefined && value !== null && String(value).length > 0;
}

function target(reference) {
  if (BASE !== EXPECTED_BASE || typeof reference !== 'string' || !reference) {
    throw new Error('Invalid target');
  }
  if (reference.startsWith(BASE + '/') || reference === BASE) return reference;
  if (reference.startsWith('//') || /^[a-z][a-z0-9+.-]*:/i.test(reference)) {
    throw new Error('External URL rejected');
  }
  return BASE + (reference.startsWith('/') ? reference : '/' + reference);
}

function json(response) {
  if (!response) return null;
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  if (!response || !response.headers) return null;
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return null;
}

function updateCsrf(state, response) {
  const data = json(response);
  if (data && present(data.csrf)) state.csrf = data.csrf;
}

function successful(response) {
  return !!response && response.status >= 200 && response.status < 300;
}

function login(state) {
  const formResponse = http.get(target('/v2/login-form'), {
    redirects: 0,
    timeout: '10s',
  });

  if (!check(formResponse, {
    'login form loaded': (r) => r.status === 200,
  })) return false;

  let token;
  try {
    const document = parseHTML(formResponse.body);
    token = document.find('form[action="/v2/login"] input[name="csrf"]')
      .first().attr('value');
    if (!present(token)) {
      token = document.find('input[name="csrf"]').first().attr('value');
    }
  } catch (_) {
    token = null;
  }

  if (!check({ token }, {
    'login form CSRF extracted': (v) => present(v.token),
  })) return false;

  state.csrf = token;
  const response = http.post(
    target('/v2/login'),
    JSON.stringify({
      username: `bench-${__VU}`,
      password: 'bench',
      csrf: token,
    }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      timeout: '10s',
    }
  );

  if (!check(response, {
    'login accepted': (r) => r.status === 200 || r.status === 302,
  })) return false;

  updateCsrf(state, response);

  if (response.status === 302) {
    const location = header(response, 'Location');
    if (!check({ location }, {
      'login redirect location provided': (v) => present(v.location),
    })) return false;

    const redirected = http.get(target(location), {
      redirects: 0,
      timeout: '10s',
    });
    if (!check(redirected, {
      'login redirect completed': (r) => r.status === 200,
    })) return false;
    updateCsrf(state, redirected);
  }

  return check(state, {
    'session CSRF available': (s) => present(s.csrf),
  });
}

function directMutation(state, path, body) {
  const response = http.post(target(path), JSON.stringify(body), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': String(state.csrf),
    },
    redirects: 0,
    timeout: '10s',
  });
  if (successful(response)) updateCsrf(state, response);
  return response;
}

function recoverSession(state, reason) {
  if (reason === 'expired') {
    const renewed = directMutation(state, '/v2/session/renew', {});
    if (!check(renewed, {
      'expired session renewed': successful,
    })) return false;
  } else if (reason === 'session') {
    if (!login(state)) return false;
  } else {
    check({ reason }, {
      'authorization was not denied': (v) => v.reason !== 'denied',
      'authorization error is recoverable': (v) =>
        v.reason === 'expired' || v.reason === 'session',
    });
    return false;
  }

  if (present(state.cartId)) {
    const recovered = directMutation(
      state,
      `/v2/carts/${encodeURIComponent(String(state.cartId))}/recover`,
      {}
    );
    if (!check(recovered, {
      'cart recovered': successful,
    })) return false;
    const etag = header(recovered, 'ETag');
    if (present(etag)) state.etag = etag;
  }
  return true;
}

function authenticated(state, method, path, body, extraHeaders, beforeAttempt) {
  const url = target(path);

  function attempt() {
    if (beforeAttempt && !beforeAttempt()) return null;
    const headers = Object.assign({}, extraHeaders || {});
    let payload = null;
    if (method !== 'GET') {
      headers['Content-Type'] = 'application/json';
      headers['X-CSRF-Token'] = String(state.csrf);
      payload = JSON.stringify(body === undefined ? {} : body);
    }
    const response = http.request(method, url, payload, {
      headers,
      redirects: 0,
      timeout: '10s',
    });
    if (method !== 'GET' && successful(response)) updateCsrf(state, response);
    return response;
  }

  let response = attempt();
  if (response && response.status === 401) {
    const data = json(response);
    const reason = data && data.error;
    if (recoverSession(state, reason)) response = attempt();
  }
  return response;
}

function jobIdFromResponse(data) {
  if (present(data.job_id)) return data.job_id;
  if (present(data.id)) return data.id;

  const url = data.status_url;
  if (typeof url !== 'string') return null;
  const queryMatch = url.match(/[?&](?:job_id|id)=([^&#]+)/);
  if (queryMatch) return queryMatch[1];
  const path = url.split(/[?#]/, 1)[0].replace(/\/+$/, '');
  const parts = path.split('/');
  const last = parts[parts.length - 1];
  return last === 'status' && parts.length > 1
    ? parts[parts.length - 2]
    : last;
}

export default function () {
  const state = { csrf: null, cartId: null, etag: null };

  try {
    if (!login(state)) return;

    const catalogResponse = authenticated(state, 'GET', '/v2/catalog');
    const catalog = json(catalogResponse);
    if (!check({ response: catalogResponse, data: catalog }, {
      'catalog loaded': (v) =>
        successful(v.response) && !!v.data &&
        !!v.data.data && Array.isArray(v.data.data.products),
    })) return;

    let productId = null;
    let variantId = null;
    for (const product of catalog.data.products) {
      if (!present(product.id) || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find((v) => v.in_stock && present(v.id));
      if (variant) {
        productId = product.id;
        variantId = variant.id;
        break;
      }
    }

    if (!check({ productId, variantId }, {
      'in-stock catalog variant selected': (v) =>
        present(v.productId) && present(v.variantId),
    })) return;

    const cartResponse = authenticated(state, 'POST', '/v2/carts', {
      product_id: productId,
      variant_id: variantId,
    });
    const cart = json(cartResponse);
    if (!check({ response: cartResponse, data: cart }, {
      'cart created': (v) =>
        !!v.response && v.response.status === 201 &&
        !!v.data && present(v.data.id),
    })) return;

    state.cartId = cart.id;
    state.etag = header(cartResponse, 'ETag');

    const reservationResponse = authenticated(
      state,
      'POST',
      '/v2/reservations',
      { cart_id: state.cartId }
    );
    const job = json(reservationResponse);
    if (!check({ response: reservationResponse, data: job }, {
      'reservation job accepted with status URL': (v) =>
        !!v.response && v.response.status === 202 &&
        !!v.data && present(v.data.status_url),
    })) return;

    const jobId = jobIdFromResponse(job);
    if (!check({ jobId }, {
      'reservation job ID extracted': (v) => present(v.jobId),
    })) return;

    let attempts = 0;
    let lastPollAt = 0;
    let result = null;

    function beforePoll() {
      if (attempts >= 5) return false;
      if (attempts > 0) {
        const remaining = 60 - (Date.now() - lastPollAt);
        if (remaining > 0) sleep(remaining / 1000);
      }
      lastPollAt = Date.now();
      attempts += 1;
      return true;
    }

    while (attempts < 5) {
      const response = authenticated(
        state, 'GET', job.status_url, undefined, undefined, beforePoll
      );
      const status = json(response);
      if (!check({ response, status }, {
        'reservation status response valid': (v) =>
          successful(v.response) && !!v.status &&
          ['pending', 'ready', 'failed'].includes(v.status.status),
      })) return;

      result = status;
      if (status.status !== 'pending') break;
    }

    if (!check(result || {}, {
      'reservation ready with ID': (v) =>
        v.status === 'ready' && present(v.reservation_id),
    })) return;

    const cartRead = authenticated(
      state,
      'GET',
      `/v2/carts/${encodeURIComponent(String(state.cartId))}`
    );
    const currentEtag = header(cartRead, 'ETag');
    if (!check({ response: cartRead, etag: currentEtag }, {
      'current cart and ETag loaded': (v) =>
        successful(v.response) && present(v.etag),
    })) return;
    state.etag = currentEtag;

    const orderResponse = authenticated(
      state,
      'POST',
      '/v2/orders',
      {
        cart_id: state.cartId,
        reservation_id: result.reservation_id,
      },
      {
        'Idempotency-Key': `reservation-${__VU}-${__ITER}-${state.cartId}`,
        'If-Match': state.etag,
      }
    );
    const order = json(orderResponse);
    check({ response: orderResponse, data: order }, {
      'order committed': (v) =>
        !!v.response && v.response.status === 201 &&
        !!v.data && v.data.accepted === true && present(v.data.id),
    });
  } catch (_) {
    check({ ok: false }, {
      'journey completed without an unexpected error': (v) => v.ok,
    });
  }
}
