import itertools
import os
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from gevent import sleep
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

USER_COUNT = 2
ITERATIONS = 2
_finished_users = 0
_user_numbers = itertools.count(1)


def present(value):
    return value is not None and value != ""


def local_path(location):
    if not isinstance(location, str) or not location:
        raise ValueError("Missing dynamic URL")
    absolute = urljoin(BASE_URL + "/", location)
    parsed = urlsplit(absolute)
    if parsed.scheme != "http" or parsed.netloc != "127.0.0.1:8000":
        raise ValueError("Dynamic URL is outside the target")
    path = parsed.path or "/"
    if parsed.query:
        path += "?" + parsed.query
    return path


class InputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf_values = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attributes = {key.lower(): value for key, value in attrs}
        if attributes.get("name") == "csrf" and present(attributes.get("value")):
            self.csrf_values.append(attributes["value"])


class ReservationUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def __init__(self, environment):
        super().__init__(environment)
        number = next(_user_numbers)
        self.username = "bench-{}".format((number - 1) % 16 + 1)
        self.iterations_done = 0
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None

    def _call(
        self,
        method,
        path,
        expected,
        payload=None,
        headers=None,
        authenticated=True,
        recovery=True,
        check=None,
    ):
        try:
            path = local_path(path)
        except ValueError:
            return None

        for attempt in range(2):
            request_headers = dict(headers or {})
            if authenticated and method != "GET":
                if not present(self.csrf):
                    return None
                request_headers["X-CSRF-Token"] = self.csrf
            if attempt and "If-Match" in request_headers and self.cart_etag:
                request_headers["If-Match"] = self.cart_etag

            kwargs = {
                "headers": request_headers,
                "catch_response": True,
                "allow_redirects": False,
                "timeout": 10,
            }
            if payload is not None:
                kwargs["json"] = payload

            recover_reason = None
            result = None
            with self.client.request(method, path, **kwargs) as response:
                try:
                    data = response.json()
                except (ValueError, TypeError):
                    data = None

                if response.status_code == 401:
                    error = data.get("error") if isinstance(data, dict) else None
                    if (
                        authenticated
                        and recovery
                        and attempt == 0
                        and error in ("expired", "session")
                    ):
                        response.success()
                        recover_reason = error
                    else:
                        response.failure("Unexpected or unrecoverable 401: {}".format(error))
                elif response.status_code not in expected:
                    response.failure(
                        "Unexpected HTTP status {}".format(response.status_code)
                    )
                else:
                    try:
                        if check is not None:
                            check(response, data)
                    except (ValueError, TypeError, KeyError) as exc:
                        response.failure(str(exc))
                    else:
                        if (
                            authenticated
                            and method != "GET"
                            and isinstance(data, dict)
                            and present(data.get("csrf"))
                        ):
                            self.csrf = data["csrf"]
                        result = (response, data)

            if recover_reason is not None:
                if not self._recover(recover_reason):
                    return None
                continue
            return result
        return None

    def _login(self):
        def check_form(response, _data):
            parser = InputParser()
            parser.feed(response.text)
            if not parser.csrf_values:
                raise ValueError("Login form has no csrf input")
            response.login_csrf = parser.csrf_values[0]

        form = self._call(
            "GET",
            "/v2/login-form",
            (200,),
            authenticated=False,
            recovery=False,
            check=check_form,
        )
        if form is None:
            return False
        form_csrf = form[0].login_csrf

        def check_login(response, data):
            if response.status_code == 302:
                if not response.headers.get("Location"):
                    raise ValueError("Login redirect has no Location")
                local_path(response.headers["Location"])
            elif not isinstance(data, dict) or not present(data.get("csrf")):
                raise ValueError("Login response has no csrf")

        login = self._call(
            "POST",
            "/v2/login",
            (200, 302),
            payload={
                "username": self.username,
                "password": "bench",
                "csrf": form_csrf,
            },
            authenticated=False,
            recovery=False,
            check=check_login,
        )
        if login is None:
            return False

        response, data = login
        if response.status_code == 302:
            location = response.headers["Location"]

            def check_redirect(_response, redirected_data):
                if not isinstance(redirected_data, dict) or not present(
                    redirected_data.get("csrf")
                ):
                    raise ValueError("Login redirect response has no csrf")

            redirected = self._call(
                "GET",
                location,
                (200,),
                authenticated=False,
                recovery=False,
                check=check_redirect,
            )
            if redirected is None:
                return False
            data = redirected[1]

        self.csrf = data["csrf"]
        return True

    def _recover(self, reason):
        if reason == "session":
            if not self._login():
                return False
        else:
            def check_renew(_response, data):
                if not isinstance(data, dict) or not present(data.get("csrf")):
                    raise ValueError("Renewal response has no csrf")

            renewed = self._call(
                "POST",
                "/v2/session/renew",
                (200,),
                payload={},
                recovery=False,
                check=check_renew,
            )
            if renewed is None:
                return False

        if self.cart_id is not None:
            recovered = self._call(
                "POST",
                "/v2/carts/{}/recover".format(self.cart_id),
                (200,),
                payload={},
                recovery=False,
            )
            if recovered is None:
                return False

            def check_cart(response, _data):
                if not response.headers.get("ETag"):
                    raise ValueError("Recovered cart has no ETag")

            cart = self._call(
                "GET",
                "/v2/carts/{}".format(self.cart_id),
                (200,),
                recovery=False,
                check=check_cart,
            )
            if cart is None:
                return False
            self.cart_etag = cart[0].headers["ETag"]

        return True

    def _journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None

        if not self._login():
            return

        def check_catalog(response, data):
            if not isinstance(data, dict) or not isinstance(data.get("data"), dict):
                raise ValueError("Invalid catalog")
            products = data["data"].get("products")
            if not isinstance(products, list):
                raise ValueError("Catalog has no products")
            for product in products:
                if not isinstance(product, dict) or not present(product.get("id")):
                    continue
                for variant in product.get("variants", []):
                    if (
                        isinstance(variant, dict)
                        and variant.get("in_stock")
                        and present(variant.get("id"))
                    ):
                        response.selection = (product["id"], variant["id"])
                        return
            raise ValueError("Catalog has no in-stock variant")

        catalog = self._call("GET", "/v2/catalog", (200,), check=check_catalog)
        if catalog is None:
            return
        product_id, variant_id = catalog[0].selection

        def check_create(response, data):
            if not isinstance(data, dict) or not present(data.get("id")):
                raise ValueError("Cart creation has no cart ID")
            if not response.headers.get("ETag"):
                raise ValueError("Cart creation has no ETag")

        created = self._call(
            "POST",
            "/v2/carts",
            (201,),
            payload={"product_id": product_id, "variant_id": variant_id},
            check=check_create,
        )
        if created is None:
            return
        self.cart_id = created[1]["id"]
        self.cart_etag = created[0].headers["ETag"]

        def check_reservation(_response, data):
            if not isinstance(data, dict) or not present(data.get("status_url")):
                raise ValueError("Reservation response has no status URL")
            local_path(data["status_url"])

        reservation = self._call(
            "POST",
            "/v2/reservations",
            (202,),
            payload={"cart_id": self.cart_id},
            check=check_reservation,
        )
        if reservation is None:
            return

        job = reservation[1]
        status_url = local_path(job["status_url"])
        # Some responses expose the job ID separately; otherwise it is carried
        # by the returned status URL. The URL itself is always used for polling.
        job_id = job.get("job_id", job.get("id"))
        if not present(job_id):
            job_id = urlsplit(status_url).path.rstrip("/").split("/")[-1]
        if not present(job_id):
            return

        reservation_id = None
        for poll_number in range(5):
            if poll_number:
                sleep(0.055)

            def check_status(_response, data):
                if not isinstance(data, dict):
                    raise ValueError("Invalid reservation job status")
                status = data.get("status")
                if status == "ready":
                    if not present(data.get("reservation_id")):
                        raise ValueError("Ready job has no reservation ID")
                elif status == "pending":
                    if poll_number == 4:
                        raise ValueError("Reservation job did not become ready")
                elif status == "failed":
                    raise ValueError("Reservation job failed")
                else:
                    raise ValueError("Unknown reservation job status")

            polled = self._call(
                "GET", status_url, (200,), check=check_status
            )
            if polled is None:
                return
            if polled[1]["status"] == "ready":
                reservation_id = polled[1]["reservation_id"]
                break

        if not present(reservation_id):
            return

        def check_order(_response, data):
            if (
                not isinstance(data, dict)
                or data.get("accepted") is not True
                or not present(data.get("id"))
            ):
                raise ValueError("Order was not accepted")

        self._call(
            "POST",
            "/v2/orders",
            (201,),
            payload={
                "cart_id": self.cart_id,
                "reservation_id": reservation_id,
            },
            headers={
                "Idempotency-Key": "reservation-cart-{}".format(self.cart_id),
                "If-Match": self.cart_etag,
            },
            check=check_order,
        )

    @task
    def run_iteration(self):
        global _finished_users
        try:
            self._journey()
        finally:
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS:
                _finished_users += 1
                raise StopUser()


class ReservationShape(LoadTestShape):
    def tick(self):
        remaining = USER_COUNT - _finished_users
        if remaining <= 0 or self.get_run_time() > 120:
            return None
        return (remaining, USER_COUNT)
