import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  noCookiesReset: false,
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

function json(res) {
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function header(res, name) {
  const wanted = name.toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === wanted) return res.headers[key];
  }
  return null;
}

function update(state, res) {
  const body = json(res);
  if (body && body.csrf !== undefined && body.csrf !== null) {
    state.csrf = String(body.csrf);
  }
  const etag = header(res, 'ETag');
  if (etag) state.etag = etag;
  return body;
}

function raw(state, method, url, payload) {
  const res = http.request(method, url, payload === undefined ? null : JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'If-Match': state.etag,
      'Idempotency-Key': state.cart,
    },
    redirects: 0,
    timeout: '3s',
  });
  update(state, res);
  return res;
}

function locationUrl(location, requestPath) {
  if (!location) return null;
  if (location.startsWith('//')) return null;
  if (location.startsWith('/')) return BASE + location;
  if (/^https?:\/\//i.test(location)) {
    return location === BASE || location.startsWith(BASE + '/') ? location : null;
  }
  if (/^[a-z][a-z0-9+.-]*:/i.test(location)) return null;
  if (location.startsWith('?')) return BASE + requestPath + location;
  const parent = requestPath.slice(0, requestPath.lastIndexOf('/') + 1);
  return BASE + parent + location;
}

function login(state) {
  const formRes = raw(state, 'GET', BASE + '/v2/login-form');
  let formToken;
  try {
    formToken = formRes.html('input[name="csrf"]').first().attr('value');
  } catch (_) {
    formToken = null;
  }
  if (!check(formRes, {
    'login form has CSRF token': (r) => r.status === 200 && !!formToken,
  })) return false;

  const loginRes = raw(state, 'POST', BASE + '/v2/login', {
    username: state.username,
    password: 'bench',
    csrf: formToken,
  });
  const loginBody = json(loginRes);
  let freshCsrf = loginBody && loginBody.csrf !== undefined && loginBody.csrf !== null;

  const validStatus = check(loginRes, {
    'login status is successful': (r) => r.status === 200 || r.status === 302,
    'login response contains csrf': (r) => /"csrf"\s*:/.test(r.body || ''),
  });

  if (loginRes.status === 302) {
    const url = locationUrl(header(loginRes, 'Location'), '/v2/login');
    if (!check(loginRes, { 'login redirect has a local Location': () => !!url })) return false;
    const redirectRes = raw(state, 'GET', url);
    const redirectBody = json(redirectRes);
    if (redirectBody && redirectBody.csrf !== undefined && redirectBody.csrf !== null) {
      freshCsrf = true;
    }
    if (redirectBody && redirectBody.grant_id !== undefined && redirectBody.grant_id !== null) {
      state.grant = String(redirectBody.grant_id);
    }
    if (!check(redirectRes, { 'login redirect succeeds': (r) => r.status === 200 })) return false;
  } else if (!validStatus) {
    return false;
  }

  return check(loginRes, { 'login provides a CSRF token': () => !!freshCsrf });
}

function recover(state, error) {
  if (error === 'expired') {
    const renew = raw(state, 'POST', BASE + '/v2/session/renew', {});
    const body = json(renew);
    if (!check(renew, {
      'session renewal succeeds': (r) =>
        r.status === 200 && !!body && body.csrf !== undefined && body.csrf !== null,
    })) return false;
  } else if (error === 'session') {
    if (!login(state)) return false;
  } else {
    return false;
  }

  if (state.cart !== 'MISSING') {
    const res = raw(state, 'POST', BASE + '/v2/carts/' + encodeURIComponent(state.cart) + '/recover', {});
    if (!check(res, { 'cart recovery succeeds': (r) => r.status === 200 || r.status === 204 })) {
      return false;
    }
  }
  return true;
}

function operation(state, method, path, payload) {
  let res = raw(state, method, BASE + path, payload);
  const body = json(res);
  if (res.status === 401 && body && (body.error === 'expired' || body.error === 'session')) {
    if (recover(state, body.error)) {
      res = raw(state, method, BASE + path, payload);
    }
  }
  return res;
}

export default function () {
  const state = {
    username: 'bench-' + __VU,
    csrf: 'MISSING',
    cart: 'MISSING',
    etag: 'MISSING',
    grant: 'MISSING',
  };

  if (!login(state)) return;

  const catalog = operation(state, 'GET', '/v2/catalog');
  const catalogBody = json(catalog);
  const products = catalogBody && catalogBody.data && catalogBody.data.products;
  let product = null;
  let variant = null;
  if (Array.isArray(products)) {
    for (const item of products) {
      if (item && Array.isArray(item.variants) && item.variants[0] &&
          item.variants[0].in_stock === true &&
          item.id !== undefined && item.variants[0].id !== undefined) {
        product = String(item.id);
        variant = String(item.variants[0].id);
        break;
      }
    }
  }
  if (!check(catalog, {
    'catalog supplies a product with an in-stock first variant': (r) =>
      r.status === 200 && product !== null && variant !== null,
  })) return;

  const cartRes = operation(state, 'POST', '/v2/carts', {
    product_id: product,
    variant_id: variant,
    grant_id: state.grant,
  });
  const cartBody = json(cartRes);
  if (!check(cartRes, {
    'cart is created with a cart ID': (r) =>
      r.status === 201 && !!cartBody && typeof cartBody.id === 'string' &&
      /^cart-/.test(cartBody.id),
  })) return;
  state.cart = cartBody.id;

  const order = operation(state, 'POST', '/v2/orders', { cart_id: state.cart });
  const orderBody = json(order);
  check(order, {
    'order is created and accepted': (r) =>
      r.status === 201 && !!orderBody && orderBody.accepted === true,
  });
}

