import os
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")


class FlowError(Exception):
    pass


class InputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        fields = dict(attrs)
        if fields.get("name") == "csrf" and fields.get("value") and self.csrf is None:
            self.csrf = fields["value"]

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    created = 0
    completed = 0

    def on_start(self):
        ShopUser.created += 1
        self.username = f"bench-{ShopUser.created}"
        self.iterations = 0
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"

    def _local_location(self, location, origin_path):
        if not location:
            raise ValueError("Missing redirect Location")
        target = urlsplit(urljoin(self.host + origin_path, location))
        base = urlsplit(self.host)
        if (
            target.scheme != base.scheme
            or target.netloc != base.netloc
            or target.username is not None
            or target.password is not None
        ):
            raise ValueError("Redirect is outside the configured host")
        return urlunsplit(("", "", target.path or "/", target.query, ""))

    def _request(
        self, method, path, expected, payload=None, check=None, retry_auth=True
    ):
        for attempt in range(2):
            headers = {
                "Content-Type": "application/json",
                "X-CSRF-Token": self.csrf,
                "If-Match": self.etag,
                "Idempotency-Key": self.cart,
            }
            kwargs = {
                "headers": headers,
                "allow_redirects": False,
                "catch_response": True,
                "timeout": (2, 3),
            }
            if payload is not None:
                kwargs["json"] = payload

            failure = None
            recovery = None
            result = None
            with self.client.request(method, path, **kwargs) as response:
                try:
                    body = response.json()
                except (ValueError, TypeError):
                    body = None

                error = body.get("error") if isinstance(body, dict) else None
                if (
                    response.status_code == 401
                    and error in ("expired", "session")
                    and retry_auth
                    and attempt == 0
                ):
                    response.success()
                    recovery = error
                elif response.status_code not in expected:
                    failure = f"Unexpected HTTP {response.status_code}: {error}"
                    response.failure(failure)
                else:
                    try:
                        value = check(response, body) if check else None
                    except Exception as exc:
                        failure = f"Response assertion failed: {exc}"
                        response.failure(failure)
                    else:
                        if isinstance(body, dict) and body.get("csrf"):
                            self.csrf = body["csrf"]
                        if response.headers.get("ETag"):
                            self.etag = response.headers["ETag"]
                        result = (body, value)

            if failure:
                raise FlowError(failure)
            if recovery:
                self._recover(recovery)
                continue
            return result

        raise FlowError("Authentication retry exhausted")

    @staticmethod
    def _form_token(response, body):
        parser = InputParser()
        parser.feed(response.text)
        if not parser.csrf:
            raise ValueError("Login form has no csrf input")
        return parser.csrf

    def _login_response(self, response, body):
        if response.status_code == 302:
            return self._local_location(response.headers.get("Location"), "/v2/login")
        if not isinstance(body, dict) or not body.get("csrf"):
            raise ValueError("Login response has no csrf")
        return None

    def _login(self):
        _, token = self._request(
            "GET", "/v2/login-form", (200,), check=self._form_token, retry_auth=False
        )
        _, location = self._request(
            "POST",
            "/v2/login",
            (200, 302),
            payload={"username": self.username, "password": "bench", "csrf": token},
            check=self._login_response,
            retry_auth=False,
        )
        if location:
            def check_redirect(response, body):
                if (
                    self.csrf == "MISSING"
                    and (not isinstance(body, dict) or not body.get("csrf"))
                ):
                    raise ValueError("Redirect response has no csrf")

            self._request(
                "GET", location, (200,), check=check_redirect, retry_auth=False
            )

    def _recover(self, error):
        if error == "expired":
            def check_csrf(response, body):
                if not isinstance(body, dict) or not body.get("csrf"):
                    raise ValueError("Renewal response has no csrf")

            self._request(
                "POST",
                "/v2/session/renew",
                (200,),
                payload={},
                check=check_csrf,
                retry_auth=False,
            )
        else:
            self._login()

        if self.cart != "MISSING":
            self._request(
                "POST",
                f"/v2/carts/{self.cart}/recover",
                (200,),
                payload={},
                retry_auth=False,
            )

    @staticmethod
    def _select_product(response, body):
        if not isinstance(body, dict):
            raise ValueError("Catalog is not JSON")
        products = body.get("data", {}).get("products", [])
        for product in products:
            variants = product.get("variants", [])
            if variants and variants[0].get("in_stock") is True:
                product_id = product.get("id")
                variant_id = variants[0].get("id")
                if product_id and variant_id:
                    return product_id, variant_id
        raise ValueError("Catalog has no product with a stocked first variant")

    @staticmethod
    def _cart_id(response, body):
        cart = body.get("id") if isinstance(body, dict) else None
        if not isinstance(cart, str) or not cart.startswith("cart-"):
            raise ValueError("Cart response has no cart ID")
        return cart

    @staticmethod
    def _accepted(response, body):
        if not isinstance(body, dict) or body.get("accepted") is not True:
            raise ValueError("Order was not accepted")

    def _journey(self):
        self.client.cookies.clear()
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        grant = "MISSING"

        self._login()
        _, selection = self._request(
            "GET", "/v2/catalog", (200,), check=self._select_product
        )
        product, variant = selection

        _, cart = self._request(
            "POST",
            "/v2/carts",
            (201,),
            payload={
                "product_id": product,
                "variant_id": variant,
                "grant_id": grant,
            },
            check=self._cart_id,
        )
        self.cart = cart

        self._request(
            "POST",
            "/v2/orders",
            (201,),
            payload={"cart_id": self.cart},
            check=self._accepted,
        )

    @task
    def run_iteration(self):
        try:
            self._journey()
        except FlowError:
            pass
        finally:
            self.iterations += 1

        if self.iterations >= 2:
            ShopUser.completed += 1
            raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        remaining = 2 - ShopUser.completed
        if remaining <= 0:
            return None
        return remaining, 1000
