import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static ChainBuilder login() {
    return exec(session -> session.removeAll("form", "loginLocation", "loginStatus"))
      .exec(
        http("Login form")
          .get("/v2/login-form")
          .check(
            status().is(200),
            css("input[name=csrf]", "value").saveAs("form")
          )
      )
      .exitHereIfFailed()
      .exec(
        http("Login")
          .post("/v2/login")
          .header("Content-Type", "application/json")
          .body(StringBody(
            "{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{form}\"}"
          ))
          .check(
            status().in(200, 302).saveAs("loginStatus"),
            checkIf(session -> session.getInt("loginStatus") == 200)
              .then(jsonPath("$.csrf").saveAs("csrf")),
            checkIf(session -> session.getInt("loginStatus") == 302)
              .then(header("Location").saveAs("loginLocation"))
          )
      )
      .exitHereIfFailed()
      .doIf(session -> session.getInt("loginStatus") == 302).then(
        exec(
          http("Login redirect")
            .get("#{loginLocation}")
            .check(
              status().is(200),
              jsonPath("$.csrf").saveAs("csrf")
            )
        )
      )
      .exitHereIfFailed();
  }

  private static ChainBuilder recoverCart() {
    return doIf(session -> "expired".equals(session.getString("patchError"))).then(
        exec(
          http("Renew session")
            .post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(
              status().is(200),
              jsonPath("$.csrf").saveAs("csrf")
            )
        )
      )
      .doIf(session -> "session".equals(session.getString("patchError"))).then(
        login()
      )
      .exitHereIfFailed()
      .exec(
        http("Recover cart")
          .post("/v2/carts/#{cart}/recover")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .body(StringBody("{}"))
          .check(
            status().is(200),
            regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"),
            header("ETag").optional().saveAs("etag")
          )
      )
      .exitHereIfFailed();
  }

  private static ChainBuilder patchCart() {
    return exec(
      http("Update quantity")
        .patch("/v2/carts/#{cart}")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .header("If-Match", "#{etag}")
        .body(StringBody("{\"quantity\":#{quantity}}"))
        .check(
          status().in(200, 401, 412).saveAs("patchStatus"),
          checkIf(session -> session.getInt("authRetries") > 0)
            .then(status().not(401)),
          checkIf(session -> session.getInt("versionRetries") > 0)
            .then(status().not(412)),
          checkIf(session -> session.getInt("patchStatus") == 401)
            .then(jsonPath("$.error").in("expired", "session").saveAs("patchError")),
          regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"),
          header("ETag").optional().saveAs("etag")
        )
    );
  }

  private static ChainBuilder journey() {
    return exec(flushCookieJar())
      .exec(session -> session.removeAll(
        "csrf", "cart", "etag", "product", "variant", "patchError"
      ))
      .pause(session -> Duration.ofMillis(((Number) session.get("delay")).longValue()))
      .exec(login())
      .exec(
        http("Catalog")
          .get("/v2/catalog")
          .check(
            status().is(200),
            jmesPath("data.products[?variants[0].in_stock == `true`].id | [0]")
              .saveAs("product"),
            jmesPath("data.products[?variants[0].in_stock == `true`].variants[0].id | [0]")
              .saveAs("variant")
          )
      )
      .exitHereIfFailed()
      .exec(
        http("Create cart")
          .post("/v2/carts")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .body(StringBody(
            "{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\"}"
          ))
          .check(
            status().is(201),
            jsonPath("$.id").saveAs("cart"),
            jsonPath("$.csrf").optional().saveAs("csrf"),
            header("ETag").saveAs("etag")
          )
      )
      .exitHereIfFailed()
      .exec(session -> session
        .set("patchStatus", 0)
        .set("authRetries", 0)
        .set("versionRetries", 0))
      .repeat(3).on(
        doIf(session -> session.getInt("patchStatus") != 200).then(
          exec(session -> session.remove("patchError")),
          patchCart(),
          exitHereIfFailed(),
          doIf(session -> session.getInt("patchStatus") == 401).then(
            exec(session -> session.set("authRetries", session.getInt("authRetries") + 1)),
            recoverCart()
          ),
          doIf(session -> session.getInt("patchStatus") == 412).then(
            exec(session -> session.set("versionRetries", session.getInt("versionRetries") + 1)),
            exec(
              http("Read cart version")
                .get("/v2/carts/#{cart}")
                .check(
                  status().is(200),
                  header("ETag").saveAs("etag")
                )
            ),
            exitHereIfFailed()
          )
        )
      )
      .exitHereIfFailed()
      .exec(
        http("Commit order")
          .post("/v2/orders")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .header("If-Match", "#{etag}")
          .header("Idempotency-Key", "#{cart}")
          .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
          .check(
            status().is(201),
            jsonPath("$.accepted").is("true"),
            jsonPath("$.id").exists(),
            jsonPath("$.csrf").optional().saveAs("csrf")
          )
      )
      .exitHereIfFailed();
  }

  private final HttpProtocolBuilder httpProtocol = http
    .baseUrl(System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000"))
    .disableFollowRedirect();

  private final ScenarioBuilder scenario = scenario("CSV-driven users")
    .feed(jsonFile("/fixtures/accounts.json").queue())
    .repeat(2).on(journey());

  {
    setUp(scenario.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}

