import http from 'k6/http';
import { check, fail, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import { parseHTML } from 'k6/html';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const accounts = new SharedArray('accounts', () =>
  JSON.parse(open('/fixtures/accounts.json'))
);

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (base !== 'http://127.0.0.1:8000') {
  throw new Error('BASE_URL must target http://127.0.0.1:8000');
}

function requireCheck(condition, name) {
  if (!check(condition, { [name]: (ok) => ok })) {
    fail(name);
  }
}

function target(path) {
  requireCheck(typeof path === 'string' && path.length > 0, 'URL is present');
  if (path.startsWith('http://127.0.0.1:8000/')) return path;
  requireCheck(
    !path.startsWith('//') && !path.includes('\\') && !/^[a-z][a-z0-9+.-]*:/i.test(path),
    'URL targets the local shop'
  );
  return base + (path.startsWith('/') ? path : '/' + path);
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key of Object.keys(response.headers || {})) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return undefined;
}

function json(response) {
  try {
    return response.json();
  } catch (_) {
    return {};
  }
}

function successful(response) {
  return response.status >= 200 && response.status < 300;
}

function capture(state, response, captureEtag) {
  if (response.status >= 200 && response.status < 400) {
    const body = json(response);
    if (body && typeof body.csrf === 'string' && body.csrf) {
      state.csrf = body.csrf;
    }
    if (captureEtag) {
      const etag = header(response, 'ETag');
      if (etag) state.etag = etag;
    }
  }
}

function raw(state, method, path, payload, extraHeaders, captureEtag) {
  const headers = Object.assign({}, extraHeaders || {});
  if (method !== 'GET') {
    headers['Content-Type'] = 'application/json';
    if (state.csrf) headers['X-CSRF-Token'] = state.csrf;
  }
  const response = http.request(
    method,
    target(path),
    payload === undefined ? null : JSON.stringify(payload),
    { headers, jar: state.jar, redirects: 0, timeout: '3s' }
  );
  capture(state, response, captureEtag);
  return response;
}

function login(state) {
  state.csrf = null;
  state.grant = null;

  const form = raw(state, 'GET', '/v2/login-form');
  requireCheck(form.status === 200, 'login form returned 200');
  const token = parseHTML(form.body).find('input[name="csrf"]').first().attr('value');
  requireCheck(typeof token === 'string' && token.length > 0, 'login form contains csrf');

  let response = raw(state, 'POST', '/v2/login', {
    username: state.account.username,
    password: state.account.password,
    csrf: token,
  });
  requireCheck(response.status === 200 || response.status === 302, 'login succeeded');

  if (response.status === 302) {
    const location = header(response, 'Location');
    requireCheck(typeof location === 'string' && location.length > 0, 'login redirect has a location');
    response = raw(state, 'GET', location);
    requireCheck(response.status === 200, 'login redirect returned 200');
  }

  const body = json(response);
  if (body && body.grant_id) state.grant = body.grant_id;
  requireCheck(typeof state.csrf === 'string' && state.csrf.length > 0, 'login supplied csrf');
}

function recoverSession(state, reason) {
  const renewed = raw(state, 'POST', '/v2/session/renew', {});
  if (!successful(renewed)) {
    requireCheck(reason === 'session', 'expired session renewed');
    login(state);
  } else {
    requireCheck(typeof state.csrf === 'string' && state.csrf.length > 0, 'renewal supplied csrf');
  }

  if (state.cart) {
    const recovered = raw(
      state, 'POST',
      '/v2/carts/' + encodeURIComponent(state.cart) + '/recover',
      {}, undefined, true
    );
    requireCheck(successful(recovered), 'cart recovered');
  }
}

function request(state, method, path, payload, headers, captureEtag, recovery) {
  const budget = recovery || { used: false };
  const send = () => raw(
    state, method, path, payload,
    typeof headers === 'function' ? headers() : headers,
    captureEtag
  );

  let response = send();
  const body = json(response);
  if (
    response.status === 401 &&
    body &&
    (body.error === 'expired' || body.error === 'session') &&
    !budget.used
  ) {
    budget.used = true;
    recoverSession(state, body.error);
    response = send();
  }
  return response;
}

function readCart(state) {
  const response = request(
    state, 'GET', '/v2/carts/' + encodeURIComponent(state.cart),
    undefined, undefined, true
  );
  requireCheck(response.status === 200, 'cart read succeeded');
  requireCheck(typeof header(response, 'ETag') === 'string', 'cart read supplied etag');
}

export default function () {
  const account = accounts[__VU - 1];
  requireCheck(!!account, 'fixture row exists for VU');
  requireCheck(
    typeof account.username === 'string' &&
    typeof account.password === 'string' &&
    typeof account.quantity === 'number' &&
    Number.isInteger(account.quantity) &&
    account.quantity >= 1 && account.quantity <= 20 &&
    typeof account.delay === 'number' && account.delay >= 0,
    'fixture fields retain their types'
  );

  if (account.delay > 0) sleep(account.delay / 1000);

  const state = {
    account,
    jar: new http.CookieJar(),
    csrf: null,
    cart: null,
    etag: null,
    grant: null,
  };

  login(state);

  const catalog = request(state, 'GET', '/v2/catalog');
  requireCheck(catalog.status === 200, 'catalog returned 200');
  const catalogBody = json(catalog);
  const products = catalogBody && catalogBody.data && catalogBody.data.products;
  requireCheck(Array.isArray(products), 'catalog contains products');

  const product = products.find(
    (p) => p && Array.isArray(p.variants) &&
      p.variants.length > 0 && p.variants[0].in_stock === true
  );
  requireCheck(!!product && !!product.id && !!product.variants[0].id, 'catalog has an in-stock variant');

  const cartPayload = {
    product_id: product.id,
    variant_id: product.variants[0].id,
  };
  if (state.grant) cartPayload.grant_id = state.grant;

  const created = request(state, 'POST', '/v2/carts', cartPayload, undefined, true);
  const cartBody = json(created);
  requireCheck(created.status === 201 && !!cartBody.id, 'cart created');
  state.cart = cartBody.id;
  state.grant = null;
  requireCheck(typeof state.etag === 'string' && state.etag.length > 0, 'cart creation supplied etag');

  const cartPath = '/v2/carts/' + encodeURIComponent(state.cart);
  const patchBudget = { used: false };
  const patchHeaders = () => ({ 'If-Match': state.etag });
  const quantityPayload = { quantity: account.quantity };
  let patched = request(
    state, 'PATCH', cartPath, quantityPayload, patchHeaders, true, patchBudget
  );
  if (patched.status === 412) {
    readCart(state);
    patched = request(
      state, 'PATCH', cartPath, quantityPayload, patchHeaders, true, patchBudget
    );
  }
  requireCheck(successful(patched), 'cart quantity updated');
  if (!header(patched, 'ETag')) readCart(state);

  const order = request(
    state, 'POST', '/v2/orders', { cart_id: state.cart },
    () => ({ 'If-Match': state.etag, 'Idempotency-Key': state.cart })
  );
  const orderBody = json(order);
  requireCheck(
    order.status === 201 && orderBody.accepted === true && !!orderBody.id,
    'order accepted'
  );
}

