import json
import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"]
base_parts = urlsplit(BASE_URL)
if (
    base_parts.scheme != "http"
    or base_parts.hostname != "127.0.0.1"
    or base_parts.port != 8000
    or base_parts.path not in ("", "/")
    or base_parts.query
    or base_parts.fragment
):
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

with open("/fixtures/accounts.json", encoding="utf-8") as fixture:
    ACCOUNTS = json.load(fixture)

if not isinstance(ACCOUNTS, list) or len(ACCOUNTS) != 2:
    raise ValueError("Expected two account records")
for record in ACCOUNTS:
    if (
        not isinstance(record, dict)
        or not isinstance(record.get("username"), str)
        or not isinstance(record.get("password"), str)
        or type(record.get("quantity")) is not int
        or not 1 <= record["quantity"] <= 20
        or type(record.get("delay")) not in (int, float)
    ):
        raise ValueError("Invalid account record")


class JourneyFailure(Exception):
    pass


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.form_action = None
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            self.form_action = attrs.get("action", "")
        elif tag == "input" and attrs.get("name") == "csrf":
            value = attrs.get("value")
            if value and "disabled" not in attrs:
                self.candidates.append((self.form_action, value))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag == "form":
            self.form_action = None

    def token(self):
        for action, value in self.candidates:
            if action and urlsplit(action).path.rstrip("/") == "/v2/login":
                return value
        return self.candidates[0][1] if self.candidates else None


def safe_location(location):
    if not isinstance(location, str) or not location:
        raise ValueError("Missing Location")
    resolved = urlsplit(urljoin(BASE_URL.rstrip("/") + "/", location))
    if (
        resolved.scheme != "http"
        or resolved.hostname != "127.0.0.1"
        or resolved.port != 8000
        or resolved.username is not None
        or resolved.password is not None
        or resolved.fragment
    ):
        raise ValueError("Location is not on the target")
    return resolved.path + ("?" + resolved.query if resolved.query else "")


def require(condition, message):
    if not condition:
