    require(isinstance(data, dict), "Catalog is not an object")
    nested = data.get("data")
    require(isinstance(nested, dict), "Catalog data is missing")
    products = nested.get("products")
    require(isinstance(products, list), "Catalog products are missing")
    for product in products:
        if not isinstance(product, dict):
