        authenticated=True,
        extra_headers=None,
        validator=None,
        recoverable=False,
        allow_precondition=False,
        allow_revoked_renewal=False,
    ):
        headers = dict(extra_headers or {})
        if authenticated and method != "GET":
            headers["X-CSRF-Token"] = self.csrf or ""
        kwargs = {
            "headers": headers,
            "allow_redirects": False,
            "catch_response": True,
            "timeout": (2, 3),
        }
        if payload is not None:
            kwargs["json"] = payload

        with self.client.request(method, path, **kwargs) as response:
            try:
                data = response.json()
            except (ValueError, TypeError):
                data = None

            error = data.get("error") if isinstance(data, dict) else None
            if response.status_code == 401 and error in ("expired", "session"):
                if recoverable:
                    response.success()
                    return "recover", response, data
                if allow_revoked_renewal and error == "session":
                    response.success()
                    return "revoked", response, data

            if response.status_code == 412 and allow_precondition:
                response.success()
                return "precondition", response, data

            if response.status_code not in statuses:
                response.failure(
                    f"Unexpected status {response.status_code}; error={error!r}"
                )
