                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                if response.headers.get("ETag"):
                    self.etag = response.headers["ETag"]
            except (ValueError, TypeError, KeyError) as exc:
                response.failure(str(exc))
                return "failure", response, data

