        _, response, _ = self._call(
            "GET", "/v2/login-form", {200},
            authenticated=False, validator=validate_form,
        )
        parser = LoginFormParser()
        parser.feed(response.text)
        form_token = parser.token()
        self.csrf = None

        def validate_login(response, data):
            if response.status_code == 302:
                safe_location(response.headers.get("Location"))
            else:
                require(isinstance(data, dict), "Login response is not JSON")
                require(bool(data.get("csrf")), "Login CSRF is missing")
                require("user" in data, "Login user is missing")

        _, response, _ = self._call(
            "POST",
            "/v2/login",
            {200, 302},
            payload={
                "username": self.record["username"],
                "password": self.record["password"],
                "csrf": form_token,
            },
            authenticated=False,
            validator=validate_login,
        )
        if response.status_code == 302:
            location = safe_location(response.headers.get("Location"))

            def validate_redirect(_response, data):
                require(
                    bool(self.csrf) or (
                        isinstance(data, dict) and bool(data.get("csrf"))
                    ),
                    "Login redirect did not supply CSRF",
                )

            self._call(
                "GET", location, {200},
                authenticated=False, validator=validate_redirect,
            )

    def _recover_session(self):
        def validate_renewal(_response, data):
            require(
                isinstance(data, dict) and bool(data.get("csrf")),
                "Renewal CSRF is missing",
            )

        outcome, _, _ = self._raw(
            "POST",
            "/v2/session/renew",
            {200},
            payload={},
            validator=validate_renewal,
            allow_revoked_renewal=True,
        )
        if outcome == "revoked":
            self._login()
        elif outcome != "ok":
            raise JourneyFailure()

        if self.cart_id is not None:
            path = "/v2/carts/" + quote(str(self.cart_id), safe="") + "/recover"
            outcome, _, _ = self._raw("POST", path, {200}, payload={})
            if outcome != "ok":
                raise JourneyFailure()

    def _read_cart(self, path):
        def validate_cart(response, _data):
            require(bool(response.headers.get("ETag")), "Cart ETag is missing")

        self._call("GET", path, {200}, validator=validate_cart)

    def _journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self._login()

        _, _, catalog = self._call(
            "GET", "/v2/catalog", {200},
            validator=lambda _response, data: catalog_choice(data),
        )
        product_id, variant_id = catalog_choice(catalog)

        def validate_creation(response, data):
            require(
                isinstance(data, dict)
                and isinstance(data.get("id"), str)
                and data["id"].startswith("cart-"),
                "Cart ID is missing",
            )
            require(bool(response.headers.get("ETag")), "Cart ETag is missing")

        _, _, cart = self._call(
            "POST",
            "/v2/carts",
            {201},
            payload={"product_id": product_id, "variant_id": variant_id},
            validator=validate_creation,
        )
        self.cart_id = cart["id"]
        cart_path = "/v2/carts/" + quote(self.cart_id, safe="")
        quantity_payload = {"quantity": self.record["quantity"]}

        outcome, response, _ = self._call(
            "PATCH",
            cart_path,
            {200, 204},
            payload=quantity_payload,
            match_cart=True,
            allow_precondition=True,
        )
        if outcome == "precondition":
            self._read_cart(cart_path)
            _, response, _ = self._call(
                "PATCH",
                cart_path,
                {200, 204},
                payload=quantity_payload,
                match_cart=True,
            )
        if not response.headers.get("ETag"):
            self._read_cart(cart_path)

        def validate_order(_response, data):
            require(
                isinstance(data, dict)
                and data.get("accepted") is True
                and bool(data.get("id")),
                "Order was not accepted",
            )

        self._call(
            "POST",
            "/v2/orders",
            {201},
            payload={"cart_id": self.cart_id},
            extra_headers={"Idempotency-Key": self.cart_id},
            match_cart=True,
            validator=validate_order,
        )

    @task
    def run_iteration(self):
        if self.iteration >= 2:
            raise StopUser()
        try:
            self._journey()
        except JourneyFailure:
            raise StopUser()
        self.iteration += 1
        if self.iteration >= 2:
            raise StopUser()


class DataShape(LoadTestShape):
    def tick(self):
        if ShopUser.finished >= 2 or self.get_run_time() >= 90:
            return None
        return (2, 100)
