import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const expectedStatuses = http.expectedStatuses({ min: 200, max: 299 }, 302, 401);

export const options = {
  noCookiesReset: true,
  scenarios: {
    checkout: {
      executor: 'constant-arrival-rate',
      rate: 2,
      timeUnit: '1s',
      duration: '38s',
      preAllocatedVUs: 4,
      maxVUs: 4,
      gracefulStop: '5s',
    },
  },
};

function urlFor(path) {
  if (path.startsWith(BASE_URL + '/')) return path;
  if (path.startsWith('/') && !path.startsWith('//')) return BASE_URL + path;
  if (!path.includes('://') && !path.startsWith('//')) return BASE_URL + '/' + path;
  throw new Error('Refusing an off-target URL');
}

function json(response) {
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return null;
}

function capture(state, response) {
  if (!response || !((response.status >= 200 && response.status < 300) || response.status === 302)) return;
  const body = json(response);
  if (body && body.csrf) state.csrf = body.csrf;
  const etag = header(response, 'ETag');
  if (etag) state.etag = etag;
}

function send(state, method, path, payload, extraHeaders, authenticated) {
  const headers = Object.assign({}, extraHeaders || {});
  if (method !== 'GET') {
    headers['Content-Type'] = 'application/json';
    if (authenticated && state.csrf) headers['X-CSRF-Token'] = state.csrf;
  }

  const response = http.request(
    method,
    urlFor(path),
    payload === undefined ? null : JSON.stringify(payload),
    {
      headers,
      redirects: 0,
      timeout: '3s',
      responseCallback: expectedStatuses,
    }
  );
  capture(state, response);
  return response;
}

function login(state) {
  state.csrf = null;
  state.grant = null;

  const form = send(state, 'GET', '/v2/login-form', undefined, null, false);
  if (!check(form, { 'login form returned 200': (r) => r.status === 200 })) return false;

  let formCsrf = null;
  try {
    formCsrf = parseHTML(form.body).find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    // The check below records an invalid form.
  }
  if (!check(formCsrf, { 'login form contains CSRF': (v) => !!v })) return false;

  let response = send(state, 'POST', '/v2/login', {
    username: `bench-${__VU}`,
    password: 'bench',
    csrf: formCsrf,
  }, null, false);

  if (!check(response, {
    'login accepted': (r) => r.status === 200 || r.status === 302,
  })) return false;

  if (response.status === 302) {
    const location = header(response, 'Location');
    if (!check(location, { 'login redirect has location': (v) => !!v })) return false;
    response = send(state, 'GET', location, undefined, null, false);
    if (!check(response, { 'login redirect returned 200': (r) => r.status === 200 })) return false;
  }

  const body = json(response);
  if (body && body.grant_id) state.grant = body.grant_id;
  return check(state.csrf, { 'login supplied CSRF': (v) => !!v });
}

function recover(state, error) {
  const renew = send(state, 'POST', '/v2/session/renew', {}, null, true);
  let renewed = renew.status === 200 && !!(json(renew) || {}).csrf;

  if (!renewed && error === 'session') renewed = login(state);
  if (!check(renewed, { 'session recovery succeeded': (v) => v === true })) return false;

  if (state.cart !== null) {
    const response = send(
      state,
      'POST',
      `/v2/carts/${encodeURIComponent(state.cart)}/recover`,
      {},
      null,
      true
    );
    if (!check(response, {
      'cart recovery succeeded': (r) => r.status >= 200 && r.status < 300,
    })) return false;
  }
  return true;
}

function authenticatedRequest(state, method, path, payload, makeHeaders) {
  function attempt() {
    return send(
      state,
      method,
      path,
      payload,
      makeHeaders ? makeHeaders() : null,
      true
    );
  }

  let response = attempt();
  if (response.status === 401) {
    const body = json(response);
    const error = body && body.error;
    if ((error === 'expired' || error === 'session') && recover(state, error)) {
      response = attempt();
    }
  }
  return response;
}

export default function () {
  const state = { csrf: null, cart: null, etag: null, grant: null };
  if (!login(state)) return;

  const catalog = authenticatedRequest(state, 'GET', '/v2/catalog');
  if (!check(catalog, { 'catalog returned 200': (r) => r.status === 200 })) return;

  const catalogBody = json(catalog);
  const products = catalogBody && catalogBody.data && catalogBody.data.products;
  let product = null;
  let variant = null;
  if (Array.isArray(products)) {
    for (const candidate of products) {
      if (candidate && Array.isArray(candidate.variants) &&
          candidate.variants[0] && candidate.variants[0].in_stock === true) {
        product = candidate.id;
        variant = candidate.variants[0].id;
        break;
      }
    }
  }
  if (!check({ product, variant }, {
    'catalog has an eligible product and variant': (v) =>
      v.product !== null && v.product !== undefined &&
      v.variant !== null && v.variant !== undefined,
  })) return;

  const cartPayload = { product_id: product, variant_id: variant };
  if (state.grant) cartPayload.grant_id = state.grant;

  const cartResponse = authenticatedRequest(state, 'POST', '/v2/carts', cartPayload);
  const cartBody = json(cartResponse);
  if (!check(cartResponse, {
    'cart created': (r) => r.status === 201 && !!cartBody && !!cartBody.id,
  })) return;
  state.cart = cartBody.id;

  const order = authenticatedRequest(
    state,
    'POST',
    '/v2/orders',
    { cart_id: state.cart },
    () => {
      const headers = { 'Idempotency-Key': String(state.cart) };
      if (state.etag) headers['If-Match'] = state.etag;
      return headers;
    }
  );
  const orderBody = json(order);
  check(order, {
    'order committed': (r) =>
      r.status === 201 && !!orderBody && orderBody.accepted === true && !!orderBody.id,
  });
}

import os
import time
from html.parser import HTMLParser
from urllib.parse import urlsplit

import gevent
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"]
INTERVAL = 60.0 / 121.2
RUN_DURATION = 38.0

run_epoch = None
next_iteration = None
next_user_number = 0


class JourneyError(Exception):
    pass


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        values = dict(attrs)
        if values.get("name") == "csrf" and values.get("value"):
            if self.csrf is None:
                self.csrf = values["value"]

    handle_startendtag = handle_starttag


def same_origin_location(location):
    if not location:
        return None
    base = urlsplit(BASE_URL)
    parsed = urlsplit(location)
    if parsed.scheme or parsed.netloc:
        if parsed.scheme != base.scheme or parsed.netloc != base.netloc:
            return None
        path = parsed.path or "/"
        if parsed.query:
            path += "?" + parsed.query
        return path
    if not location.startswith("/") or location.startswith("//"):
        return None
    return location


class CheckoutUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        global next_user_number
        next_user_number += 1
        self.username = "bench-%d" % ((next_user_number - 1) % 16 + 1)
        self.csrf = None
        self.cart_id = None
        self.etag = None

    def call(
        self,
        method,
        path,
        expected,
        payload=None,
        validator=None,
        use_etag=False,
        idempotency_key=None,
        allow_recovery=True,
    ):
        for attempt in range(2):
            headers = {}
            if method != "GET" and self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            if use_etag and self.etag:
                headers["If-Match"] = self.etag
            if idempotency_key is not None:
                headers["Idempotency-Key"] = str(idempotency_key)

            kwargs = {
                "headers": headers,
                "catch_response": True,
                "allow_redirects": False,
                "timeout": (2, 3),
            }
            if payload is not None:
                kwargs["json"] = payload

            recovery_reason = None
            failure = None
            data = {}
            response_headers = {}
            text = ""
            status = 0

            with self.client.request(method, path, **kwargs) as response:
                status = response.status_code
                response_headers = dict(response.headers)
                text = response.text or ""
                try:
                    parsed = response.json()
                    if isinstance(parsed, dict):
                        data = parsed
                except (ValueError, TypeError):
                    pass

                if (
                    status == 401
                    and data.get("error") in ("expired", "session")
                    and allow_recovery
                    and attempt == 0
                ):
                    recovery_reason = data["error"]
                    response.success()
                elif status not in expected:
                    failure = "Unexpected HTTP status %s" % status
                    response.failure(failure)
                else:
                    try:
                        failure = validator(data, response) if validator else None
                    except Exception as exc:
                        failure = "Response validation failed: %s" % exc
                    if failure:
                        response.failure(failure)
                    else:
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        if response.headers.get("ETag"):
                            self.etag = response.headers["ETag"]

            if failure:
                raise JourneyError(failure)
            if recovery_reason:
                self.recover_session(recovery_reason)
                continue
            return status, data, response_headers, text

        raise JourneyError("Operation recovery exhausted")

    def login(self):
        self.csrf = None
        form = LoginFormParser()

        def validate_form(data, response):
            form.feed(response.text or "")
            if not form.csrf:
                return "Login form has no CSRF input"

        self.call("GET", "/v2/login-form", {200}, validator=validate_form,
                  allow_recovery=False)

        def validate_login(data, response):
            if response.status_code == 302:
                if not same_origin_location(response.headers.get("Location")):
                    return "Login redirect has no valid Location"
            elif not data.get("csrf"):
                return "Login response has no CSRF token"

        status, data, headers, _ = self.call(
            "POST",
            "/v2/login",
            {200, 302},
            payload={"username": self.username, "password": "bench", "csrf": form.csrf},
            validator=validate_login,
            allow_recovery=False,
        )
        if status == 302:
            location = same_origin_location(headers.get("Location"))

            def validate_redirect(data, response):
                if not data.get("csrf") and not self.csrf:
                    return "Login redirect has no CSRF token"

            self.call("GET", location, {200}, validator=validate_redirect,
                      allow_recovery=False)

    def recover_session(self, reason):
        if reason == "expired":
            def validate_renew(data, response):
                if not data.get("csrf"):
                    return "Session renewal has no CSRF token"

            self.call(
                "POST", "/v2/session/renew", {200}, payload={},
                validator=validate_renew, allow_recovery=False,
            )
        else:
            self.login()

        if self.cart_id is not None:
            self.call(
                "POST",
                "/v2/carts/%s/recover" % self.cart_id,
                {200, 201},
                payload={},
                allow_recovery=False,
            )

    def journey(self):
        self.cart_id = None
        self.etag = None
        self.login()

        selection = {}

        def validate_catalog(data, response):
            products = data.get("data", {}).get("products", [])
            if not isinstance(products, list):
                return "Catalog products are invalid"
            for product in products:
                variants = product.get("variants", [])
                if (
                    variants
                    and variants[0].get("in_stock") is True
                    and product.get("id") is not None
                    and variants[0].get("id") is not None
                ):
                    selection["product_id"] = product["id"]
                    selection["variant_id"] = variants[0]["id"]
                    return None
            return "Catalog has no eligible product and first variant"

        self.call("GET", "/v2/catalog", {200}, validator=validate_catalog)

        def validate_cart(data, response):
            cart_id = data.get("id")
            if not isinstance(cart_id, str) or not cart_id.startswith("cart-"):
                return "Cart response has no valid cart ID"
            if not response.headers.get("ETag"):
                return "Cart response has no ETag"

        _, cart, _, _ = self.call(
            "POST", "/v2/carts", {201}, payload=selection,
            validator=validate_cart,
        )
        self.cart_id = cart["id"]

        def validate_order(data, response):
            if data.get("accepted") is not True:
                return "Order was not accepted"
            if not data.get("id"):
                return "Accepted order has no ID"

        self.call(
            "POST",
            "/v2/orders",
            {201},
            payload={"cart_id": self.cart_id},
            validator=validate_order,
            use_etag=True,
            idempotency_key=self.cart_id,
        )

    @task
    def checkout_iteration(self):
        global next_iteration
        now = time.monotonic()
        if run_epoch is not None and now >= run_epoch + RUN_DURATION:
            raise StopUser()

        slot = max(now, next_iteration if next_iteration is not None else now)
        next_iteration = slot + INTERVAL
        if slot > now:
            gevent.sleep(slot - now)

        if run_epoch is not None and time.monotonic() >= run_epoch + RUN_DURATION:
            raise StopUser()

        try:
            self.journey()
        except JourneyError:
            pass


class CheckoutShape(LoadTestShape):
    def tick(self):
        global run_epoch
        if run_epoch is None:
            run_epoch = time.monotonic()
        if time.monotonic() >= run_epoch + RUN_DURATION + 1.0:
            return None
        return (4, 100)

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.Iterator;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String BASE_URL =
      System.getenv("BASE_URL") == null
          ? "http://127.0.0.1:8000"
          : System.getenv("BASE_URL");

  private final HttpProtocolBuilder httpProtocol = http
      .baseUrl(BASE_URL)
      .disableFollowRedirect()
      .contentTypeHeader("application/json");

  private final Iterator<Map<String, Object>> users = List.of(
      Map.<String, Object>of("username", "bench-1"),
      Map.<String, Object>of("username", "bench-2")
  ).iterator();

  private final ScenarioBuilder journey = scenario("journey")
      .feed(users)
      .repeat(2).on(
          exec(flushCookieJar()),
          exec(session -> session
              .removeAll("form", "loginLocation", "product", "variant",
                  "cart", "etag", "grant")
              .set("csrf", "MISSING")
              .set("loginStatus", 0)),

          exec(http("HTTPSamplerProxy-4")
              .get("/v2/login-form")
              .check(
                  status().is(200),
                  css("input[name=csrf]", "value").saveAs("form")
              )),

          exec(http("HTTPSamplerProxy-12")
              .post("/v2/login")
              .body(StringBody(
                  "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
              .check(
                  status().in(200, 302),
                  status().saveAs("loginStatus"),
                  regex("\"csrf\"\\s*:").exists(),
                  jsonPath("$.csrf").optional().saveAs("csrf"),
                  header("Location").optional().saveAs("loginLocation")
              )),

          doIf(session -> session.getInt("loginStatus") == 302).then(
              exec(http("HTTPSamplerProxy-21")
                  .get("#{loginLocation}")
                  .check(
                      status().is(200),
                      jsonPath("$.csrf").optional().saveAs("csrf"),
                      jsonPath("$.grant_id").optional().saveAs("grant")
                  ))
          ),

          exec(http("HTTPSamplerProxy-26")
              .get("/v2/catalog")
              .check(
                  status().is(200),
                  jsonPath("$.csrf").optional().saveAs("csrf"),
                  jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                      .find().saveAs("product"),
                  jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                      .find().saveAs("variant")
              )),

          exec(http("HTTPSamplerProxy-31")
              .post("/v2/carts")
              .header("X-CSRF-Token", "#{csrf}")
              .body(StringBody(session -> {
                String body = "{\"product_id\":\"" + session.getString("product")
                    + "\",\"variant_id\":\"" + session.getString("variant") + "\"";
                if (session.contains("grant")) {
                  body += ",\"grant_id\":\"" + session.getString("grant") + "\"";
                }
                return body + "}";
              }))
              .check(
                  status().is(201),
                  regex("\"id\"\\s*:\\s*\"cart-").exists(),
                  jsonPath("$.id").saveAs("cart"),
                  jsonPath("$.csrf").optional().saveAs("csrf"),
                  header("ETag").saveAs("etag")
              )),

          exec(http("HTTPSamplerProxy-38")
              .post("/v2/orders")
              .header("X-CSRF-Token", "#{csrf}")
              .header("If-Match", "#{etag}")
              .header("Idempotency-Key", "#{cart}")
              .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
              .check(
                  status().is(201),
                  regex("\"accepted\"\\s*:\\s*true").exists(),
                  jsonPath("$.csrf").optional().saveAs("csrf")
              ))
      );

  {
    setUp(journey.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}

