import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (BASE !== 'http://127.0.0.1:8000') {
  throw new Error('BASE_URL must target http://127.0.0.1:8000');
}

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    'checks{sampler:login}': ['rate==1'],
    'checks{sampler:cart}': ['rate==1'],
    'checks{sampler:order}': ['rate==1'],
  },
};

function bodyJson(res) {
  try {
    return res.json();
  } catch (_) {
    return {};
  }
}

function header(res, name) {
  const wanted = name.toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === wanted) return res.headers[key];
  }
  return undefined;
}

function localUrl(path) {
  if (typeof path !== 'string' || path.indexOf('\\') !== -1) return null;
  if (path.startsWith('/') && !path.startsWith('//')) return BASE + path;
  if (path.startsWith(BASE + '/')) return path;
  return null;
}

function capture(state, res, captureEtag) {
  if (res.status < 200 || res.status >= 400) return;
  const data = bodyJson(res);
  if (data && typeof data.csrf === 'string' && data.csrf) {
    state.csrf = data.csrf;
  }
  if (captureEtag) {
    const etag = header(res, 'etag');
    if (etag) state.etag = etag;
  }
}

function request(state, method, path, payload, name, extraHeaders, captureEtag) {
  const url = localUrl(path);
  if (!url) return null;

  const headers = Object.assign({}, extraHeaders || {});
  if (method !== 'GET') {
    headers['Content-Type'] = 'application/json';
    if (state.csrf) headers['X-CSRF-Token'] = state.csrf;
  }

  const res = http.request(method, url, payload === undefined ? null : JSON.stringify(payload), {
    headers,
    redirects: 0,
    timeout: '3s',
    tags: { name },
  });
  capture(state, res, captureEtag);
  return res;
}

function login(state) {
  const form = request(state, 'GET', '/v2/login-form', undefined, 'GET /v2/login-form');
  if (!form || form.status !== 200) return false;

  let token;
  try {
    token = parseHTML(form.body).find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    return false;
  }
  if (!token) return false;

  const res = request(
    state,
    'POST',
    '/v2/login',
    { username: `bench-${__VU}`, password: 'bench', csrf: token },
    'POST /v2/login'
  );
  if (!res) return false;

  check(res, {
    'login response contains csrf': (r) => /"csrf"\s*:/.test(r.body || ''),
  }, { sampler: 'login' });

  if (res.status === 302) {
    const location = header(res, 'location');
    const redirected = request(state, 'GET', location, undefined, 'GET login redirect');
    if (!redirected || redirected.status < 200 || redirected.status >= 300) return false;
  } else if (res.status < 200 || res.status >= 300) {
    return false;
  }
  return Boolean(state.csrf);
}

function recoverSession(state) {
  const renewed = request(
    state, 'POST', '/v2/session/renew', {}, 'POST /v2/session/renew'
  );

  if (!renewed || renewed.status < 200 || renewed.status >= 300) {
    state.csrf = null;
    if (!login(state)) return false;
  }

  if (state.cart) {
    const recovered = request(
      state,
      'POST',
      `/v2/carts/${encodeURIComponent(state.cart)}/recover`,
      {},
      'POST /v2/carts/{id}/recover',
      undefined,
      true
    );
    if (!recovered || recovered.status < 200 || recovered.status >= 300) return false;
  }
  return true;
}

function withRecovery(state, operation) {
  const first = operation();
  if (!first || first.status !== 401) return first;

  const error = bodyJson(first).error;
  if (error !== 'expired' && error !== 'session') return first;
  if (!recoverSession(state)) return first;
  return operation();
}

export default function () {
  const state = { csrf: null, cart: null, etag: null };
  if (!login(state)) return;

  const catalog = withRecovery(state, () =>
    request(state, 'GET', '/v2/catalog', undefined, 'GET /v2/catalog')
  );
  if (!catalog || catalog.status !== 200) return;

  const catalogData = bodyJson(catalog);
