    const firstVariant = candidate.variants && candidate.variants[0];
    if (candidate.id != null && firstVariant && firstVariant.id != null &&
        firstVariant.in_stock === true) {
      product = candidate.id;
      variant = firstVariant.id;
      break;
    }
  }
  if (product === undefined) return;

  const cart = withRecovery(state, () =>
    request(
      state,
      'POST',
      '/v2/carts',
      { product_id: product, variant_id: variant },
      'POST /v2/carts',
      undefined,
      true
    )
  );
