  if (cart.status !== 201 || typeof cartData.id !== 'string' ||
      !cartData.id.startsWith('cart-')) return;
  state.cart = cartData.id;

  const order = withRecovery(state, () => {
    const headers = { 'Idempotency-Key': state.cart };
