    return request(
      state,
      'POST',
      '/v2/orders',
      { cart_id: state.cart },
      'POST /v2/orders',
      headers
    );
  });
  if (!order) return;

  check(order, {
    'order response accepted': (r) =>
      r.status === 201 && bodyJson(r).accepted === true,
