import os
import re
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"]
base = urlsplit(BASE_URL)
if base.scheme != "http" or base.netloc != "127.0.0.1:8000":
    raise ValueError("BASE_URL must target http://127.0.0.1:8000")


class JourneyAbort(Exception):
    pass


class Inputs(HTMLParser):
    def __init__(self):
        super().__init__()
        self.values = {}

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "input":
            attrs = dict(attrs)
            name = attrs.get("name")
            if name is not None and name not in self.values:
                self.values[name] = attrs.get("value")


def local_location(location):
    if not location:
        raise ValueError("Missing Location")
    resolved = urlsplit(urljoin(BASE_URL.rstrip("/") + "/", location))
    if resolved.scheme != "http" or resolved.netloc != "127.0.0.1:8000":
        raise ValueError("Location points outside the target")
    return location


def json_object(response):
    try:
        value = response.json()
    except (ValueError, TypeError):
        return {}
    return value if isinstance(value, dict) else {}


class ShopUser(HttpUser):
    host = BASE_URL
    next_user = 0
    completed_users = 0
    completed_journeys = 0
    order_attempts = 0

    def on_start(self):
        ShopUser.next_user += 1
        self.username = "bench-{}".format(ShopUser.next_user)
        self.iterations = 0
        self.csrf = None
        self.cart = None
        self.etag = None

    def request(
        self, method, path, *, name=None, body=None, statuses=(200,),
        validator=None, authenticated=True, extra_headers=None, retry_auth=True
    ):
        for attempt in range(2 if retry_auth else 1):
            headers = dict(extra_headers or {})
            if authenticated and method != "GET" and self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            kwargs = {
                "name": name or path,
                "headers": headers,
                "allow_redirects": False,
                "catch_response": True,
                "timeout": (2, 3),
            }
            if body is not None:
                kwargs["json"] = body

            recover_reason = None
            failure = None
            result = None
            with self.client.request(method, path, **kwargs) as response:
                data = json_object(response)
                reason = data.get("error")
                if (
                    response.status_code == 401
                    and reason in ("expired", "session")
                    and retry_auth
                    and attempt == 0
                ):
                    response.success()
                    recover_reason = reason
                else:
                    try:
                        if response.status_code not in statuses:
                            raise ValueError(
                                "Unexpected HTTP status {}".format(response.status_code)
                            )
                        value = validator(response, data) if validator else data
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        result = (value, dict(response.headers))
                    except Exception as exc:
                        failure = str(exc) or type(exc).__name__
                        response.failure(failure)

            if recover_reason:
                self.recover_session(recover_reason)
                continue
            if failure:
                raise JourneyAbort(failure)
            return result

        raise JourneyAbort("Authentication retry exhausted")

    def login(self):
        def form_check(response, data):
            parser = Inputs()
            parser.feed(response.text)
            token = parser.values.get("csrf")
            if not token:
                raise ValueError("Login form has no csrf input")
            return token

        form_token, _ = self.request(
            "GET", "/v2/login-form", validator=form_check, authenticated=False
        )

        def login_check(response, data):
            if not re.search(r'"csrf"\s*:', response.text):
                raise ValueError("Login response lacks csrf")
            if response.status_code == 302:
                local_location(response.headers.get("Location"))
            return data

        _, headers = self.request(
            "POST",
            "/v2/login",
            body={"username": self.username, "password": "bench", "csrf": form_token},
            statuses=(200, 302),
            validator=login_check,
            authenticated=False,
            retry_auth=False,
        )
        location = headers.get("Location")
        if location:
            try:
                location = local_location(location)
            except ValueError as exc:
                raise JourneyAbort(str(exc))
            self.request(
                "GET", location, name="/v2/login/redirect",
                authenticated=False, retry_auth=False
            )
        if not self.csrf:
            raise JourneyAbort("Login did not provide a csrf token")

    def recover_session(self, reason):
        if reason == "expired":
            def renew_check(response, data):
                if not data.get("csrf"):
                    raise ValueError("Renewal did not provide csrf")
                return data

            self.request(
                "POST", "/v2/session/renew", body={},
                validator=renew_check, retry_auth=False
            )
        else:
            self.login()

        if self.cart:
            self.request(
                "POST",
                "/v2/carts/{}/recover".format(self.cart),
                name="/v2/carts/[id]/recover",
                body={},
                retry_auth=False,
            )

    def journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart = None
        self.etag = None
        self.login()

        def catalog_check(response, data):
            products = data.get("data", {}).get("products", [])
            for product in products:
                variants = product.get("variants") or []
                if (
                    product.get("id")
                    and variants
                    and variants[0].get("id")
                    and variants[0].get("in_stock") is True
                ):
                    return product["id"], variants[0]["id"]
            raise ValueError("No product with an in-stock first variant")

        (product, variant), _ = self.request(
            "GET", "/v2/catalog", validator=catalog_check
        )

        def cart_check(response, data):
            if not re.search(r'"id"\s*:\s*"cart-', response.text):
                raise ValueError("Cart response lacks a cart id")
            if not data.get("id") or not response.headers.get("ETag"):
                raise ValueError("Cart response lacks id or ETag")
            return data["id"]

        self.cart, headers = self.request(
            "POST",
            "/v2/carts",
            body={"product_id": product, "variant_id": variant},
            statuses=(201,),
            validator=cart_check,
        )
        self.etag = headers["ETag"]

        def order_check(response, data):
            if not re.search(r'"accepted"\s*:\s*true', response.text):
                raise ValueError("Order was not accepted")
            if data.get("accepted") is not True:
                raise ValueError("Order was not accepted")
            return data

        ShopUser.order_attempts += 1
        self.request(
            "POST",
            "/v2/orders",
            body={"cart_id": self.cart},
            statuses=(200, 201),
            validator=order_check,
            extra_headers={
                "If-Match": self.etag,
                "Idempotency-Key": self.cart,
            },
        )

    @task
    def run_iteration(self):
        try:
            self.journey()
        except JourneyAbort:
            pass
        finally:
            self.iterations += 1
            ShopUser.completed_journeys += 1

        if self.iterations >= 2:
            ShopUser.completed_users += 1
            raise StopUser()


class JourneyShape(LoadTestShape):
    def tick(self):
        if ShopUser.completed_users >= 2:
            orders = self.runner.environment.stats.get("/v2/orders", "POST")
            self.runner.environment.process_exit_code = (
                1
                if (
                    ShopUser.completed_journeys != 4
                    or ShopUser.order_attempts != 4
                    or orders.num_failures > 0
                )
                else 0
            )
            return None
        return (2, 2)
```

