import http from 'k6/http';
import { check } from 'k6';

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

let csrf = '';
let cart = '';
let grant = '';

function body(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return '';
}

function validValue(value) {
  return value !== undefined && value !== null && String(value) !== '';
}

function localPath(location) {
  if (typeof location !== 'string' || !location) return '';
  if (location.indexOf(base + '/') === 0) return location.slice(base.length);
  if (location[0] === '/' && location[1] !== '/') return location;
  return '';
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && csrf) headers['X-CSRF-Token'] = csrf;

  const response = http.request(
    method,
    base + path,
    data === null ? null : JSON.stringify(data),
    { headers, redirects: 0, timeout: '3s' }
  );
  const result = body(response);
  if (response.status >= 200 && response.status < 400 && validValue(result.csrf)) {
    csrf = result.csrf;
  }
  return response;
}

function login() {
  csrf = '';
  const formResponse = raw('/v2/login-form');
  if (!check(formResponse, { 'login form returned': r => r.status === 200 })) {
    return false;
  }

  const document = formResponse.html();
  let inputs = document.find('form[action="/v2/login"] input[name="csrf"]');
  if (inputs.size() === 0) inputs = document.find('input[name="csrf"]');
  const token = inputs.first().attr('value');
  if (!check(token, { 'login form token found': validValue })) return false;

  const username = `bench-${((__VU - 1) % 16) + 1}`;
  let response = raw('/v2/login', 'POST', {
    username,
    password: 'bench',
    csrf: token,
  });

  if (response.status === 302) {
    const location = localPath(header(response, 'Location'));
    if (!check(location, { 'login redirect is local': validValue })) return false;
    response = raw(location);
  }

  const result = body(response);
  if (validValue(result.grant_id)) grant = result.grant_id;
  return check(response, {
    'login succeeded with session token': r => r.status === 200 && validValue(csrf),
  });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let response = raw(path, method, data, extra);
  const error = body(response).error;

  if (response.status !== 401 || (error !== 'expired' && error !== 'session')) {
    return response;
  }

  const renewed = raw('/v2/session/renew', 'POST', {});
  const renewalOk = renewed.status === 200 && validValue(body(renewed).csrf);

  if (!renewalOk) {
    if (error !== 'session') {
      check(renewed, { 'expired session renewed': () => false });
      return response;
    }
    if (!login()) return response;
  }

  const retryHeaders = Object.assign({}, extra);
  if (validValue(cart)) {
    const recovered = raw(`/v2/carts/${encodeURIComponent(cart)}/recover`, 'POST', {});
    if (!check(recovered, { 'cart recovered': r => r.status >= 200 && r.status < 300 })) {
      return response;
    }
    const recoveredEtag = header(recovered, 'ETag');
    if (recoveredEtag && retryHeaders['If-Match']) {
      retryHeaders['If-Match'] = recoveredEtag;
    }
  }

  return raw(path, method, data, retryHeaders);
}

export default function () {
  csrf = '';
  cart = '';
  grant = '';

  if (!login()) return;

  const catalogResponse = request('/v2/catalog');
  const catalog = body(catalogResponse);
  const products = catalog.data && catalog.data.products;
  if (!check(catalogResponse, {
    'catalog returned products': r => r.status === 200 && Array.isArray(products),
  })) return;

  let product;
  let variant;
  for (const candidate of products) {
    if (!validValue(candidate.id) || !Array.isArray(candidate.variants)) continue;
    const available = candidate.variants.find(v => v.in_stock && validValue(v.id));
    if (available) {
      product = candidate;
      variant = available;
      break;
    }
  }
  if (!check(product, { 'in-stock variant found': () => !!product && !!variant })) return;

  const cartPayload = { product_id: product.id, variant_id: variant.id };
  if (validValue(grant)) cartPayload.grant_id = grant;

  const cartResponse = request('/v2/carts', 'POST', cartPayload);
  const cartBody = body(cartResponse);
  const etag = header(cartResponse, 'ETag');
  if (!check(cartResponse, {
    'cart created': r => r.status === 201 && validValue(cartBody.id) && validValue(etag),
  })) return;

  cart = cartBody.id;
  const orderResponse = request(
    '/v2/orders',
    'POST',
    { cart_id: cart },
    {
      'Idempotency-Key': String(cart),
      'If-Match': etag,
    }
  );
  check(orderResponse, {
    'order accepted': r => r.status === 201 && body(r).accepted === true,
  });
}

