import os
from html.parser import HTMLParser
from urllib.parse import quote, urlsplit

from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


USERS = 2
ITERATIONS = 2
_state_lock = Semaphore()
_started = 0
_finished = 0


def present(value):
    return value is not None and value != ""


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.token = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attributes = dict(attrs)
        if attributes.get("name") == "csrf" and present(attributes.get("value")):
            if self.token is None:
                self.token = attributes["value"]


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = lambda self: 0

    def on_start(self):
        global _started
        with _state_lock:
            _started += 1
            number = _started
        if number > USERS:
            raise StopUser()
        self.username = "bench-{}".format(number)
        self.csrf = None
        self.cart = None
        self.etag = None
        self.iteration = 0

    def local_location(self, location):
        if not isinstance(location, str) or not location or "{" in location or "}" in location:
            return False
        parsed = urlsplit(location)
        if parsed.scheme or parsed.netloc:
            base = urlsplit(self.host)
            return parsed.scheme == base.scheme and parsed.netloc == base.netloc
        return location.startswith("/") and not location.startswith("//")

    def raw(self, path, method="GET", data=None, headers=None, expected=(200,),
            validate=None, allow_recovery=False, name=None):
        request_headers = {}
        if self.csrf and method != "GET":
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(
            method, path, json=data, headers=request_headers, name=name,
            catch_response=True, allow_redirects=False, timeout=3
        ) as response:
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {}
            except ValueError:
                body = {}

            status = response.status_code
            transient = (
                allow_recovery and status == 401
                and body.get("error") in ("expired", "session")
            )
            error = None
            if status not in expected and not transient:
                error = "Unexpected HTTP status {}".format(status)
            elif not transient and validate is not None:
                try:
                    error = validate(response, body)
                except Exception as exc:
                    error = "Response validation failed: {}".format(exc)

            if error:
                response.failure(error)
                self.environment.process_exit_code = 99
            else:
                response.success()
                if status < 400 and body.get("csrf"):
                    self.csrf = body["csrf"]

            return status, response.headers.copy(), body, not bool(error)

    def login(self):
        self.csrf = None
        parser = LoginFormParser()

        def check_form(response, body):
            parser.feed(response.text)
            if not parser.token:
                return "Login form did not contain a CSRF token"
            return None

        _, _, _, ok = self.raw("/v2/login-form", validate=check_form)
        if not ok:
            return False

        def check_login(response, body):
            if response.status_code == 302:
                if not self.local_location(response.headers.get("Location")):
                    return "Login redirect has an invalid Location"
            elif not body.get("csrf"):
                return "Login response did not contain a CSRF token"
            return None

        status, headers, _, ok = self.raw(
            "/v2/login", "POST",
            {"username": self.username, "password": "bench", "csrf": parser.token},
            expected=(200, 302), validate=check_login
        )
        if not ok:
            return False

        if status == 302:
            def check_redirect(response, body):
                if not body.get("csrf") and not self.csrf:
                    return "Login redirect did not provide a CSRF token"
                return None

            _, _, _, ok = self.raw(headers["Location"], validate=check_redirect)
            if not ok:
                return False
        return bool(self.csrf)

    def recover(self, error):
        if error == "session":
            if not self.login():
                return False
        else:
            status, _, body, ok = self.raw(
                "/v2/session/renew", "POST", {}, expected=(200,),
                allow_recovery=True
            )
            if not ok:
                return False
            if status == 401:
                if body.get("error") != "session" or not self.login():
                    return False

        if self.cart is not None:
            path = "/v2/carts/{}/recover".format(quote(str(self.cart), safe=""))
            _, headers, _, ok = self.raw(
                path, "POST", {}, expected=(200, 201, 204)
            )
            if not ok:
                return False
            self.etag = headers.get("ETag", self.etag)
        return True

    def request(self, path, method="GET", data=None, headers=None,
                expected=(200,), validate=None):
        result = self.raw(
            path, method, data, headers, expected, validate,
            allow_recovery=True
        )
        status, _, body, ok = result
        if not ok or status != 401:
            return result

        if not self.recover(body.get("error")):
            self.environment.process_exit_code = 99
            return status, result[1], body, False

        retry_headers = dict(headers or {})
        if "If-Match" in retry_headers and self.etag:
            retry_headers["If-Match"] = self.etag
        return self.raw(
            path, method, data, retry_headers, expected, validate,
            allow_recovery=False
        )

    def flow(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart = None
        self.etag = None
        if not self.login():
            return

        selection = []

        def check_catalog(response, body):
            products = body.get("data", {}).get("products", [])
            if not isinstance(products, list):
                return "Catalog products are invalid"
            for product in products:
                if not isinstance(product, dict) or not present(product.get("id")):
                    continue
                for variant in product.get("variants", []):
                    if (isinstance(variant, dict) and variant.get("in_stock")
                            and present(variant.get("id"))):
                        selection.append((product["id"], variant["id"]))
                        return None
            return "Catalog contained no in-stock variant"

        _, _, _, ok = self.request("/v2/catalog", validate=check_catalog)
        if not ok:
            return

        def check_cart(response, body):
            if not present(body.get("id")):
                return "Cart response did not contain an ID"
            if not response.headers.get("ETag"):
                return "Cart response did not contain an ETag"
            return None

        product_id, variant_id = selection[0]
        _, headers, body, ok = self.request(
            "/v2/carts", "POST",
            {"product_id": product_id, "variant_id": variant_id},
            expected=(201,), validate=check_cart
        )
        if not ok:
            return
        self.cart = body["id"]
        self.etag = headers["ETag"]

        def check_order(response, body):
            if body.get("accepted") is not True or not present(body.get("id")):
                return "Order was not accepted"
            return None

        self.request(
            "/v2/orders", "POST", {"cart_id": self.cart},
            headers={"Idempotency-Key": str(self.cart), "If-Match": self.etag},
            expected=(201,), validate=check_order
        )

    @task
    def run_journey(self):
        global _finished
        self.flow()
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            with _state_lock:
                _finished += 1
            raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        if self.first_tick:
            self.first_tick = False
            return USERS, USERS
        with _state_lock:
            remaining = USERS - _finished
        if remaining <= 0:
            return None
        return remaining, USERS
```

