import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import java.io.IOException;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static Session captureCsrf(Session session, String bodyAttribute) {
        if (!session.contains(bodyAttribute)) {
            return session;
        }
        try {
            JsonNode body = JSON.readTree(session.getString(bodyAttribute));
            if (body != null && body.hasNonNull("csrf")
                && !body.path("csrf").asText().isEmpty()) {
                return session.set("csrf", body.path("csrf").asText());
            }
        } catch (IOException ignored) {
            // A redirect response may have no JSON body.
        }
        return session;
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode body = JSON.readTree(session.getString("catalogBody"));
            for (JsonNode product : body.path("data").path("products")) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()
                        && product.hasNonNull("id") && variant.hasNonNull("id")) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException ignored) {
            // Stop the journey if the catalog cannot be interpreted.
        }
        return session.markAsFailed();
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(session -> session.remove("cart")
                .remove("csrf")
                .remove("formCsrf")
                .remove("loginStatus")
                .remove("loginBody")
                .remove("location")
                .remove("redirectBody")
                .remove("catalogBody")
                .remove("product")
                .remove("variant")
                .remove("etag"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("username", "bench-" + ((session.userId() - 1) % 16 + 1))
                    .put("password", "bench")
                    .put("csrf", session.getString("formCsrf"))
                    .toString()))
                .check(status().in(200, 302),
                    status().saveAs("loginStatus"),
                    bodyString().optional().saveAs("loginBody"),
                    header("Location").optional().saveAs("location")))
            .exitHereIfFailed()
            .exec(session -> captureCsrf(session, "loginBody"))
            .exec(session -> session.getInt("loginStatus") == 302
                && (!session.contains("location") || session.getString("location").isEmpty())
                    ? session.markAsFailed() : session)
            .exitHereIfFailed()
            .exec(doIf(session -> session.getInt("loginStatus") == 302).then(
                exec(http("login redirect").get("#{location}")
                    .disableFollowRedirect()
                    .check(status().is(200),
                        bodyString().optional().saveAs("redirectBody")))
                    .exitHereIfFailed()
                    .exec(session -> captureCsrf(session, "redirectBody"))))
            .exitHereIfFailed()
            .exec(session -> session.contains("csrf")
                ? session : session.markAsFailed())
            .exitHereIfFailed()
            .exec(http("catalog").get("/v2/catalog")
                .check(status().is(200), bodyString().saveAs("catalogBody")))
            .exitHereIfFailed()
            .exec(ModelSimulation::selectProduct)
            .exitHereIfFailed()
            .exec(http("cart").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("product_id", session.getString("product"))
                    .put("variant_id", session.getString("variant"))
                    .toString()))
                .check(status().is(201),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed()
            .exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("cart_id", session.getString("cart"))
                    .toString()))
                .check(status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").exists(),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed();
    }

    public ModelSimulation() {
        setUp(scenario("flow")
            .exec(repeat(2).on(journey()))
            .injectOpen(atOnceUsers(2)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

