import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

function body(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return '';
}

function urlFor(path) {
  if (typeof path !== 'string' || !path) throw new Error('Missing request path');
  if (/^https?:\/\//i.test(path)) {
    if (path !== base && !path.startsWith(base + '/') && !path.startsWith(base + '?')) {
      throw new Error('Unexpected request origin');
    }
    return path;
  }
  return base + (path.startsWith('/') ? path : '/' + path);
}

function raw(state, path, method = 'GET', data = null, extraHeaders = {}) {
  const headers = Object.assign({}, extraHeaders);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && state.csrf) headers['X-CSRF-Token'] = state.csrf;

  const response = http.request(
    method,
    urlFor(path),
    data === null ? null : JSON.stringify(data),
    { headers, jar: state.jar, redirects: 0, timeout: '3s' }
  );

  const result = body(response);
  if (response.status >= 200 && response.status < 400 && result.csrf) {
    state.csrf = result.csrf;
  }
  return response;
}

function login(state) {
  state.jar = new http.CookieJar();
  state.csrf = '';

  let response = raw(state, '/v2/login-form');
  if (!check(response, { 'login form returned': r => r.status === 200 })) return false;

  let token = '';
  try {
    const html = response.html();
    token = html.find('form[action="/v2/login"] input[name="csrf"]').first().attr('value');
    if (!token) token = html.find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    token = '';
  }
  if (!check(token, { 'login form has csrf': t => !!t })) return false;

  response = raw(state, '/v2/login', 'POST', {
    username: `bench-${__VU}`,
    password: 'bench',
    csrf: token,
  });

  if (response.status === 302) {
    const location = header(response, 'Location');
    if (!check(location, { 'login redirect has location': l => !!l })) return false;
    response = raw(state, location);
  }

  return check(response, {
    'login succeeded': r => r.status === 200 && !!state.csrf,
  });
}

function request(state, path, method = 'GET', data = null, extraHeaders = {}) {
  let response = raw(state, path, method, data, extraHeaders);
  const error = body(response).error;

  if (response.status !== 401 || (error !== 'expired' && error !== 'session')) {
    return response;
  }

  let authenticated = false;
  if (error === 'expired') {
    const renewed = raw(state, '/v2/session/renew', 'POST', {});
    authenticated = renewed.status === 200;
  }
  if (!authenticated) authenticated = login(state);
  if (!authenticated) return response;

  if (state.cart !== null) {
    const recovered = raw(
      state,
      '/v2/carts/' + encodeURIComponent(String(state.cart)) + '/recover',
      'POST',
      {}
    );
    if (!check(recovered, {
      'cart recovered': r => r.status >= 200 && r.status < 300,
    })) return response;
  }

  return raw(state, path, method, data, extraHeaders);
}

export default function () {
  const state = { jar: null, csrf: '', cart: null };
  if (!login(state)) return;

  const catalog = request(state, '/v2/catalog');
  const catalogBody = body(catalog);
  const products = catalogBody.data && catalogBody.data.products;
  if (!check(catalog, {
    'catalog returned products': r => r.status === 200 && Array.isArray(products),
  })) return;

  let product = null;
  let variant = null;
  for (const candidate of products) {
    if (candidate.id === undefined || candidate.id === null || !Array.isArray(candidate.variants)) {
      continue;
    }
    const available = candidate.variants.find(
      v => v.in_stock && v.id !== undefined && v.id !== null
    );
    if (available) {
      product = candidate;
      variant = available;
      break;
    }
  }
  if (!check(product, { 'eligible product found': p => p !== null })) return;

  const created = request(state, '/v2/carts', 'POST', {
    product_id: product.id,
    variant_id: variant.id,
  });
  const createdBody = body(created);
  const etag = header(created, 'ETag');
  if (!check(created, {
    'fresh cart created': r =>
      r.status === 201 && createdBody.id !== undefined && createdBody.id !== null && !!etag,
  })) return;
  state.cart = createdBody.id;

  const order = request(state, '/v2/orders', 'POST', { cart_id: state.cart }, {
    'Idempotency-Key': `journey-${__VU}-${__ITER}-${state.cart}`,
    'If-Match': etag,
  });
  check(order, {
    'order accepted': r => {
      const result = body(r);
      return r.status === 201 && result.accepted === true &&
        result.id !== undefined && result.id !== null;
    },
  });
}

