import os
from html.parser import HTMLParser
from itertools import count
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


USER_NUMBERS = count(1)


class InputParser(HTMLParser):
    def __init__(self, name):
        super().__init__(convert_charrefs=True)
        self.name = name
        self.value = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input" or self.value is not None:
            return
        attributes = dict(attrs)
        if (
            attributes.get("name") == self.name
            and "disabled" not in attributes
            and attributes.get("value")
        ):
            self.value = attributes["value"]

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def input_value(html, name):
    parser = InputParser(name)
    parser.feed(html)
    return parser.value


def local_location(response):
    location = response.headers.get("Location")
    if not location:
        return None
    target = urljoin(response.url, location)
    parts = urlsplit(target)
    if parts.scheme != "http" or parts.netloc != "127.0.0.1:8000":
        return None
    return target


def choose_product(body):
    data = body.get("data")
    if not isinstance(data, dict):
        return None
    products = data.get("products")
    if not isinstance(products, list):
        return None
    for product in products:
        if not isinstance(product, dict) or product.get("id") is None:
            continue
        variants = product.get("variants")
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if (
                isinstance(variant, dict)
                and variant.get("id") is not None
                and variant.get("in_stock") is True
            ):
                return product["id"], variant["id"]
    return None


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = lambda self: 0

    def on_start(self):
        number = next(USER_NUMBERS)
        self.username = "bench-{}".format((number - 1) % 16 + 1)
        self.csrf = ""
        self.cart = None
        self.etag = ""
        self.iteration = 0

    def once(
        self,
        path,
        method="GET",
        data=None,
        headers=None,
        expected=(200,),
        validate=None,
        allow_auth_error=False,
    ):
        request_headers = dict(headers or {})
        if self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        failed = False
        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {}
            except ValueError:
                body = {}

            error = body.get("error")
            auth_error = (
                allow_auth_error
                and response.status_code == 401
                and error in ("expired", "session")
            )
            reason = None
            if auth_error:
                response.success()
            elif response.status_code not in expected:
                reason = "Unexpected HTTP status {}".format(response.status_code)
            elif validate:
                try:
                    reason = validate(response, body)
                except (KeyError, TypeError, ValueError, AttributeError):
                    reason = "Invalid response"

            if reason:
                response.failure(reason)
                failed = True
            elif not auth_error:
                response.success()
                if body.get("csrf"):
                    self.csrf = body["csrf"]

        if failed:
            raise StopUser()
        return response, body

    def login(self):
        self.client.cookies.clear()
        self.csrf = ""

        def validate_form(response, body):
            if not input_value(response.text, "csrf"):
                return "Login form has no CSRF token"
            return None

        form, _ = self.once("/v2/login-form", validate=validate_form)
        token = input_value(form.text, "csrf")

        def validate_login(response, body):
            if response.status_code == 302:
                if not local_location(response):
                    return "Invalid login redirect"
            elif not body.get("csrf") or "user" not in body:
                return "Invalid login response"
            return None

        response, _ = self.once(
            "/v2/login",
            "POST",
            {"username": self.username, "password": "bench", "csrf": token},
            expected=(200, 302),
            validate=validate_login,
        )
        if response.status_code == 302:
            location = local_location(response)

            def validate_landing(landing, body):
                if not (body.get("csrf") or self.csrf):
                    return "Login redirect did not provide a CSRF token"
                return None

            self.once(location, validate=validate_landing)

    def recover(self, error):
        if error == "expired":
            def validate_renew(response, body):
                if not body.get("csrf"):
                    return "Renewal did not provide a CSRF token"
                return None

            self.once(
                "/v2/session/renew",
                "POST",
                {},
                validate=validate_renew,
            )
        else:
            self.login()

        if self.cart is not None:
            response, _ = self.once(
                "/v2/carts/{}/recover".format(quote(str(self.cart), safe="")),
                "POST",
                {},
            )
            self.etag = response.headers.get("ETag", self.etag)

    def request(self, path, method="GET", data=None, headers=None,
                expected=(200,), validate=None):
        request_headers = dict(headers or {})
        for attempt in range(2):
            response, body = self.once(
                path,
                method,
                data,
                request_headers,
                expected=expected,
                validate=validate,
                allow_auth_error=(attempt == 0),
            )
            if (
                response.status_code == 401
                and body.get("error") in ("expired", "session")
            ):
                self.recover(body["error"])
                if "If-Match" in request_headers:
                    request_headers["If-Match"] = self.etag
                continue
            return response, body

        raise StopUser()

    def flow(self):
        # A completed cart and its session must never cross a journey boundary.
        self.cart = None
        self.etag = ""
        self.csrf = ""
        self.login()

        def validate_catalog(response, body):
            if choose_product(body) is None:
                return "Catalog has no available product and variant"
            return None

        _, catalog = self.request("/v2/catalog", validate=validate_catalog)
        product_id, variant_id = choose_product(catalog)

        def validate_cart(response, body):
            if body.get("id") is None or not response.headers.get("ETag"):
                return "Cart response is missing its ID or ETag"
            return None

        response, cart = self.request(
            "/v2/carts",
            "POST",
            {"product_id": product_id, "variant_id": variant_id},
            expected=(201,),
            validate=validate_cart,
        )
        self.cart = cart["id"]
        self.etag = response.headers["ETag"]

        def validate_order(response, body):
            if body.get("accepted") is not True or body.get("id") is None:
                return "Order was not accepted"
            return None

        self.request(
            "/v2/orders",
            "POST",
            {"cart_id": self.cart},
            headers={
                "Idempotency-Key": "order-{}".format(self.cart),
                "If-Match": self.etag,
            },
            expected=(201,),
            validate=validate_order,
        )

    @task
    def run_journey(self):
        self.flow()
        self.iteration += 1
        if self.iteration >= 2:
            raise StopUser()


class TestShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        if not self.started:
            self.started = True
            return 2, 2
        if self.runner.user_count == 0:
            return None
        return 2, 2
```

