import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = { users: 2, iterations: 2, mode: 'denial' };
const rows = Array.from({ length: 16 }, (_, i) => ({
  username: `bench-${i + 1}`,
  password: 'bench',
  quantity: i + 2,
}));
const failure = new Rate('business_failure');
const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try {
    return r.json() || {};
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  const wanted = name.toLowerCase();
  for (const key in r.headers) {
    if (key.toLowerCase() === wanted) return r.headers[key];
  }
  return '';
}

function target(path) {
  if (path.indexOf(base + '/') === 0) return path;
  if (path.charAt(0) === '/' && path.charAt(1) !== '/') return base + path;
  if (path && !/^[a-z][a-z0-9+.-]*:/i.test(path) && path.indexOf('//') !== 0) {
    return base + '/' + path;
  }
  throw new Error('Invalid or off-origin request target');
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const r = http.request(method, target(path), data === null ? null : JSON.stringify(data), {
    headers: Object.assign(
      { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      extra
    ),
    redirects: 0,
    timeout: '3s',
  });
  const b = body(r);
  if (r.status >= 200 && r.status < 400 && b.csrf) csrf = b.csrf;

  if (path === '/v2/work') {
    const expectedExpiry = r.status === 401 && b.error === 'expired';
    const scheduledThrottle = r.status === 429 && Number(header(r, 'Retry-After')) === 1;
    const success = r.status === 200 && b.ok === true;
    failure.add(!(success || expectedExpiry || scheduledThrottle));
  }
  return r;
}

function loginToken(r) {
  const doc = r.html();
  let token = '';
  let fallback = '';
  doc.find('form').each((_, form) => {
    const input = form.find('input[name="csrf"]:not([disabled])').first();
    const value = input.attr('value');
    if (!value) return;
    if (!fallback) fallback = value;
    const action = form.attr('action') || '';
    if (action.split('?')[0].endsWith('/v2/login') ||
        form.find('input[name="password"]').length > 0) {
      token = value;
    }
  });
  if (token) return token;
  if (fallback) return fallback;
  return doc.find('input[name="csrf"]:not([disabled])').first().attr('value') || '';
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form');
  const token = r.status === 200 ? loginToken(r) : '';
  if (!check(token, { 'login form contains csrf': (v) => !!v })) return false;

  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token,
  });
  if (r.status === 302) {
    const location = header(r, 'Location');
    if (!check(location, { 'login redirect has location': (v) => !!v })) return false;
    r = raw(location);
    if (body(r).grant_id) grant = body(r).grant_id;
  }
  return check(r, { 'login succeeded': (v) => v.status === 200 && !!csrf });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  const error = body(r).error;
  if (r.status !== 401 || (error !== 'expired' && error !== 'session')) return r;

  check(r, {
    'expected session expiry or revocation': (v) =>
      v.status === 401 && ['expired', 'session'].indexOf(body(v).error) !== -1,
  });

  const renewed = raw('/v2/session/renew', 'POST', {});
  let refreshed = renewed.status >= 200 && renewed.status < 300 && !!body(renewed).csrf;
  if (!refreshed) refreshed = login();
  if (!check(refreshed, { 'session refreshed': (v) => v === true })) return r;

  const retryHeaders = Object.assign({}, extra);
  if (cart) {
    const recovered = raw(`/v2/carts/${cart}/recover`, 'POST', {});
    if (!check(recovered, {
      'cart recovered': (v) => v.status >= 200 && v.status < 300,
    })) return r;
    const recoveredEtag = header(recovered, 'ETag');
    if (recoveredEtag && retryHeaders['If-Match']) {
      retryHeaders['If-Match'] = recoveredEtag;
    }
  }
  return raw(path, method, data, retryHeaders);
}

function work(override) {
  if (cfg.workload || !csrf) {
    if (!login()) return;
  }
  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    const delay = Number(header(r, 'Retry-After'));
    if (delay !== 1) break;
    sleep(delay);
    r = request(path, 'POST', {});
  }
  check(r, {
    'operation succeeded': (v) => v.status === 200 && body(v).ok === true,
  });
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';
  if (!login()) return;

  if (cfg.mode === 'challenge') {
    let r = request('/v2/challenge-form');
    if (!check(r, { 'challenge form loaded': (v) => v.status === 200 })) return;
    const form = r.html().find('form[action^="/v2/challenges/"]').first();
    const action = form.attr('action');
    const challenge = form.find('input[name="challenge"]').first().attr('value');
    if (!check(action && challenge, { 'challenge fields present': (v) => !!v })) return;
    r = request(action, 'POST', { challenge });
    const location = header(r, 'Location');
    if (!check(r, { 'challenge accepted': (v) => v.status === 302 && !!location })) return;
    r = request(location);
    grant = body(r).grant_id;
    if (!check(r, { 'challenge grant received': (v) => v.status === 200 && !!grant })) return;
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product;
  for (let n = 0; n < 3 && page; n++) {
    const r = request(page);
    if (!check(r, { 'catalog loaded': (v) => v.status === 200 })) return;
    const b = body(r);
    const products = b.data && Array.isArray(b.data.products) ? b.data.products : [];
    product = products.find((p) =>
      Array.isArray(p.variants) && p.variants.some((v) => v.in_stock)
    );
    if (product) break;
    page = b.next;
  }
  if (!check(product, { 'eligible product': (v) => !!v })) return;

  const variant = product.variants.find((v) => v.in_stock);
  const payload = { product_id: product.id, variant_id: variant.id };
  if (grant) payload.grant_id = grant;
  let r = request('/v2/carts', 'POST', payload);
  const cartBody = body(r);
  let etag = header(r, 'ETag');
  if (!check(r, {
    'cart created': (v) => v.status === 201 && !!cartBody.id && !!etag,
  })) return;
  cart = cartBody.id;

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data'
      ? rows[(__VU - 1) % rows.length].quantity
      : (cfg.quantity || 2);
    const update = { quantity };
    r = request(`/v2/carts/${cart}`, 'PATCH', update, { 'If-Match': etag });
    if (r.status === 412) {
      const current = request(`/v2/carts/${cart}`);
      etag = header(current, 'ETag');
      if (!check(current, {
        'cart reread': (v) => v.status === 200 && !!etag,
      })) return;
      r = request(`/v2/carts/${cart}`, 'PATCH', update, { 'If-Match': etag });
    }
    if (!check(r, { 'cart updated': (v) => v.status === 200 })) return;
    etag = header(r, 'ETag') || etag;
  }

  let reservation;
  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', { cart_id: cart });
    const statusUrl = body(r).status_url;
    if (!check(r, {
      'reservation requested': (v) => v.status === 202 && !!statusUrl,
    })) return;
    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(statusUrl);
      if (!check(r, { 'reservation status loaded': (v) => v.status === 200 })) return;
      const b = body(r);
      if (b.status === 'ready') {
        reservation = b.reservation_id;
        break;
      }
      if (b.status !== 'pending') break;
    }
    if (!check(reservation, { 'reservation ready': (v) => !!v })) return;
  }

  const order = { cart_id: cart };
  if (reservation) order.reservation_id = reservation;
  r = request('/v2/orders', 'POST', order, {
    'Idempotency-Key': String(cart),
    'If-Match': etag,
  });
  check(r, {
    'order accepted': (v) =>
      v.status === 201 && body(v).accepted === true && !!body(v).id,
  });

  if (cfg.mode === 'threshold') raw('/v2/health');
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work();
  } else if (cfg.mode === 'errors') {
    if (login()) {
      for (let n = 0; n < 4; n++) work();
    }
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}

import os
from html.parser import HTMLParser
from urllib.parse import quote, urlsplit

from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


USERS = 2
ITERATIONS = 2
_state_lock = Semaphore()
_started = 0
_finished = 0
_all_finished = Event()


class FlowFailed(Exception):
    pass


class InputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "input":
            attributes = {key.lower(): value for key, value in attrs}
            self.inputs.append(attributes)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def safe_location(location):
    if not isinstance(location, str) or not location:
        return False
    parts = urlsplit(location)
    if parts.scheme or parts.netloc:
        return parts.scheme == "http" and parts.netloc == "127.0.0.1:8000"
    return location.startswith("/") and not location.startswith("//")


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = lambda self: 0

    def on_start(self):
        global _started
        with _state_lock:
            _started += 1
            number = _started
        self.username = "bench-" + str((number - 1) % 16 + 1)
        self.iteration = 0
        self.csrf = ""
        self.cart = ""
        self.etag = ""

    def once(
        self,
        path,
        method="GET",
        data=None,
        headers=None,
        expected=(200,),
        validate=None,
        allow_expiry=False,
        allow_revoked_renewal=False,
    ):
        request_headers = dict(headers or {})
        if self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
            except (ValueError, TypeError):
                body = {}
            if not isinstance(body, dict):
                body = {}

            status = response.status_code
            error = body.get("error")
            result = {
                "status": status,
                "body": body,
                "headers": dict(response.headers),
                "text": response.text,
            }

            if status == 401 and error in ("expired", "session"):
                if allow_expiry or (allow_revoked_renewal and error == "session"):
                    response.success()
                    return result

            failure = None
            if status not in expected:
                failure = "Unexpected HTTP status: {}".format(status)
            elif validate is not None:
                try:
                    failure = validate(response, body)
                except Exception as exc:
                    failure = "Response validation error: {}".format(exc)

            if failure:
                response.failure(failure)
                raise FlowFailed(failure)

            if body.get("csrf"):
                self.csrf = body["csrf"]
            response.success()
            return result

    def login(self):
        self.csrf = ""
        token = {}

        def validate_form(response, body):
            parser = InputParser()
            parser.feed(response.text)
            for item in parser.inputs:
                if item.get("name") == "csrf" and item.get("value"):
                    token["value"] = item["value"]
                    return None
            return "Login form has no CSRF token"

        self.once("/v2/login-form", validate=validate_form)

        def validate_login(response, body):
            if response.status_code == 302:
                if not safe_location(response.headers.get("Location")):
                    return "Login redirect has no safe Location"
            elif not body.get("csrf"):
                return "Login response has no CSRF token"
            return None

        result = self.once(
            "/v2/login",
            "POST",
            {"username": self.username, "password": "bench", "csrf": token["value"]},
            expected=(200, 302),
            validate=validate_login,
        )
        if result["status"] == 302:
            location = result["headers"]["Location"]

            def validate_redirect(response, body):
                if not body.get("csrf") and not self.csrf:
                    return "Login redirect has no CSRF token"
                return None

            self.once(location, validate=validate_redirect)

    def recover(self, reason):
        def validate_renewal(response, body):
            if not body.get("csrf"):
                return "Renewal response has no CSRF token"
            return None

        renewed = self.once(
            "/v2/session/renew",
            "POST",
            {},
            expected=(200,),
            validate=validate_renewal,
            allow_revoked_renewal=(reason == "session"),
        )
        if renewed["status"] == 401:
            self.login()

        if self.cart:
            result = self.once(
                "/v2/carts/" + quote(str(self.cart), safe="") + "/recover",
                "POST",
                {},
                expected=(200, 201, 204),
            )
            self.etag = result["headers"].get("ETag", self.etag)

    def request(self, path, method="GET", data=None, headers=None,
                expected=(200,), validate=None):
        result = self.once(
            path, method, data, headers, expected, validate, allow_expiry=True
        )
        if result["status"] != 401:
            return result

        self.recover(result["body"]["error"])
        retry_headers = dict(headers or {})
        if "If-Match" in retry_headers:
            retry_headers["If-Match"] = self.etag
        return self.once(
            path, method, data, retry_headers, expected, validate
        )

    def flow(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.login()

        selected = {}

        def validate_catalog(response, body):
            data = body.get("data")
            products = data.get("products") if isinstance(data, dict) else None
            if not isinstance(products, list):
                return "Catalog has no product list"
            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                for variant in product.get("variants", []):
                    if (isinstance(variant, dict) and variant.get("in_stock")
                            and variant.get("id") is not None):
                        selected["product_id"] = product["id"]
                        selected["variant_id"] = variant["id"]
                        return None
            return "Catalog has no in-stock variant"

        self.request("/v2/catalog", validate=validate_catalog)

        def validate_cart(response, body):
            if body.get("id") is None:
                return "Cart response has no ID"
            if not response.headers.get("ETag"):
                return "Cart response has no ETag"
            return None

        result = self.request(
            "/v2/carts",
            "POST",
            selected,
            expected=(201,),
            validate=validate_cart,
        )
        self.cart = result["body"]["id"]
        self.etag = result["headers"]["ETag"]

        def validate_order(response, body):
            if body.get("accepted") is not True or body.get("id") is None:
                return "Order was not accepted"
            return None

        self.request(
            "/v2/orders",
            "POST",
            {"cart_id": self.cart},
            {
                "Idempotency-Key": "order-" + str(self.cart),
                "If-Match": self.etag,
            },
            expected=(201,),
            validate=validate_order,
        )

    @task
    def run_journey(self):
        global _finished
        try:
            self.flow()
        except FlowFailed:
            pass

        self.iteration += 1
        if self.iteration >= ITERATIONS:
            with _state_lock:
                _finished += 1
                if _finished >= USERS:
                    _all_finished.set()
            _all_finished.wait()
            raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        if _all_finished.is_set() or self.get_run_time() >= 60:
            return None
        return USERS, USERS

