import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String username(Session session) {
        return "bench-" + (((session.userId() - 1) % 16) + 1);
    }

    private static Session captureLogin(Session session) {
        if (session.getInt("loginStatus") == 302) {
            return session.contains("location") ? session : session.markAsFailed();
        }
        try {
            JsonNode body = JSON.readTree(session.getString("loginBody"));
            JsonNode csrf = body.path("csrf");
            if (!csrf.isTextual() || csrf.asText().isEmpty()) {
                return session.markAsFailed();
            }
            return session.set("csrf", csrf.asText());
        } catch (Exception error) {
            return session.markAsFailed();
        }
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                JsonNode productId = product.path("id");
                if (productId.isMissingNode() || productId.isNull()) {
                    continue;
                }
                for (JsonNode variant : product.path("variants")) {
                    JsonNode variantId = variant.path("id");
                    if (variant.path("in_stock").asBoolean()
                        && !variantId.isMissingNode() && !variantId.isNull()) {
                        return session.set("product", productId.asText())
                            .set("variant", variantId.asText());
                    }
                }
            }
        } catch (Exception error) {
            return session.markAsFailed();
        }
        return session.markAsFailed();
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(session -> session
                .remove("csrf")
                .remove("formCsrf")
                .remove("loginBody")
                .remove("location")
                .remove("product")
                .remove("variant")
                .remove("cart")
                .remove("etag"))
            .exec(http("login form")
                .get("/v2/login-form")
                .check(status().is(200),
                    css("input[name=csrf]", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("login")
                .post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("username", username(session))
                    .put("password", "bench")
                    .put("csrf", session.getString("formCsrf"))
                    .toString()))
                .check(status().in(200, 302),
                    status().saveAs("loginStatus"),
                    bodyString().optional().saveAs("loginBody"),
                    header("Location").optional().saveAs("location")))
            .exitHereIfFailed()
            .exec(ModelSimulation::captureLogin)
            .exitHereIfFailed()
            .exec(doIf(session -> session.getInt("loginStatus") == 302).then(
                exec(http("login redirect")
                    .get("#{location}")
                    .disableFollowRedirect()
                    .check(status().is(200),
                        jsonPath("$.csrf").saveAs("csrf")))))
            .exitHereIfFailed()
            .exec(http("catalog")
                .get("/v2/catalog")
                .check(status().is(200), bodyString().saveAs("catalogBody")))
            .exitHereIfFailed()
            .exec(ModelSimulation::selectProduct)
            .exitHereIfFailed()
            .exec(http("cart")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("product_id", session.getString("product"))
                    .put("variant_id", session.getString("variant"))
                    .toString()))
                .check(status().is(201),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed()
            .exec(http("commit")
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("cart_id", session.getString("cart"))
                    .toString()))
                .check(status().in(200, 201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").exists(),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed();
    }

    public ModelSimulation() {
        setUp(
            scenario("decline")
                .exec(repeat(2).on(journey()))
                .injectOpen(atOnceUsers(2))
        ).protocols(HTTP)
         .assertions(global().failedRequests().count().is(0L));
    }
}

