import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
let csrf = '';
let cart = '';
let grant = '';

function json(r) {
  try {
    return r && r.json() || {};
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  if (!r || !r.headers) return '';
  const key = Object.keys(r.headers).find(k => k.toLowerCase() === name.toLowerCase());
  return key ? r.headers[key] : '';
}

function url(path) {
  if (typeof path !== 'string') return '';
  if (path.startsWith('/') && !path.startsWith('//')) return base + path;
  if (path.startsWith(base + '/')) return path;
  return '';
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const target = url(path);
  if (!target) return null;
  const headers = Object.assign({ 'Content-Type': 'application/json' }, extra);
  if (method !== 'GET' && csrf) headers['X-CSRF-Token'] = csrf;
  const r = http.request(method, target, data === null ? null : JSON.stringify(data), {
    headers,
    redirects: 0,
    timeout: '3s',
  });
  const b = json(r);
  if (b.csrf) csrf = b.csrf;
  return r;
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form');
  let token = '';
  try {
    token = r.html().find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    token = '';
  }
  if (!check(r, { 'login form and csrf': x => x && x.status === 200 && !!token })) {
    return false;
  }

  r = raw('/v2/login', 'POST', {
    username: `bench-${__VU}`,
    password: 'bench',
    csrf: token,
  });

  if (r && r.status === 302) {
    const location = header(r, 'Location');
    if (!check(r, { 'login redirect location': () => !!url(location) })) return false;
    r = raw(location);
    grant = json(r).grant_id || '';
  }

  return check(r, {
    'login successful': x => x && x.status === 200 && !!csrf,
  });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  const error = json(r).error;
  if (!r || r.status !== 401 || (error !== 'expired' && error !== 'session')) {
    return r;
  }

  const renewed = raw('/v2/session/renew', 'POST', {});
  if (!renewed || renewed.status !== 200) {
    if (error !== 'session' || !login()) return r;
  }

  let retryHeaders = extra;
  if (cart) {
    const cartPath = '/v2/carts/' + encodeURIComponent(String(cart));
    const recovered = raw(cartPath + '/recover', 'POST', {});
    if (!check(recovered, {
      'cart recovered': x => x && x.status >= 200 && x.status < 300,
    })) return r;

    if (extra['If-Match']) {
      const current = raw(cartPath);
      const etag = header(current, 'ETag');
      if (!check(current, {
        'recovered cart version': x => x && x.status === 200 && !!etag,
      })) return r;
      retryHeaders = Object.assign({}, extra, { 'If-Match': etag });
    }
  }

  return raw(path, method, data, retryHeaders);
}

export default function () {
  csrf = '';
  cart = '';
  grant = '';

  if (!login()) return;

  let page = '/v2/catalog';
  let product;
  let variant;
  for (let n = 0; n < 3 && page; n++) {
    const r = request(page);
    const b = json(r);
    if (!check(r, {
      'catalog response': x =>
        x && x.status === 200 && b.data && Array.isArray(b.data.products),
    })) return;

    for (const candidate of b.data.products) {
      if (!Array.isArray(candidate.variants)) continue;
      const available = candidate.variants.find(v => v.in_stock === true);
      if (available) {
        product = candidate;
        variant = available;
        break;
      }
    }
    if (product) break;
    page = b.next;
  }

  if (!check(null, {
    'eligible product': () => !!(product && product.id && variant && variant.id),
  })) return;

  const cartPayload = { product_id: product.id, variant_id: variant.id };
  if (grant) cartPayload.grant_id = grant;
  const created = request('/v2/carts', 'POST', cartPayload);
  const cartBody = json(created);
  const etag = header(created, 'ETag');
  if (!check(created, {
    'cart created': x => x && x.status === 201 && !!cartBody.id && !!etag,
  })) return;
  cart = cartBody.id;

  const order = request('/v2/orders', 'POST', { cart_id: cart }, {
    'Idempotency-Key': 'cart-' + String(cart),
    'If-Match': etag,
  });
  const orderBody = json(order);
  check(order, {
    'order accepted': x =>
      x && x.status === 201 && orderBody.accepted === true && !!orderBody.id,
  });
}

