import os
from html.parser import HTMLParser
from itertools import count
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


USERS = 2
ITERATIONS = 2
USER_NUMBERS = count(1)


class InputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "input":
            self.inputs.append(dict(attrs))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def csrf_from_form(html):
    parser = InputParser()
    parser.feed(html)
    for attrs in parser.inputs:
        if attrs.get("name") == "csrf" and attrs.get("value"):
            return attrs["value"]
    return None


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = constant(0)

    def on_start(self):
        number = next(USER_NUMBERS)
        self.username = "bench-" + str((number - 1) % 16 + 1)
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.iteration = 0

    def send(self, path, method="GET", data=None, headers=None,
             expected=(200,), check=None, allow_recovery=False,
             allow_renew_failure=False, order=False):
        request_headers = dict(headers or {})
        if method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            status = response.status_code
            error = body.get("error")
            outcome = "ok"

            if status == 401 and error in ("expired", "session") and allow_recovery:
                response.success()
                outcome = "recover"
            elif (status == 401 and error in ("expired", "session")
                  and allow_renew_failure):
                response.success()
                outcome = "renew_failed"
            else:
                message = None
                if order and body.get("accepted") is False:
                    message = "Order declined: accepted is false"
                elif status not in expected:
                    message = "Unexpected HTTP status {} (error={!r})".format(
                        status, error
                    )
                elif check is not None:
                    message = check(response, body)

                if message:
                    response.failure(message)
                    outcome = "failed"
                else:
                    response.success()

            if body.get("csrf"):
                self.csrf = body["csrf"]

            return {
                "status": status,
                "body": body,
                "headers": response.headers,
                "text": response.text,
                "outcome": outcome,
            }

    def login(self):
        self.client.cookies.clear()
        self.csrf = ""

        def check_form(response, body):
            if not csrf_from_form(response.text):
                return "Login form did not contain a CSRF input"
            return None

        form = self.send("/v2/login-form", check=check_form)
        if form["outcome"] != "ok":
            return False

        token = csrf_from_form(form["text"])

        def check_login(response, body):
            if response.status_code == 302:
                if not response.headers.get("Location"):
                    return "Login redirect did not contain a Location"
            elif not body.get("csrf") or not body.get("user"):
                return "Login response did not contain csrf and user"
            return None

        result = self.send(
            "/v2/login",
            "POST",
            {"username": self.username, "password": "bench", "csrf": token},
            expected=(200, 302),
            check=check_login,
        )
        if result["outcome"] != "ok":
            return False

        if result["status"] == 302:
            def check_redirect(response, body):
                if not body.get("csrf") and not self.csrf:
                    return "Login redirect response did not contain csrf"
                return None

            result = self.send(
                result["headers"]["Location"],
                check=check_redirect,
            )
            if result["outcome"] != "ok":
                return False

        return bool(self.csrf)

    def recover(self, error):
        def check_renew(response, body):
            if not body.get("csrf"):
                return "Session renewal did not contain csrf"
            return None

        renewed = self.send(
            "/v2/session/renew",
            "POST",
            {},
            check=check_renew,
            allow_renew_failure=True,
        )
        if renewed["outcome"] == "failed":
            return False

        if error == "session" or renewed["outcome"] == "renew_failed":
            if not self.login():
                return False

        if self.cart:
            recovered = self.send(
                "/v2/carts/" + self.cart + "/recover",
                "POST",
                {},
            )
            if recovered["outcome"] != "ok":
                return False
            self.etag = recovered["headers"].get("ETag", self.etag)

        return True

    def request(self, path, method="GET", data=None, headers=None,
                expected=(200,), check=None, order=False):
        result = self.send(
            path, method, data, headers, expected, check,
            allow_recovery=True, order=order,
        )
        if result["outcome"] != "recover":
            return result

        if not self.recover(result["body"].get("error")):
            return result

        retry_headers = dict(headers or {})
        if "If-Match" in retry_headers and self.etag:
            retry_headers["If-Match"] = self.etag

        return self.send(
            path, method, data, retry_headers, expected, check,
            allow_recovery=False, order=order,
        )

    def journey(self):
        self.cart = ""
        self.etag = ""
        if not self.login():
            return

        def check_catalog(response, body):
            data = body.get("data")
            if not isinstance(data, dict) or not isinstance(data.get("products"), list):
                return "Catalog did not contain a product list"
            for product in data["products"]:
                if not isinstance(product, dict) or not product.get("id"):
                    continue
                variants = product.get("variants")
                if isinstance(variants, list) and any(
                    isinstance(v, dict) and v.get("id") and v.get("in_stock")
                    for v in variants
                ):
                    return None
            return "Catalog contained no in-stock variant"

        catalog = self.request("/v2/catalog", check=check_catalog)
        if catalog["outcome"] != "ok":
            return

        product = None
        variant = None
        for item in catalog["body"]["data"]["products"]:
            if not isinstance(item, dict) or not item.get("id"):
                continue
            variants = item.get("variants")
            if not isinstance(variants, list):
                continue
            for candidate in variants:
                if (isinstance(candidate, dict) and candidate.get("id")
                        and candidate.get("in_stock")):
                    product, variant = item, candidate
                    break
            if product is not None:
                break

        def check_cart(response, body):
            if not body.get("id"):
                return "Cart creation did not contain an id"
            if not response.headers.get("ETag"):
                return "Cart creation did not contain an ETag"
            return None

        cart = self.request(
            "/v2/carts",
            "POST",
            {"product_id": product["id"], "variant_id": variant["id"]},
            expected=(201,),
            check=check_cart,
        )
        if cart["outcome"] != "ok":
            return

        self.cart = str(cart["body"]["id"])
        self.etag = cart["headers"]["ETag"]
        order_headers = {
            "Idempotency-Key": str(uuid4()),
            "If-Match": self.etag,
        }

        def check_order(response, body):
            if body.get("accepted") is not True:
                return "Order was not accepted"
            if not body.get("id"):
                return "Accepted order did not contain an id"
            return None

        self.request(
            "/v2/orders",
            "POST",
            {"cart_id": self.cart},
            headers=order_headers,
            expected=(201,),
            check=check_order,
            order=True,
        )

    @task
    def run_journey(self):
        self.journey()
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        if self.first_tick:
            self.first_tick = False
            return USERS, USERS
        if self.runner.user_count == 0:
            return None
        return USERS, USERS
```

