```java
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.io.IOException;
import java.io.StringReader;
import javax.swing.text.MutableAttributeSet;
import javax.swing.text.html.HTML;
import javax.swing.text.html.HTMLEditorKit;
import javax.swing.text.html.parser.ParserDelegator;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String formCsrf(String html) {
        final String[] token = {null};

        HTMLEditorKit.ParserCallback callback = new HTMLEditorKit.ParserCallback() {
            private void inspect(HTML.Tag tag, MutableAttributeSet attributes) {
                if (tag == HTML.Tag.INPUT && token[0] == null) {
                    Object name = attributes.getAttribute(HTML.Attribute.NAME);
                    Object value = attributes.getAttribute(HTML.Attribute.VALUE);
                    if ("csrf".equals(name) && value != null) {
                        token[0] = value.toString();
                    }
                }
            }

            @Override
            public void handleSimpleTag(HTML.Tag tag, MutableAttributeSet attributes, int position) {
                inspect(tag, attributes);
            }

            @Override
            public void handleStartTag(HTML.Tag tag, MutableAttributeSet attributes, int position) {
                inspect(tag, attributes);
            }
        };

        try {
            new ParserDelegator().parse(new StringReader(html), callback, true);
        } catch (IOException error) {
            throw new IllegalArgumentException("Could not parse login form", error);
        }

        if (token[0] == null || token[0].isEmpty()) {
            throw new IllegalArgumentException("Login form has no CSRF token");
        }
        return token[0];
    }

    private static JsonNode selectProduct(String body) {
        try {
            JsonNode products = JSON.readTree(body).path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean(false)
                            && product.hasNonNull("id") && variant.hasNonNull("id")) {
                        return JSON.createObjectNode()
                            .put("product", product.path("id").asText())
                            .put("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException error) {
            throw new IllegalArgumentException("Invalid catalog", error);
        }
        throw new IllegalArgumentException("Catalog has no in-stock variant");
    }

    private static Session handleLoginResponse(Session session) {
        if (session.isFailed()) {
            return session;
        }

        if (session.getInt("loginStatus") == 302) {
            return session.contains("location") ? session : session.markAsFailed();
        }

        try {
            JsonNode response = JSON.readTree(session.getString("loginBody"));
            JsonNode csrf = response.path("csrf");
            if (csrf.isMissingNode() || csrf.isNull() || csrf.asText().isEmpty()) {
                return session.markAsFailed();
            }
            return session.set("csrf", csrf.asText());
        } catch (IOException | RuntimeException error) {
            return session.markAsFailed();
        }
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(session -> session
                .remove("csrf")
                .remove("formCsrf")
                .remove("loginBody")
                .remove("location")
                .remove("selection")
                .remove("product")
                .remove("variant")
                .remove("cart")
                .remove("etag"))
            .exec(http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    bodyString().transform(ModelSimulation::formCsrf).saveAs("formCsrf")
                ))
            .exitHereIfFailed()
            .exec(http("login")
                .post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("username", "bench-" + ((session.userId() - 1) % 16 + 1))
                    .put("password", "bench")
                    .put("csrf", session.getString("formCsrf"))
                    .toString()))
                .check(
                    status().in(200, 302),
                    status().saveAs("loginStatus"),
                    header("Location").optional().saveAs("location"),
                    bodyString().optional().saveAs("loginBody")
                ))
            .exec(ModelSimulation::handleLoginResponse)
            .exitHereIfFailed()
            .exec(doIf(session -> session.getInt("loginStatus") == 302).then(
                exec(http("login redirect")
                    .get("#{location}")
                    .disableFollowRedirect()
                    .check(
                        status().is(200),
                        jsonPath("$.csrf").saveAs("csrf")
                    ))
            ))
            .exitHereIfFailed()
            .exec(http("catalog")
                .get("/v2/catalog")
                .check(
                    status().is(200),
                    bodyString().transform(ModelSimulation::selectProduct).saveAs("selection")
                ))
            .exitHereIfFailed()
            .exec(session -> {
                JsonNode selection = (JsonNode) session.get("selection");
                return session
                    .set("product", selection.path("product").asText())
                    .set("variant", selection.path("variant").asText());
            })
            .exec(http("cart")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("product_id", session.getString("product"))
                    .put("variant_id", session.getString("variant"))
                    .toString()))
                .check(
                    status().is(201),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                ))
            .exitHereIfFailed()
            .exec(http("checkout")
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("cart_id", session.getString("cart"))
                    .toString()))
                .check(
                    status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").exists(),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                ))
            .exitHereIfFailed();
    }

    public ModelSimulation() {
        setUp(
            scenario("checkout threshold")
                .exec(repeat(2).on(journey()))
                .injectOpen(atOnceUsers(2))
        )
        .protocols(HTTP)
        .assertions(
            details("checkout").responseTime().percentile3().lt(250),
            global().failedRequests().count().is(0L)
        );
    }
}
