import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = { users: 2, iterations: 2, mode: 'threshold' };
const rows = [
  { username: 'bench-1', password: 'bench', quantity: 2 },
  { username: 'bench-2', password: 'bench', quantity: 3 },
  { username: 'bench-3', password: 'bench', quantity: 4 },
  { username: 'bench-4', password: 'bench', quantity: 5 },
  { username: 'bench-5', password: 'bench', quantity: 6 },
  { username: 'bench-6', password: 'bench', quantity: 7 },
  { username: 'bench-7', password: 'bench', quantity: 8 },
  { username: 'bench-8', password: 'bench', quantity: 9 },
  { username: 'bench-9', password: 'bench', quantity: 10 },
  { username: 'bench-10', password: 'bench', quantity: 11 },
  { username: 'bench-11', password: 'bench', quantity: 12 },
  { username: 'bench-12', password: 'bench', quantity: 13 },
  { username: 'bench-13', password: 'bench', quantity: 14 },
  { username: 'bench-14', password: 'bench', quantity: 15 },
  { username: 'bench-15', password: 'bench', quantity: 16 },
  { username: 'bench-16', password: 'bench', quantity: 17 }
];

const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s'
    }
  },
  thresholds: {
    checks: ['rate==1'],
    'http_req_duration{name:checkout}': ['p(95)<250']
  }
};

let csrf = '';
let cart = '';
let grant = '';
const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const r = http.request(method, base + path, data === null ? null : JSON.stringify(data), {
    headers: Object.assign(
      { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      extra
    ),
    tags: { name: method === 'POST' && path === '/v2/orders' ? 'checkout' : path },
    redirects: 0,
    timeout: '3s'
  });

  const b = body(r);
  if (b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    failure.add(
      r.status >= 400 &&
      !(r.status === 401 && b.error === 'expired') &&
      r.status !== 429
    );
  }
  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = r.html().find('input[name="csrf"]').first().attr('value');
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token
  });
  if (r.status === 302) {
    r = raw(r.headers.Location);
    grant = body(r).grant_id;
  }
  check(r, { login: r => r.status === 200 });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401 && ['expired', 'session'].indexOf(body(r).error) >= 0) {
    const renewed = raw('/v2/session/renew', 'POST', {});
    if (renewed.status !== 200) login();
    if (cart) raw('/v2/carts/' + cart + '/recover', 'POST', {});
    r = raw(path, method, data, extra);
  }
  return r;
}

function work(override) {
  if (cfg.workload || !csrf) login();
  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    sleep(Number(r.headers['Retry-After']) + 0.01);
    r = request(path, 'POST', {});
  }
  check(r, {
    'operation or expected throttle': r =>
      (r.status === 200 && body(r).ok === true) ||
      (cfg.completion && r.status === 429)
  });
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';
  login();

  if (cfg.mode === 'challenge') {
    let r = request('/v2/challenge-form');
    const form = r.html().find('form');
    const token = form.find('input[name="challenge"]').first().attr('value');
    r = request(form.attr('action'), 'POST', { challenge: token });
    r = request(r.headers.Location);
    grant = body(r).grant_id;
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product;
  for (let n = 0; n < 3 && page; n++) {
    const b = body(request(page));
    product = b.data.products.find(p => p.variants.some(v => v.in_stock));
    if (product) break;
    page = b.next;
  }

  if (!product) {
    check(false, { 'eligible product': x => x });
    return;
  }

  const variant = product.variants.find(v => v.in_stock);
  const cartData = { product_id: product.id, variant_id: variant.id };
  if (grant) cartData.grant_id = grant;
  let r = request('/v2/carts', 'POST', cartData);
  cart = body(r).id;
  let etag = r.headers.Etag;
  if (!check(r, { cart: r => r.status === 201 && !!body(r).id })) return;

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data'
      ? rows[(__VU - 1) % rows.length].quantity
      : (cfg.quantity || 2);
    r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, { 'If-Match': etag });
    if (r.status === 412) {
      etag = request('/v2/carts/' + cart).headers.Etag;
      r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, { 'If-Match': etag });
    }
    etag = r.headers.Etag;
    check(r, { update: r => r.status === 200 });
  }

  let reservation;
  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', { cart_id: cart });
    const url = body(r).status_url;
    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(url);
      const b = body(r);
      if (b.status === 'ready') {
        reservation = b.reservation_id;
        break;
      }
      if (b.status === 'failed') {
        check(false, { 'reservation ready': x => x });
        return;
      }
    }
    if (!reservation) return;
  }

  r = request(
    '/v2/orders',
    'POST',
    { cart_id: cart, reservation_id: reservation },
    { 'Idempotency-Key': cart, 'If-Match': etag }
  );
  check(r, { accepted: r => r.status === 201 && body(r).accepted === true });

  if (cfg.mode === 'threshold') raw('/v2/health');
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work();
  } else if (cfg.mode === 'errors') {
    login();
    for (let n = 0; n < 4; n++) work();
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}

import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

BASE_URL = os.environ["BASE_URL"]
USERS = 2
ITERATIONS = 2
CHECKOUT_LIMIT_MS = 250

_user_lock = Semaphore()
_user_number = 0


class InputParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attributes = {key.lower(): value for key, value in attrs}
        if attributes.get("name") == "csrf" and attributes.get("value"):
            self.csrf = attributes["value"]


def form_token(text):
    parser = InputParser()
    parser.feed(text)
    return parser.csrf


def safe_login_location(location):
    if not location:
        return None
    absolute = urljoin(BASE_URL.rstrip("/") + "/v2/login", location)
    parsed = urlsplit(absolute)
    if parsed.scheme != "http" or parsed.hostname != "127.0.0.1" or parsed.port != 8000:
        return None
    return absolute


def select_product(body):
    data = body.get("data")
    if not isinstance(data, dict):
        return None
    products = data.get("products")
    if not isinstance(products, list):
        return None
    for product in products:
        if not isinstance(product, dict) or not product.get("id"):
            continue
        for variant in product.get("variants") or []:
            if isinstance(variant, dict) and variant.get("id") and variant.get("in_stock"):
                return product["id"], variant["id"]
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = lambda self: 0

    def on_start(self):
        global _user_number
        with _user_lock:
            _user_number += 1
            number = _user_number
        self.username = "bench-" + str((number - 1) % 16 + 1)
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.iteration = 0

    def raw(self, path, method="GET", data=None, headers=None, name=None,
            expected=(200,), validate=None, allow_expiry=False):
        request_headers = {"Content-Type": "application/json"}
        if self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(
            method, path, json=data, headers=request_headers, name=name,
            catch_response=True, allow_redirects=False, timeout=3
        ) as response:
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {}
            except (ValueError, TypeError):
                body = {}

            is_expiry = (
                response.status_code == 401
                and body.get("error") in ("expired", "session")
            )
            errors = []
            if response.status_code not in expected:
                if not (allow_expiry and is_expiry):
                    errors.append("unexpected HTTP status %s" % response.status_code)
            elif validate:
                try:
                    error = validate(response, body)
                    if error:
                        errors.append(error)
                except Exception as exc:
                    errors.append("response validation error: %s" % exc)

            if method == "POST" and path == "/v2/orders":
                elapsed_ms = response.request_meta["response_time"]
                if elapsed_ms > CHECKOUT_LIMIT_MS:
                    errors.append(
                        "checkout latency %.1f ms exceeded 250 ms" % elapsed_ms
                    )

            if errors:
                response.failure("; ".join(errors))
                self.environment.process_exit_code = 99
                ok = False
            else:
                response.success()
                ok = True

            if 200 <= response.status_code < 400 and body.get("csrf"):
                self.csrf = body["csrf"]
            return response, body, ok

    def login(self):
        self.client.cookies.clear()
        self.csrf = ""

        def validate_form(response, body):
            if not form_token(response.text):
                return "login form is missing its CSRF input"
            return None

        response, _, ok = self.raw("/v2/login-form", validate=validate_form)
        if not ok:
            return False
        token = form_token(response.text)

        def validate_login(response, body):
            if response.status_code == 302:
                if not safe_login_location(response.headers.get("Location")):
                    return "login redirect has an invalid Location"
            elif not body.get("csrf"):
                return "login response is missing CSRF"
            return None

        response, _, ok = self.raw(
            "/v2/login", "POST",
            {"username": self.username, "password": "bench", "csrf": token},
            expected=(200, 302), validate=validate_login
        )
        if not ok:
            return False
        if response.status_code == 302:
            location = safe_login_location(response.headers.get("Location"))

            def validate_redirect(response, body):
                if not body.get("csrf"):
                    return "login redirect response is missing CSRF"
                return None

            _, _, ok = self.raw(location, validate=validate_redirect)
            if not ok:
                return False
        return bool(self.csrf)

    def recover(self, error):
        if error == "session":
            if not self.login():
                return False
        else:
            response, _, ok = self.raw(
                "/v2/session/renew", "POST", {}, allow_expiry=True
            )
            if not ok:
                return False
            if response.status_code == 401:
                if not self.login():
                    return False

        if self.cart:
            path = "/v2/carts/" + quote(str(self.cart), safe="") + "/recover"
            response, _, ok = self.raw(path, "POST", {}, expected=(200, 201))
            if not ok:
                return False
            self.etag = response.headers.get("ETag", self.etag)
        return True

    def request(self, path, method="GET", data=None, headers=None, name=None,
                expected=(200,), validate=None):
        current_headers = dict(headers or {})
        response, body, ok = self.raw(
            path, method, data, current_headers, name, expected, validate,
            allow_expiry=True
        )
        if not ok:
            return response, body, False

        if response.status_code == 401 and body.get("error") in ("expired", "session"):
            if not self.recover(body["error"]):
                return response, body, False
            if "If-Match" in current_headers:
                current_headers["If-Match"] = self.etag
            return self.raw(
                path, method, data, current_headers, name, expected, validate,
                allow_expiry=False
            )
        return response, body, True

    def journey(self):
        self.cart = ""
        self.etag = ""
        if not self.login():
            return

        def validate_catalog(response, body):
            if not select_product(body):
                return "catalog contains no in-stock variant"
            return None

        _, body, ok = self.request("/v2/catalog", validate=validate_catalog)
        if not ok:
            return
        product_id, variant_id = select_product(body)

        def validate_cart(response, body):
            if not body.get("id"):
                return "cart response is missing its ID"
            if not response.headers.get("ETag"):
                return "cart response is missing its ETag"
            return None

        response, body, ok = self.request(
            "/v2/carts", "POST",
            {"product_id": product_id, "variant_id": variant_id},
            expected=(201,), validate=validate_cart
        )
        if not ok:
            return
        self.cart = body["id"]
        self.etag = response.headers["ETag"]

        def validate_order(response, body):
            if body.get("accepted") is not True or not body.get("id"):
                return "checkout was not accepted"
            return None

        self.request(
            "/v2/orders", "POST", {"cart_id": self.cart},
            headers={
                "Idempotency-Key": "checkout-" + str(self.cart),
                "If-Match": self.etag,
            },
            name="checkout", expected=(201,), validate=validate_order
        )

    @task
    def run_journey(self):
        self.journey()
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        if self.first_tick:
            self.first_tick = False
            return USERS, USERS
        if self.runner.user_count == 0:
            return None
        return USERS, USERS

