import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL") == null
            ? "http://127.0.0.1:8000" : System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static Session absorbCsrf(Session session, String bodyKey) {
        if (!session.contains(bodyKey)) return session;
        try {
            JsonNode body = JSON.readTree(session.getString(bodyKey));
            if (body != null && body.hasNonNull("csrf")) {
                String token = body.get("csrf").asText();
                if (!token.isEmpty()) return session.set("csrf", token);
            }
        } catch (Exception ignored) {
            // A redirect response is permitted to have a non-JSON body.
        }
        return session;
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("csrf").remove("formCsrf")
                .remove("location").remove("loginBody").remove("redirectBody"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name='csrf']", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("username", "bench-" +
                        (Math.floorMod(session.userId() - 1, 16L) + 1))
                    .put("password", "bench")
                    .put("csrf", session.getString("formCsrf"))
                    .toString()))
                .check(
                    status().in(200, 302),
                    checkIf((response, session) -> response.status().code() == 200)
                        .then(jsonPath("$.csrf").saveAs("csrf")),
                    checkIf((response, session) -> response.status().code() == 302)
                        .then(header("Location").saveAs("location")),
                    checkIf((response, session) -> response.status().code() == 302)
                        .then(bodyString().optional().saveAs("loginBody"))
                ))
            .exitHereIfFailed()
            .exec(session -> absorbCsrf(session, "loginBody"))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .disableFollowRedirect()
                    .check(status().is(200), bodyString().saveAs("redirectBody")))
                    .exitHereIfFailed()
                    .exec(session -> absorbCsrf(session, "redirectBody"))
            ))
            .exec(session -> !session.contains("csrf")
                    || session.getString("csrf").isEmpty()
                ? session.markAsFailed() : session)
            .exitHereIfFailed();
    }

    private static ChainBuilder workOnce() {
        return exec(http("work").post("/v2/work")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(
                status().in(200, 401, 429),
                status().saveAs("workStatus"),
                checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.ok").is("true")),
                checkIf((response, session) -> response.status().code() == 200)
                    .then(jsonPath("$.csrf").optional().saveAs("csrf")),
                checkIf((response, session) -> response.status().code() == 401)
                    .then(jsonPath("$.error").in("expired", "session").saveAs("workError")),
                checkIf((response, session) -> response.status().code() == 429)
                    .then(header("Retry-After").is("1"))
            ))
            .exitHereIfFailed();
    }

    private static ChainBuilder renew() {
        return exec(http("renew").post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")))
            .exitHereIfFailed();
    }

    private static ChainBuilder journey() {
        ChainBuilder chain = login()
            .exec(session -> session.set("recovered", false).set("rateRetries", 0))
            .exec(workOnce());

        for (int i = 0; i < 5; i++) {
            chain = chain
                .exec(doIf(session -> session.getInt("workStatus") == 401
                        && !session.getBoolean("recovered")).then(
                    exec(session -> session.set("recovered", true))
                        .exec(doIf(session -> "expired".equals(session.getString("workError")))
                            .then(renew())
                            .elseDo(login()))
                        .exec(workOnce())
                ))
                .exec(doIf(session -> session.getInt("workStatus") == 429
                        && session.getInt("rateRetries") < 4).then(
                    pause(Duration.ofSeconds(1))
                        .exec(session -> session.set("rateRetries",
                            session.getInt("rateRetries") + 1))
                        .exec(workOnce())
                ));
        }

        return chain.exec(session -> session.getInt("workStatus") == 200
            ? session : session.markAsFailed());
    }

    public ModelSimulation() {
        setUp(
            scenario("workload")
                .exec(journey())
                .injectOpen(constantUsersPerSec(5.0).during(Duration.ofSeconds(38)))
        ).protocols(HTTP);
    }
}

