import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL") == null
            ? "http://127.0.0.1:8000" : System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static Session absorbCsrf(Session session, String bodyKey) {
        if (!session.contains(bodyKey)) return session;
        try {
            JsonNode body = JSON.readTree(session.getString(bodyKey));
            if (body != null && body.hasNonNull("csrf")) {
                String token = body.get("csrf").asText();
                if (!token.isEmpty()) return session.set("csrf", token);
            }
        } catch (Exception ignored) {
            // Redirect responses may have non-JSON bodies.
        }
        return session;
    }

    private static boolean validWork(String body, Session session) {
        int status = session.getInt("workStatus");
        if (status == 429) {
            try {
                return Double.parseDouble(session.getString("retryAfter")) == 1.0;
            } catch (RuntimeException error) {
                return false;
            }
        }
        try {
            JsonNode json = JSON.readTree(body);
            if (json == null) return false;
            if (status == 200) return json.path("ok").asBoolean(false);
            if (status == 401) {
                String error = json.path("error").asText();
                return "expired".equals(error) || "session".equals(error);
            }
        } catch (Exception ignored) {
            return false;
        }
        return false;
    }

    private static Session absorbWork(Session session) {
        session = absorbCsrf(session, "workBody");
        if (session.getInt("workStatus") == 401) {
            try {
                JsonNode body = JSON.readTree(session.getString("workBody"));
                return session.set("workError", body.path("error").asText());
            } catch (Exception error) {
                return session.markAsFailed();
            }
        }
        return session;
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("csrf").remove("formCsrf")
                .remove("location").remove("loginBody").remove("redirectBody"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name='csrf']", "value").saveAs("formCsrf")))
