import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '36s',
      preAllocatedVUs: 16,
      maxVUs: 16,
      gracefulStop: '4s',
    },
  },
  thresholds: { checks: ['rate>=0.99'] },
  noCookiesReset: true,
};

let csrf = '';

function body(response) {
  try {
    const value = response.json();
    return value && typeof value === 'object' ? value : {};
  } catch (_) {
    return {};
  }
}

function urlFor(path) {
  if (path.startsWith('/')) return base + path;
  if (path === base || path.startsWith(base + '/')) return path;
  throw new Error('Unexpected request location');
}

function raw(path, method = 'GET', data = null) {
  const response = http.request(
    method,
    urlFor(path),
    data === null ? null : JSON.stringify(data),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
      redirects: 0,
      timeout: '3s',
    }
  );

  const result = body(response);
  if (result.csrf) csrf = result.csrf;

  if (path === '/v2/work') {
    const expectedExpiry = response.status === 401 && result.error === 'expired';
    const expectedThrottle =
      response.status === 429 && Number(response.headers['Retry-After']) === 1;
    const success = response.status === 200 && result.ok === true;
    failure.add(!success && !expectedExpiry && !expectedThrottle);
  }
  return response;
}

function login() {
  csrf = '';
  const form = raw('/v2/login-form');
  let token;
  try {
    token = form.html().find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    token = null;
  }

  const formOK = check(form, {
    'login form has CSRF token': (r) => r.status === 200 && !!token,
  });
  if (!formOK) return false;

  let response = raw('/v2/login', 'POST', {
    username: `bench-${((__VU - 1) % 16) + 1}`,
    password: 'bench',
    csrf: token,
  });

  if (response.status === 302) {
    const location = response.headers.Location;
    if (!location) {
      check(response, { 'login redirect has location': () => false });
      return false;
    }
    response = raw(location);
  }

  return check(response, {
    'login succeeded': (r) => r.status === 200 && !!csrf,
  });
}

function workRequest(recovery) {
  let response = raw('/v2/work', 'POST', {});
  const error = body(response).error;

  if (
    !recovery.used &&
    response.status === 401 &&
    (error === 'expired' || error === 'session')
  ) {
    recovery.used = true;
    const renewed = raw('/v2/session/renew', 'POST', {});
    let recovered = renewed.status === 200;

    if (!recovered && error === 'session') recovered = login();
    if (recovered) response = raw('/v2/work', 'POST', {});
  }

  return response;
}

export default function () {
