import os
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

BASE_URL = os.environ["BASE_URL"]
RATE = 5
DURATION = 35
USERS = 8
TOTAL_ARRIVALS = RATE * DURATION


class CSRFParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.token = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attrs = dict(attrs)
        if attrs.get("name") == "csrf" and attrs.get("value"):
            self.token = attrs["value"]


class ArrivalPlan:
    def __init__(self):
        self.lock = Semaphore()
        self.started = None
        self.next_index = 0
        self.inflight = 0

    def claim(self):
        with self.lock:
            if self.next_index >= TOTAL_ARRIVALS:
                return None
            if self.started is None:
                self.started = time.monotonic()
            deadline = self.started + self.next_index / RATE
            self.next_index += 1
            self.inflight += 1
            return deadline

    def complete(self):
        with self.lock:
            self.inflight -= 1

    def state(self):
        with self.lock:
            return self.started, self.next_index, self.inflight


ARRIVALS = ArrivalPlan()
USER_LOCK = Semaphore()
USER_SEQUENCE = 0


def json_object(response):
    try:
        body = response.json()
    except (ValueError, TypeError):
        return {}
    return body if isinstance(body, dict) else {}


def same_host_location(location):
    if not location:
        return False
    target = urlsplit(urljoin(BASE_URL, location))
    base = urlsplit(BASE_URL)
    return (target.scheme, target.netloc) == (base.scheme, base.netloc)


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = lambda self: 0

    def on_start(self):
        global USER_SEQUENCE
        with USER_LOCK:
            USER_SEQUENCE += 1
            number = USER_SEQUENCE
        self.username = "bench-" + str((number - 1) % 16 + 1)
        self.csrf = ""
        if not self.login():
            raise StopUser()

    def capture_csrf(self, body):
        if body.get("csrf"):
            self.csrf = body["csrf"]

    def login(self):
        self.client.cookies.clear()
        self.csrf = ""

        with self.client.get(
            "/v2/login-form", catch_response=True, allow_redirects=False, timeout=3
        ) as response:
            if response.status_code != 200:
                response.failure("login form request failed")
                return False
            parser = CSRFParser()
            try:
                parser.feed(response.text)
            except Exception:
                response.failure("invalid login form")
                return False
            if not parser.token:
                response.failure("login CSRF token missing")
                return False
            token = parser.token
            response.success()

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": token},
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            body = json_object(response)
            self.capture_csrf(body)
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not same_host_location(location):
                    response.failure("invalid login redirect")
                    return False
                response.success()
            elif response.status_code == 200 and self.csrf:
                response.success()
                return True
            else:
                response.failure("login failed or CSRF token missing")
                return False

        with self.client.get(
            location, catch_response=True, allow_redirects=False, timeout=3
        ) as response:
            body = json_object(response)
            self.capture_csrf(body)
            if response.status_code != 200 or not self.csrf:
                response.failure("login redirect failed or CSRF token missing")
                return False
            response.success()
            return True

    def recover_session(self, reason):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            body = json_object(response)
            if response.status_code == 200:
                self.capture_csrf(body)
                response.success()
                return bool(self.csrf)
            if (
                response.status_code == 401
                and body.get("error") in ("expired", "session")
            ) or (reason == "session" and response.status_code == 403):
                response.success()
            else:
                response.failure("session renewal failed unexpectedly")
                return False
        return self.login()

    def work(self):
        recoveries = 0
        retries_429 = 0

        while True:
            action = None
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                allow_redirects=False,
                timeout=3,
            ) as response:
                body = json_object(response)
                self.capture_csrf(body)

                if response.status_code == 200 and body.get("ok") is True:
                    response.success()
                    return True

                if (
                    response.status_code == 401
                    and body.get("error") in ("expired", "session")
                    and recoveries == 0
                ):
                    response.success()
                    action = ("recover", body["error"])
                elif response.status_code == 429 and retries_429 < 4:
                    try:
                        retry_after = float(response.headers.get("Retry-After", ""))
                    except ValueError:
                        retry_after = 0
                    if retry_after != 1:
                        response.failure("invalid Retry-After")
                        return False
                    response.success()
                    action = ("retry", retry_after)
                else:
                    response.failure("unexpected work response")
                    return False

            if action[0] == "recover":
                recoveries += 1
                if not self.recover_session(action[1]):
                    return False
            else:
                retries_429 += 1
                sleep(action[1])

    @task
    def run_work(self):
        deadline = ARRIVALS.claim()
        if deadline is None:
            raise StopUser()
        try:
            sleep(max(0, deadline - time.monotonic()))
            self.work()
        finally:
            ARRIVALS.complete()


class WorkShape(LoadTestShape):
    def tick(self):
        started, claimed, inflight = ARRIVALS.state()

        if started is None:
            if self.get_run_time() >= 10:
                return None
            return USERS, USERS

        if claimed >= TOTAL_ARRIVALS:
            if inflight == 0 or time.monotonic() >= started + DURATION + 5:
                return None
            # Do not replace users that have finished while the last work drains.
            return self.runner.user_count, USERS

        if time.monotonic() >= started + DURATION + 5:
            return None
        return USERS, USERS

