import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';

const accounts = JSON.parse(open('/fixtures/accounts.json'));
const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

if (
  !Array.isArray(accounts) ||
  accounts.length < 2 ||
  !accounts[0].username ||
  !accounts[0].password ||
  !accounts[1].username ||
  !accounts[1].password ||
  accounts[0].username === accounts[1].username
) {
  throw new Error('Two distinct fixture accounts are required');
}

let csrf = '';
let cart = null;

function body(response) {
  try {
    const value = response.json();
    return value && typeof value === 'object' ? value : {};
  } catch (_) {
    return {};
  }
}

function url(path) {
  if (/^https?:\/\//i.test(path)) {
    if (path !== base && !path.startsWith(base + '/')) {
      throw new Error('Unexpected URL origin');
    }
    return path;
  }
  if (!path || path[0] !== '/') throw new Error('Expected a relative URL');
  return base + path;
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && csrf) headers['X-CSRF-Token'] = csrf;

  const response = http.request(
    method,
    url(path),
    data === null ? null : JSON.stringify(data),
    { headers, redirects: 0, timeout: '3s' }
  );
  const result = body(response);
  if (result.csrf) csrf = result.csrf;
  return response;
}

function login() {
  const account = accounts[exec.vu.idInTest - 1];
  if (!account) {
    check(false, { 'account assigned to VU': () => false });
    return false;
  }

  csrf = '';
  let response = raw('/v2/login-form');
  if (!check(response, { 'login form loaded': (r) => r.status === 200 })) {
    return false;
  }

  let token;
  try {
    const document = response.html();
    token = document
      .find('form[action="/v2/login"] input[name="csrf"]')
      .first()
      .attr('value');
    if (!token) token = document.find('input[name="csrf"]').first().attr('value');
  } catch (_) {
    token = null;
  }
  if (!check(token, { 'login CSRF found': (v) => !!v })) return false;

  response = raw('/v2/login', 'POST', {
    username: account.username,
    password: account.password,
    csrf: token,
  });
  if (response.status === 302) {
    const location = response.headers.Location;
    if (!check(location, { 'login redirect has location': (v) => !!v })) {
      return false;
    }
    response = raw(location);
  }
  return check(response, {
    'login succeeded': (r) => r.status === 200 && !!csrf,
  });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let response = raw(path, method, data, extra);
  const error = body(response).error;

  if (response.status === 401 && (error === 'expired' || error === 'session')) {
    if (error === 'expired') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      if (!check(renewed, { 'session renewed': (r) => r.status === 200 && !!csrf })) {
        return response;
      }
    } else if (!login()) {
      return response;
    }

    if (cart !== null) {
      const recovered = raw('/v2/carts/' + cart + '/recover', 'POST', {});
      if (!check(recovered, { 'cart recovered': (r) => r.status >= 200 && r.status < 300 })) {
        return response;
      }
    }
    response = raw(path, method, data, extra);
  }
  return response;
}

export default function () {
  csrf = '';
  cart = null;
  if (!login()) return;

  // Keep both users active concurrently without sharing their sessions.
  sleep(0.5);

  const catalog = request('/v2/catalog');
  const products = body(catalog).data && body(catalog).data.products;
  if (!check(catalog, {
    'catalog loaded': (r) => r.status === 200 && Array.isArray(products),
  })) return;

  const product = products.find(
    (p) => Array.isArray(p.variants) && p.variants.some((v) => v.in_stock)
  );
  if (!check(product, { 'eligible product found': (p) => !!p })) return;
  const variant = product.variants.find((v) => v.in_stock);

  const created = request('/v2/carts', 'POST', {
    product_id: product.id,
    variant_id: variant.id,
  });
  const cartId = body(created).id;
  if (!check(created, {
    'cart created': (r) => r.status === 201 && cartId != null,
  })) return;
  cart = cartId;

  sleep(0.25);

  const headers = { 'Idempotency-Key': String(cart) };
  const etag = created.headers.Etag || created.headers.ETag;
  if (etag) headers['If-Match'] = etag;

  const order = request('/v2/orders', 'POST', { cart_id: cart }, headers);
  check(order, {
    'order accepted': (r) => r.status === 201 && body(r).accepted === true,
  });
}

import json
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit
from uuid import uuid4

from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

USERS = 2
ITERATIONS = 2
HOST = "http://127.0.0.1:8000"

with open("/fixtures/accounts.json", encoding="utf-8") as fixture:
    ROWS = json.load(fixture)

if (
    not isinstance(ROWS, list)
    or len(ROWS) < USERS
    or any(
        not isinstance(row, dict)
        or not row.get("username")
        or not row.get("password")
        for row in ROWS[:USERS]
    )
    or len({row["username"] for row in ROWS[:USERS]}) != USERS
):
    raise ValueError("Fixture must contain distinct credentials for all users")

assignment_lock = Semaphore()
next_assignment = 0
aborted = Event()
finished = Event()


class Barrier:
    def __init__(self):
        self.lock = Semaphore()
        self.count = 0
        self.ready = Event()

    def wait(self, final=False):
        with self.lock:
            self.count += 1
            if self.count == USERS:
                if final:
                    finished.set()
                self.ready.set()
            elif self.count > USERS:
                raise RuntimeError("Barrier used by too many users")
        if not self.ready.wait(timeout=5) or aborted.is_set():
            raise RuntimeError("Journey synchronization failed")


login_barriers = [Barrier() for _ in range(ITERATIONS)]
cart_barriers = [Barrier() for _ in range(ITERATIONS)]
end_barriers = [Barrier() for _ in range(ITERATIONS)]


class FlowError(Exception):
    pass


class InputParser(HTMLParser):
    def __init__(self, wanted):
        super().__init__(convert_charrefs=True)
        self.wanted = wanted
        self.values = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attributes = {key.lower(): value for key, value in attrs}
        if attributes.get("name") == self.wanted and attributes.get("value"):
            self.values.append(attributes["value"])

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def input_value(html, name):
    parser = InputParser(name)
    parser.feed(html)
    return parser.values[0] if parser.values else None


def local_path(location, base="/"):
    if not isinstance(location, str) or not location:
        raise ValueError("Missing location")
    absolute = urljoin(HOST + base, location)
    parts = urlsplit(absolute)
    if (
        parts.scheme != "http"
        or parts.netloc != "127.0.0.1:8000"
        or not parts.path.startswith("/v2/")
        or parts.fragment
    ):
        raise ValueError("Location is not a local protocol endpoint")
    return parts.path + ("?" + parts.query if parts.query else "")


def valid_location(response, base):
    try:
        local_path(response.headers.get("Location"), base)
        return True
    except ValueError:
        return False


class MatrixUser(HttpUser):
    host = HOST
    wait_time = lambda self: 0

    def on_start(self):
        global next_assignment
        with assignment_lock:
            index = next_assignment
            next_assignment += 1
        if index >= USERS:
            aborted.set()
            self.environment.process_exit_code = 1
            raise StopUser()

        self.row = ROWS[index]
        self.username = self.row["username"]
        self.password = self.row["password"]
        self.iteration = 0
        self.csrf = ""
        self.cart = ""
        self.etag = ""

    def raw(self, path, method="GET", data=None, headers=None,
            statuses=(200,), check=None, allow_recovery=False):
        if aborted.is_set():
            raise FlowError("Another user aborted")

        request_headers = dict(headers or {})
        if method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        failed = False
        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {}
            except (ValueError, TypeError):
                body = {}

            recoverable = (
                allow_recovery
                and response.status_code == 401
                and body.get("error") in ("expired", "session")
            )
            valid = recoverable or response.status_code in statuses
            if valid and not recoverable and check is not None:
                try:
                    valid = bool(check(response, body))
                except (ValueError, TypeError, KeyError):
                    valid = False

            if valid:
                response.success()
                if response.status_code < 400 and body.get("csrf"):
                    self.csrf = body["csrf"]
            else:
                response.failure(
                    "Unexpected response or failed assertion: {} {}".format(
                        method, path
                    )
                )
                failed = True

        if failed:
            raise FlowError("Request failed: {} {}".format(method, path))
        return response, body

    def login(self):
        self.csrf = ""
        form, _ = self.raw(
            "/v2/login-form",
            check=lambda response, body: bool(input_value(response.text, "csrf")),
        )
        token = input_value(form.text, "csrf")
        response, body = self.raw(
            "/v2/login",
            "POST",
            {"username": self.username, "password": self.password, "csrf": token},
            statuses=(200, 302),
            check=lambda response, body: (
                valid_location(response, "/v2/login")
                if response.status_code == 302
                else bool(body.get("csrf") and body.get("user"))
            ),
        )
        if response.status_code == 302:
            location = local_path(response.headers["Location"], "/v2/login")
            self.raw(
                location,
                check=lambda response, body: bool(body.get("csrf") or self.csrf),
            )
        if not self.csrf:
            raise FlowError("Login did not provide a CSRF token")

    def recover(self):
        response, _ = self.raw(
            "/v2/session/renew",
            "POST",
            {},
            statuses=(200,),
            allow_recovery=True,
            check=lambda response, body: bool(body.get("csrf")),
        )
        if response.status_code == 401:
            self.login()
        if self.cart:
            response, _ = self.raw(
                "/v2/carts/{}/recover".format(quote(str(self.cart), safe="")),
                "POST",
                {},
            )
            self.etag = response.headers.get("ETag", self.etag)

    def request(self, path, method="GET", data=None, headers=None,
                statuses=(200,), check=None):
        request_headers = dict(headers or {})
        for attempt in range(2):
            response, body = self.raw(
                path,
                method,
                data,
                request_headers,
                statuses,
                check,
                allow_recovery=(attempt == 0),
            )
            if response.status_code == 401:
                self.recover()
                if "If-Match" in request_headers and self.etag:
                    request_headers["If-Match"] = self.etag
                continue
            return response, body
        raise FlowError("Recovery exhausted")

    def journey(self):
        self.client.cookies.clear()
        self.cart = ""
        self.etag = ""
        self.login()
        login_barriers[self.iteration].wait()

        _, catalog = self.request(
            "/v2/catalog",
            check=lambda response, body: isinstance(
                body.get("data", {}).get("products"), list
            ),
        )
        product = None
        variant = None
        for item in catalog["data"]["products"]:
            for candidate in item.get("variants", []):
                if item.get("id") is not None and candidate.get("id") is not None and candidate.get("in_stock"):
                    product, variant = item, candidate
                    break
            if product is not None:
                break
        if product is None:
            raise FlowError("No in-stock catalog variant")

        response, body = self.request(
            "/v2/carts",
            "POST",
            {"product_id": product["id"], "variant_id": variant["id"]},
            statuses=(201,),
            check=lambda response, body: bool(
                body.get("id") and response.headers.get("ETag")
            ),
        )
        self.cart = body["id"]
        self.etag = response.headers["ETag"]
        cart_barriers[self.iteration].wait()

        self.request(
            "/v2/orders",
            "POST",
            {"cart_id": self.cart},
            headers={
                "Idempotency-Key": uuid4().hex,
                "If-Match": self.etag,
            },
            statuses=(201,),
            check=lambda response, body: (
                body.get("accepted") is True and bool(body.get("id"))
            ),
        )
        end_barriers[self.iteration].wait(
            final=(self.iteration == ITERATIONS - 1)
        )

    @task
    def run_scenario(self):
        try:
            self.journey()
            self.iteration += 1
        except Exception:
            aborted.set()
            self.environment.process_exit_code = 1
            raise StopUser()
        if self.iteration >= ITERATIONS:
            raise StopUser()


class MatrixShape(LoadTestShape):
    def tick(self):
        if finished.is_set() or aborted.is_set():
            return None
        if self.get_run_time() > 60:
            self.runner.environment.process_exit_code = 1
            return None
        return USERS, USERS

