import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static Session readLoginResponse(Session session) {
        int status = session.getInt("loginStatus");
        if (session.contains("loginBody")) {
            try {
                JsonNode body = JSON.readTree(session.getString("loginBody"));
                if (body != null) {
                    String csrf = body.path("csrf").asText("");
                    String grant = body.path("grant_id").asText("");
                    if (!csrf.isEmpty()) {
                        session = session.set("csrf", csrf);
                    }
                    if (!grant.isEmpty()) {
                        session = session.set("grant", grant);
                    }
                }
            } catch (Exception ignored) {
                if (status == 200) {
                    return session.markAsFailed();
                }
            }
        }
        if (status == 200 && !session.contains("csrf")) {
            return session.markAsFailed();
        }
        if (status == 302 && !session.contains("location")) {
            return session.markAsFailed();
        }
        return session;
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                String productId = product.path("id").asText("");
                for (JsonNode variant : product.path("variants")) {
                    String variantId = variant.path("id").asText("");
                    if (!productId.isEmpty() && !variantId.isEmpty()
                            && variant.path("in_stock").asBoolean(false)) {
                        return session.set("product", productId)
                            .set("variant", variantId);
                    }
                }
            }
        } catch (Exception ignored) {
            // A missing or unusable catalog fails the journey.
        }
        return session.markAsFailed();
    }

    private static String cartBody(Session session) {
        ObjectNode body = JSON.createObjectNode()
            .put("product_id", session.getString("product"))
            .put("variant_id", session.getString("variant"));
        if (session.contains("grant") && !session.getString("grant").isEmpty()) {
            body.put("grant_id", session.getString("grant"));
        }
        return body.toString();
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(session -> session
                .remove("csrf").remove("formCsrf").remove("location")
                .remove("loginBody").remove("grant")
                .remove("product").remove("variant")
                .remove("cart").remove("etag").remove("catalogBody"))
            .exec(http("login form")
                .get("/v2/login-form")
                .disableFollowRedirect()
                .check(status().is(200),
                    css("input[name=csrf]", "value").saveAs("formCsrf")))
            .exitHereIfFailed()
            .exec(http("login")
                .post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("username", "bench-1")
                    .put("password", "bench")
                    .put("csrf", session.getString("formCsrf"))
                    .toString()))
                .check(status().in(200, 302),
                    status().saveAs("loginStatus"),
                    header("Location").optional().saveAs("location"),
                    bodyString().optional().saveAs("loginBody")))
            .exitHereIfFailed()
            .exec(ModelSimulation::readLoginResponse)
            .exitHereIfFailed()
            .exec(doIf(session -> session.getInt("loginStatus") == 302).then(
                exec(http("login redirect")
                    .get("#{location}")
                    .disableFollowRedirect()
                    .check(status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.grant_id").optional().saveAs("grant")))))
            .exitHereIfFailed()
            .exec(session -> session.contains("csrf")
                ? session : session.markAsFailed())
            .exitHereIfFailed()
            .exec(http("catalog")
                .get("/v2/catalog")
                .disableFollowRedirect()
                .check(status().is(200),
                    jsonPath("$.data.products").exists(),
                    bodyString().saveAs("catalogBody")))
            .exitHereIfFailed()
            .exec(ModelSimulation::selectProduct)
            .exitHereIfFailed()
            .exec(http("cart")
                .post("/v2/carts")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(ModelSimulation::cartBody))
                .check(status().is(201),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed()
            .exec(http("checkout")
                .post("/v2/orders")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("cart_id", session.getString("cart"))
                    .toString()))
                .check(status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").exists(),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exitHereIfFailed();
    }

    public ModelSimulation() {
        setUp(
            scenario("owned checkout")
                .during(Duration.ofSeconds(38)).on(
                    pace(Duration.ofSeconds(1)),
                    exec(journey()))
                .injectOpen(atOnceUsers(1))
        ).protocols(HTTP);
    }
}

