import http from 'k6/http';
import { check, sleep } from 'k6';

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    checkout_journeys: {
      executor: 'constant-arrival-rate',
      rate: 1,
      timeUnit: '1s',
      duration: '36s',
      preAllocatedVUs: 4,
      maxVUs: 4,
      gracefulStop: '5s',
    },
  },
  noCookiesReset: true,
  thresholds: { checks: ['rate>=0.99'] },
};

const expected = http.expectedStatuses({ min: 200, max: 299 }, 302, 401, 412);
let csrf = '';
let cart = '';
let grant = '';

function json(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return '';
}

function urlFor(path) {
  if (typeof path !== 'string' || !path) return '';
  if (path.indexOf(base + '/') === 0) return path;
  if (path.charAt(0) === '/' && path.charAt(1) !== '/') return base + path;
  return '';
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const url = urlFor(path);
  if (!url) return null;

  const headers = Object.assign({ 'Content-Type': 'application/json' }, extra);
  if (method !== 'GET' && csrf) headers['X-CSRF-Token'] = csrf;

  const response = http.request(
    method,
    url,
    data === null ? null : JSON.stringify(data),
    { headers, redirects: 0, timeout: '3s', responseCallback: expected }
  );
  const result = json(response);
  if (result.csrf) csrf = result.csrf;
  return response;
}

function login() {
  csrf = '';
  let response = raw('/v2/login-form');
  if (!check(response, { 'login form received': r => r && r.status === 200 })) {
    return false;
  }

  const doc = response.html();
  let input = doc.find('form[action="/v2/login"] input[name="csrf"]').first();
  if (!input.size()) input = doc.find('input[name="csrf"]').first();
  const token = input.attr('value');
  if (!check(token, { 'login form contains CSRF token': t => !!t })) return false;

  response = raw('/v2/login', 'POST', {
    username: `bench-${((__VU - 1) % 16) + 1}`,
    password: 'bench',
    csrf: token,
  });

  if (response && response.status === 302) {
    const location = header(response, 'Location');
    if (!check(location, { 'login redirect location present': v => !!urlFor(v) })) {
      return false;
    }
    response = raw(location);
    if (response) grant = json(response).grant_id || '';
  }

  return check(response, {
    'login succeeded': r => r && r.status === 200 && !!csrf,
  });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let response = raw(path, method, data, extra);
  if (!response || response.status !== 401) return response;

  const error = json(response).error;
  if (error !== 'expired' && error !== 'session') return response;

  const renewed = raw('/v2/session/renew', 'POST', {});
  if (!renewed || renewed.status !== 200) {
    if (error !== 'session' || !login()) {
      check(false, { 'session recovery succeeded': v => v });
      return response;
    }
  }

  if (cart) {
    const recovered = raw(`/v2/carts/${encodeURIComponent(cart)}/recover`, 'POST', {});
    if (!check(recovered, {
      'cart recovery succeeded': r => r && r.status >= 200 && r.status < 300,
    })) {
      return response;
    }
  }

  return raw(path, method, data, extra);
}

function journey() {
  csrf = '';
  cart = '';
  grant = '';
  if (!login()) return;

  let page = '/v2/catalog';
  let product;
  for (let n = 0; n < 3 && page; n++) {
    const response = request(page);
    if (!check(response, { 'catalog received': r => r && r.status === 200 })) return;

    const result = json(response);
    const products = result.data && result.data.products;
    if (!check(products, { 'catalog products present': p => Array.isArray(p) })) return;
    product = products.find(p =>
      Array.isArray(p.variants) && p.variants.some(v => v.in_stock)
    );
    if (product) break;
    page = result.next;
  }

  if (!check(product, { 'in-stock product found': p => !!p })) return;
  const variant = product.variants.find(v => v.in_stock);
  const cartPayload = { product_id: product.id, variant_id: variant.id };
  if (grant) cartPayload.grant_id = grant;

  let response = request('/v2/carts', 'POST', cartPayload);
  grant = '';
  if (!check(response, {
    'cart created': r => r && r.status === 201 && !!json(r).id,
  })) return;

  cart = json(response).id;
  let etag = header(response, 'ETag');
  const orderPayload = { cart_id: cart };
  const orderHeaders = { 'Idempotency-Key': `checkout-${cart}` };
  if (etag) orderHeaders['If-Match'] = etag;

  response = request('/v2/orders', 'POST', orderPayload, orderHeaders);
  if (response && response.status === 412) {
    const current = request(`/v2/carts/${encodeURIComponent(cart)}`);
    if (!check(current, {
      'cart reread succeeded': r => r && r.status === 200 && !!header(r, 'ETag'),
    })) return;
    etag = header(current, 'ETag');
    orderHeaders['If-Match'] = etag;
    response = request('/v2/orders', 'POST', orderPayload, orderHeaders);
  }

  check(response, {
