import os
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"]
RATE = 1.0
ARRIVALS = 36
MAX_VUS = 4


class JourneyError(Exception):
    pass


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.current = None
        self.loose_inputs = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "form":
            self.current = {"action": attrs.get("action", ""), "inputs": []}
            self.forms.append(self.current)
        elif tag.lower() == "input":
            if self.current is None:
                self.loose_inputs.append(attrs)
            else:
                self.current["inputs"].append(attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current = None

    def csrf(self):
        preferred = [
            form for form in self.forms
            if urlsplit(form["action"]).path.rstrip("/") == "/v2/login"
        ]
        groups = preferred + [form for form in self.forms if form not in preferred]
        groups.append({"inputs": self.loose_inputs})
        for group in groups:
            for attrs in group["inputs"]:
                if attrs.get("name") == "csrf" and attrs.get("value"):
                    return attrs["value"]
        return None


def form_token(text):
    parser = LoginFormParser()
    parser.feed(text)
    return parser.csrf()


def same_origin_location(response):
    location = response.headers.get("Location")
    if not location:
        return None
    resolved = urljoin(response.url, location)
    actual = urlsplit(resolved)
    expected = urlsplit(BASE_URL)
    if (actual.scheme, actual.hostname, actual.port) != (
        expected.scheme, expected.hostname, expected.port
    ):
        return None
    if actual.username or actual.password:
        return None
    return resolved


class ArrivalPlan:
    def __init__(self):
        self.lock = Semaphore()
        self.epoch = None
        self.number = 0
        self.first_checkout = None
        self.user_number = 0

    def user(self):
        with self.lock:
            number = self.user_number
            self.user_number += 1
            return number

    def next(self):
        with self.lock:
            now = time.monotonic()
            if self.epoch is None:
                self.epoch = now

            # Do not issue a backlog as a compensating burst.
            if now > self.epoch + self.number / RATE + 0.1:
                self.number = max(
                    self.number, int((now - self.epoch) * RATE) + 1
                )
            if self.number >= ARRIVALS:
                return False
            deadline = self.epoch + self.number / RATE
            self.number += 1

        delay = deadline - time.monotonic()
        if delay > 0:
            sleep(delay)
        return True

    def committed(self, request_start):
        with self.lock:
            if self.first_checkout is None:
                self.first_checkout = request_start


PLAN = ArrivalPlan()


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = lambda self: 0

    def on_start(self):
        number = PLAN.user()
        self.username = "bench-" + str(number % 16 + 1)
        self.csrf = ""
        self.cart = ""
        self.etag = ""

    def raw(self, path, method="GET", data=None, headers=None, statuses=(200,),
            check=None, expected_auth=(), name=None):
        request_headers = dict(headers or {})
        if method != "GET" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf

        started = time.monotonic()
        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            name=name,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {}
            except (ValueError, TypeError):
                body = {}

            error = body.get("error")
            if response.status_code == 401 and error in expected_auth:
                response.success()
                return response, body, "auth", started

            valid = response.status_code in statuses
            if valid and check is not None:
                try:
                    valid = bool(check(response, body))
                except (KeyError, TypeError, ValueError, AttributeError):
                    valid = False

            if not valid:
                response.failure("unexpected status or invalid response")
                return response, body, "failed", started

            response.success()
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return response, body, "ok", started

    def login(self):
        self.csrf = ""
        response, _, result, _ = self.raw(
            "/v2/login-form",
            check=lambda r, b: bool(form_token(r.text)),
        )
        if result != "ok":
            raise JourneyError()
        token = form_token(response.text)

        def login_check(response, body):
            if response.status_code == 302:
                return bool(same_origin_location(response))
            return bool(body.get("csrf") and body.get("user"))

        response, _, result, _ = self.raw(
            "/v2/login",
            "POST",
            {"username": self.username, "password": "bench", "csrf": token},
            statuses=(200, 302),
            check=login_check,
        )
        if result != "ok":
            raise JourneyError()
        if response.status_code == 302:
            location = same_origin_location(response)
            _, _, result, _ = self.raw(
                location,
                check=lambda r, b: bool(b.get("csrf") and b.get("user")),
            )
            if result != "ok":
                raise JourneyError()

    def recover(self, reason):
        if reason == "session":
            self.client.cookies.clear()
            self.login()
        else:
            _, body, result, _ = self.raw(
                "/v2/session/renew",
                "POST",
                {},
                expected_auth=("session",),
            )
            if result == "auth" and body.get("error") == "session":
                self.client.cookies.clear()
                self.login()
            elif result != "ok":
                raise JourneyError()

        if self.cart:
            response, _, result, _ = self.raw(
                "/v2/carts/" + quote(str(self.cart), safe="") + "/recover",
                "POST",
                {},
            )
            if result != "ok":
                raise JourneyError()
            self.etag = response.headers.get("ETag", self.etag)

    def request(self, path, method="GET", data=None, headers=None,
                statuses=(200,), check=None, name=None):
        response, body, result, started = self.raw(
            path, method, data, headers, statuses, check,
            expected_auth=("expired", "session"), name=name,
        )
        if result == "auth":
            self.recover(body["error"])
            retry_headers = dict(headers or {})
            if "If-Match" in retry_headers:
                retry_headers["If-Match"] = self.etag
            response, body, result, started = self.raw(
                path, method, data, retry_headers, statuses, check, name=name,
            )
        if result != "ok":
            raise JourneyError()
        return response, body, started

    @staticmethod
    def selected_product(body):
        products = body.get("data", {}).get("products", [])
        for product in products:
            if not product.get("id"):
                continue
            for variant in product.get("variants", []):
                if variant.get("id") and variant.get("in_stock"):
                    return product["id"], variant["id"]
        return None

    def journey(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.login()

        _, catalog, _ = self.request(
            "/v2/catalog",
            check=lambda r, b: bool(self.selected_product(b)),
        )
        product_id, variant_id = self.selected_product(catalog)

        response, body, _ = self.request(
            "/v2/carts",
            "POST",
            {"product_id": product_id, "variant_id": variant_id},
            statuses=(201,),
            check=lambda r, b: bool(b.get("id") and r.headers.get("ETag")),
        )
        self.cart = body["id"]
        self.etag = response.headers["ETag"]

        _, _, started = self.request(
            "/v2/orders",
            "POST",
            {"cart_id": self.cart},
            headers={
                "Idempotency-Key": str(uuid.uuid4()),
                "If-Match": self.etag,
            },
            statuses=(201,),
            check=lambda r, b: b.get("accepted") is True and bool(b.get("id")),
        )
        PLAN.committed(started)

    @task
    def run_journey(self):
        # One arrival wait per business iteration, never per HTTP request.
        if not PLAN.next():
            raise StopUser()
        try:
            self.journey()
        except JourneyError:
            pass


class ShopShape(LoadTestShape):
    def tick(self):
        first_checkout = PLAN.first_checkout
        if first_checkout is not None:
            if time.monotonic() >= first_checkout + 36:
                return None
        elif self.get_run_time() >= 45:
            return None
        return MAX_VUS, MAX_VUS
