import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static JsonNode parse(String body) {
        try {
            return JSON.readTree(body);
        } catch (Exception error) {
            return null;
        }
    }

    private static boolean validLogin(Session session) {
        int status = session.getInt("loginStatus");
        if (status == 302) {
            return session.contains("loginLocation")
                && !session.getString("loginLocation").isEmpty();
        }
        if (status == 200) {
            JsonNode body = parse(session.getString("loginBody"));
            return body != null && body.path("csrf").isTextual()
                && !body.path("csrf").asText().isEmpty();
        }
        return false;
    }

    private static boolean validWork(Session session) {
        int status = session.getInt("workStatus");
        if (status == 429) {
            if (!session.contains("retryAfter")) return false;
            try {
                return Double.parseDouble(session.getString("retryAfter").trim()) == 1.0;
            } catch (RuntimeException error) {
                return false;
            }
        }

        JsonNode body = parse(session.getString("workBody"));
        if (body == null) return false;
        if (status == 200) {
            return body.path("ok").isBoolean() && body.path("ok").asBoolean();
        }
        if (status == 401) {
            return "expired".equals(body.path("error").asText());
        }
        return false;
    }

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(session -> session
                .set("csrf", "")
                .set("loginStatus", 0)
                .remove("formCsrf")
                .remove("loginBody")
                .remove("loginLocation"))
            .exec(http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name=csrf]", "value").saveAs("formCsrf")
                ))
            .exec(http("login")
                .post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session ->
                    "{\"username\":\"bench-" +
                    (((session.userId() - 1) % 16) + 1) +
                    "\",\"password\":\"bench\",\"csrf\":\"" +
                    session.getString("formCsrf") + "\"}"))
                .check(
                    status().saveAs("loginStatus"),
                    status().in(200, 302),
                    header("Location").optional().saveAs("loginLocation"),
                    bodyString().saveAs("loginBody"),
                    bodyString().is(session ->
                        validLogin(session) ? session.getString("loginBody") : "\u0000")
                ))
            .exec(session -> {
                if (session.getInt("loginStatus") == 200 && session.contains("loginBody")) {
                    JsonNode body = parse(session.getString("loginBody"));
                    if (body != null && body.path("csrf").isTextual()) {
                        return session.set("csrf", body.path("csrf").asText());
                    }
                }
                return session;
            })
            .exec(doIf(session ->
                session.getInt("loginStatus") == 302 && session.contains("loginLocation")
            ).then(
                exec(http("login redirect")
                    .get("#{loginLocation}")
                    .disableFollowRedirect()
                    .check(
                        status().is(200),
                        jsonPath("$.csrf").saveAs("csrf")
                    ))
            ));
    }

    private static ChainBuilder workResponse() {
        return exec(session -> session
                .set("workStatus", 0)
                .set("workError", "")
                .remove("workBody")
                .remove("retryAfter"))
            .exec(http("work")
                .post("/v2/work")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().saveAs("workStatus"),
                    status().in(200, 401, 429),
                    header("Retry-After").optional().saveAs("retryAfter"),
                    bodyString().saveAs("workBody"),
                    bodyString().is(session ->
                        validWork(session) ? session.getString("workBody") : "\u0000")
                ))
            .exec(session -> {
                if (!session.contains("workBody")) return session;
                JsonNode body = parse(session.getString("workBody"));
                if (body == null) return session;

                if (session.getInt("workStatus") == 401) {
                    return session.set("workError", body.path("error").asText(""));
                }
                if (session.getInt("workStatus") == 200
                    && body.path("csrf").isTextual()
                    && !body.path("csrf").asText().isEmpty()) {
                    return session.set("csrf", body.path("csrf").asText());
                }
                return session;
            });
    }

    private static ChainBuilder workOperation() {
        return workResponse()
            .exec(doIf(session ->
                session.getInt("workStatus") == 401
                    && "expired".equals(session.getString("workError"))
            ).then(
                exec(session -> session.remove("renewCsrf"))
                    .exec(http("renew")
                        .post("/v2/session/renew")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(
                            status().is(200),
                            jsonPath("$.csrf").saveAs("renewCsrf")
                        ))
                    .exec(doIf(session -> session.contains("renewCsrf")).then(
                        exec(session -> session.set("csrf", session.getString("renewCsrf")))
                            .exec(workResponse())
                    ))
            ));
    }

    public ModelSimulation() {
        setUp(
            scenario("errors")
                .exec(repeat(2).on(
                    login()
                        .exec(repeat(4).on(workOperation()))
                ))
                .injectOpen(atOnceUsers(2))
        )
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

