import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
    business_failure: ['rate==0'],
  },
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const failure = new Rate('business_failure');
let csrf = '';

function url(path) {
  if (/^https?:\/\//i.test(path)) {
    if (path !== base && !path.startsWith(base + '/') && !path.startsWith(base + '?')) {
      throw new Error('Unexpected redirect origin');
    }
    return path;
  }
  return base + (path.startsWith('/') ? path : '/' + path);
}

function body(response) {
  try {
    return response.json() || {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return '';
}

function send(path, method = 'GET', data = null) {
  const response = http.request(
    method,
    url(path),
    data === null ? null : JSON.stringify(data),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
      redirects: 0,
      timeout: '3s',
    }
  );
  const result = body(response);
  if (result.csrf) csrf = result.csrf;
  return response;
}

function login() {
  const form = send('/v2/login-form');
  let token;
  if (form.status === 200) {
    token = form.html().find('input[name="csrf"]').first().attr('value');
  }
  if (!token) {
    check(form, { login: () => false });
    return false;
  }

  let response = send('/v2/login', 'POST', {
    username: `bench-${((__VU - 1) % 16) + 1}`,
    password: 'bench',
    csrf: token,
  });
  if (response.status === 302) {
    const location = header(response, 'Location');
    if (!location) {
      check(response, { login: () => false });
      return false;
    }
    response = send(location);
  }
  return check(response, {
    login: (r) => r.status === 200 && !!csrf,
  });
}

function scheduledThrottle(response) {
  return response.status === 429 && Number(header(response, 'Retry-After')) === 1;
}

function expectedWorkResponse(response) {
  const result = body(response);
  return (response.status === 200 && result.ok === true) ||
    (response.status === 401 && result.error === 'expired') ||
    scheduledThrottle(response);
}

function work() {
  let recovered = false;
  let retries = 0;
  let unexpected = false;
  let response;

  while (true) {
    response = send('/v2/work', 'POST', {});
    const expected = expectedWorkResponse(response);
    failure.add(!expected);
    if (!expected) unexpected = true;

    const error = body(response).error;
    if (response.status === 401 &&
        (error === 'expired' || error === 'session') &&
        !recovered) {
      recovered = true;
      const renewal = send('/v2/session/renew', 'POST', {});
      if (renewal.status !== 200 || !body(renewal).csrf) {
        if (error !== 'session' || !login()) break;
      }
      continue;
    }

    if (scheduledThrottle(response) && retries < 4) {
      retries++;
      sleep(1.01);
      continue;
    }
    break;
  }

  check(response, {
    'work completed without unexpected errors': (r) =>
      !unexpected && r.status === 200 && body(r).ok === true,
  });
}

export default function () {
  csrf = '';
  if (!login()) return;
  for (let i = 0; i < 4; i++) work();
}

