import os
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from gevent import sleep
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

USERS = 2
ITERATIONS = 2
assigned = 0
finished = 0


class CSRFParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.token = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input" or self.token is not None:
            return
        attributes = dict(attrs)
        if attributes.get("name") == "csrf" and attributes.get("value"):
            self.token = attributes["value"]


def json_object(response):
    try:
        body = response.json()
    except (ValueError, TypeError):
        return {}
    return body if isinstance(body, dict) else {}


class WorkUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = lambda self: 0

    def on_start(self):
        global assigned
        assigned += 1
        self.username = "bench-" + str(assigned)
        self.csrf = ""
        self.iteration = 0

    def fail(self, response, message):
        response.failure(message)
        self.environment.process_exit_code = 1

    def headers(self):
        return {"X-CSRF-Token": self.csrf} if self.csrf else {}

    def login(self):
        self.client.cookies.clear()
        self.csrf = ""

        with self.client.get(
            "/v2/login-form", catch_response=True, allow_redirects=False, timeout=3
        ) as response:
            if response.status_code != 200:
                self.fail(response, "login form failed")
                return False
            parser = CSRFParser()
            try:
                parser.feed(response.text)
            except Exception:
                self.fail(response, "invalid login form")
                return False
            if not parser.token:
                self.fail(response, "login form has no CSRF token")
                return False
            response.success()
            token = parser.token

        location = None
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": token},
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            body = json_object(response)
            if response.status_code == 200:
                if not body.get("csrf"):
                    self.fail(response, "login did not supply CSRF")
                    return False
                self.csrf = body["csrf"]
                response.success()
            elif response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    self.fail(response, "login redirect has no Location")
                    return False
                target = urlsplit(urljoin(self.host, location))
                origin = urlsplit(self.host)
                if (target.scheme, target.netloc) != (origin.scheme, origin.netloc):
                    self.fail(response, "login redirect leaves target host")
                    return False
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                response.success()
            else:
                self.fail(response, "login failed")
                return False

        if location:
            with self.client.get(
                location, catch_response=True, allow_redirects=False, timeout=3
            ) as response:
                body = json_object(response)
                if response.status_code != 200:
                    self.fail(response, "login redirect failed")
                    return False
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                if not self.csrf:
                    self.fail(response, "login redirect did not supply CSRF")
                    return False
                response.success()
        return True

    def renew(self, revoked=False):
        fallback = False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self.headers(),
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            body = json_object(response)
            if response.status_code == 200:
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                response.success()
            elif (
                revoked
                and response.status_code == 401
                and body.get("error") in ("session", "expired")
            ):
                response.success()
                fallback = True
            else:
                self.fail(response, "session renewal failed")
                return False
        return self.login() if fallback else True

    def work(self):
        expiry_recovered = False
        rate_retries = 0

        while True:
            action = None
            delay = None
            with self.client.post(
                "/v2/work",
                json={},
                headers=self.headers(),
                catch_response=True,
                allow_redirects=False,
                timeout=3,
            ) as response:
                body = json_object(response)
                if response.status_code == 200 and body.get("ok") is True:
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
                    response.success()
                    return True

                if (
                    response.status_code == 401
                    and body.get("error") in ("expired", "session")
                    and not expiry_recovered
                ):
                    expiry_recovered = True
                    action = body["error"]
                    response.success()
                elif response.status_code == 429 and rate_retries < 4:
                    try:
                        delay = float(response.headers.get("Retry-After", ""))
                    except ValueError:
                        delay = None
                    if delay != 1.0:
                        self.fail(response, "invalid Retry-After")
                        return False
                    rate_retries += 1
                    action = "retry"
                    response.success()
                else:
                    self.fail(response, "unexpected work response")
                    return False

            if action == "retry":
                sleep(delay)
            elif not self.renew(revoked=(action == "session")):
                return False

    @task
    def run_iteration(self):
        global finished
        if self.login():
            for _ in range(4):
                self.work()

        self.iteration += 1
        if self.iteration >= ITERATIONS:
            finished += 1
            raise StopUser()


class WorkShape(LoadTestShape):
    def tick(self):
        if finished >= USERS:
            return None
        if self.get_run_time() > 180:
            self.runner.environment.process_exit_code = 1
            return None
        return USERS - finished, USERS
