import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final String BASE_URL =
      System.getenv("BASE_URL") == null || System.getenv("BASE_URL").isBlank()
          ? "http://127.0.0.1:8000"
          : System.getenv("BASE_URL");

  private static final String CSRF_REGEX =
      "\"csrf\"\\s*:\\s*\"([^\"]+)\"";
  private static final String ERROR_REGEX =
      "\"error\"\\s*:\\s*\"([^\"]+)\"";

  private static final Pattern CSRF = Pattern.compile(CSRF_REGEX);
  private static final Pattern OK =
      Pattern.compile("\"ok\"\\s*:\\s*true\\b");
  private static final Pattern RECOVERABLE_ERROR =
      Pattern.compile("\"error\"\\s*:\\s*\"(?:expired|session)\"");
  private static final Pattern SESSION_ERROR =
      Pattern.compile("\"error\"\\s*:\\s*\"session\"");

  private static boolean validLogin(String body, Session session) {
    int status = session.getInt("loginStatus");
    if (status == 200) {
      return CSRF.matcher(body).find();
    }
    return status == 302 && session.contains("loginLocation");
  }

  private static boolean validRenew(String body, Session session) {
    int status = session.getInt("renewStatus");
    if (status == 200) {
      return CSRF.matcher(body).find();
    }
    return status == 401 && SESSION_ERROR.matcher(body).find();
  }

  private static boolean validWork(String body, Session session) {
    int status = session.getInt("workStatus");
    if (status == 200) {
      return OK.matcher(body).find();
    }
    if (status == 401) {
      return session.getInt("workRecoveries") < 1
          && RECOVERABLE_ERROR.matcher(body).find();
    }
    if (status == 429) {
      return session.getInt("work429Retries") < 4
          && session.contains("retryAfter")
          && "1".equals(session.getString("retryAfter"));
    }
    return false;
  }

  private static ChainBuilder login() {
    return exec(session ->
            session.removeAll(
                "loginStatus", "loginLocation", "loginCsrf", "redirectCsrf"))
        .exec(
            http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name='csrf']", "value").saveAs("csrf")))
        .exitHereIfFailed()
        .exec(
            http("login")
                .post("/v2/login")
                .body(StringBody(
                    "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                .check(
                    status().in(200, 302).saveAs("loginStatus"),
                    header("Location").optional().saveAs("loginLocation"),
                    bodyString()
                        .transformWithSession(ModelSimulation::validLogin)
                        .is(true),
                    regex(CSRF_REGEX).optional().saveAs("loginCsrf")))
        .exitHereIfFailed()
        .exec(session ->
            session.contains("loginCsrf")
                ? session.set("csrf", session.getString("loginCsrf"))
                : session)
        .doIf(session -> session.getInt("loginStatus") == 302)
        .then(
            exec(
                http("login redirect")
                    .get("#{loginLocation}")
                    .check(
                        status().is(200),
                        regex(CSRF_REGEX).optional().saveAs("redirectCsrf")))
                .exitHereIfFailed()
                .exec(session ->
                    session.contains("redirectCsrf")
                        ? session.set("csrf", session.getString("redirectCsrf"))
                        : session));
  }

  private static ChainBuilder renew() {
    return exec(session -> session.removeAll("renewStatus", "renewCsrf"))
        .exec(
            http("session renew")
                .post("/v2/session/renew")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().in(200, 401).saveAs("renewStatus"),
                    bodyString()
                        .transformWithSession(ModelSimulation::validRenew)
                        .is(true),
                    regex(CSRF_REGEX).optional().saveAs("renewCsrf")))
        .exitHereIfFailed()
        .doIf(session -> session.getInt("renewStatus") == 200)
        .then(exec(session -> session.set("csrf", session.getString("renewCsrf"))))
        .doIf(session -> session.getInt("renewStatus") == 401)
        .then(login());
  }

  private static ChainBuilder work() {
    return exec(session ->
            session.set("workRecoveries", 0)
                .set("work429Retries", 0)
                .set("workRetry", false))
        .doWhile(session -> session.getBoolean("workRetry"))
        .on(
            exec(session ->
                session.removeAll(
                        "workStatus", "workError", "nextWorkCsrf", "retryAfter")
                    .set("workRetry", false))
                .exec(
                    http("work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(
                            status().in(200, 401, 429).saveAs("workStatus"),
                            header("Retry-After").optional().saveAs("retryAfter"),
                            bodyString()
                                .transformWithSession(ModelSimulation::validWork)
                                .is(true),
                            regex(ERROR_REGEX).optional().saveAs("workError"),
                            regex(CSRF_REGEX).optional().saveAs("nextWorkCsrf")))
                .exitHereIfFailed()
                .doIf(session ->
                    session.getInt("workStatus") == 200
                        && session.contains("nextWorkCsrf"))
                .then(exec(session ->
                    session.set("csrf", session.getString("nextWorkCsrf"))))
                .doIf(session -> session.getInt("workStatus") == 401)
                .then(
                    exec(session ->
                        session.set(
                            "workRecoveries",
                            session.getInt("workRecoveries") + 1))
                        .doIf(session -> "expired".equals(session.getString("workError")))
                        .then(renew())
                        .doIf(session -> "session".equals(session.getString("workError")))
                        .then(login())
                        .exec(session -> session.set("workRetry", true)))
                .doIf(session -> session.getInt("workStatus") == 429)
                .then(
                    exec(session ->
                        session.set(
                                "work429Retries",
                                session.getInt("work429Retries") + 1)
                            .set("workRetry", true))
                        .pause(Duration.ofSeconds(1))));
  }

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(BASE_URL)
          .acceptHeader("application/json, text/html;q=0.9, */*;q=0.1")
          .contentTypeHeader("application/json")
          .disableFollowRedirect();

  private final Iterator<Map<String, Object>> users =
      List.of(
              Map.<String, Object>of("username", "bench-1"),
              Map.<String, Object>of("username", "bench-2"),
              Map.<String, Object>of("username", "bench-3"),
              Map.<String, Object>of("username", "bench-4"),
              Map.<String, Object>of("username", "bench-5"))
          .iterator();

  private final ScenarioBuilder scenario =
      scenario("authenticated work")
          .feed(users)
          .exec(login())
          .during(Duration.ofSeconds(36))
          .on(
              pace(Duration.ofMillis(950)),
              work());

  {
    setUp(
        scenario.injectOpen(
            rampUsers(5).during(Duration.ofSeconds(1))))
        .protocols(httpProtocol);
  }
}
