import http from 'k6/http';
import { check, sleep } from 'k6';
import { parseHTML } from 'k6/html';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (BASE !== 'http://127.0.0.1:8000') {
  throw new Error('BASE_URL must be http://127.0.0.1:8000');
}

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '35s',
      preAllocatedVUs: 16,
      maxVUs: 16,
      gracefulStop: '5s',
    },
  },
};

function json(response) {
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return null;
}

function csrfFromForm(response) {
  try {
    return parseHTML(response.body)
      .find('input[name="csrf"]')
      .first()
      .attr('value');
  } catch (_) {
    return null;
  }
}

function rememberCsrf(ctx, response) {
  const body = json(response);
  if (body && typeof body.csrf === 'string' && body.csrf) {
    ctx.csrf = body.csrf;
  }
  return body;
}

function params(ctx, authenticated = false) {
  const headers = { 'Content-Type': 'application/json' };
  if (authenticated && ctx.csrf) headers['X-CSRF-Token'] = ctx.csrf;
  return { jar: ctx.jar, headers, redirects: 0 };
}

function redirectUrl(location, requestPath) {
  if (!location) throw new Error('Login redirect has no Location');
  if (location.startsWith(BASE + '/')) return location;
  if (/^https?:\/\//i.test(location) || location.startsWith('//')) {
    throw new Error('Login redirect points outside the target');
  }
  if (location.startsWith('/')) return BASE + location;
  if (location.startsWith('?')) return BASE + requestPath + location;
  const parent = requestPath.slice(0, requestPath.lastIndexOf('/') + 1);
  return BASE + parent + location;
}

function finishLogin(ctx, response) {
  rememberCsrf(ctx, response);

  if (response.status === 302) {
    const location = header(response, 'Location');
    const url = redirectUrl(location, '/v2/login');
    response = http.get(url, { jar: ctx.jar, redirects: 0 });
    rememberCsrf(ctx, response);
  }

  const ok = response.status >= 200 && response.status < 300 && !!ctx.csrf;
  check(response, {
    'login completed with CSRF token': () => ok,
  });
  return ok;
}

function freshLogin(ctx) {
  const form = http.get(BASE + '/v2/login-form', {
    jar: ctx.jar,
    redirects: 0,
  });
  const csrf = csrfFromForm(form);
  const formOK = form.status === 200 && !!csrf;
  check(form, { 'login form contains CSRF token': () => formOK });
  if (!formOK) return false;

  ctx.csrf = null;
  const response = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: ctx.username, password: 'bench', csrf }),
    params(ctx)
  );
  return finishLogin(ctx, response);
}

export function setup() {
  const contexts = [];
  const forms = [];

  for (let i = 1; i <= 16; i++) {
    const ctx = {
      username: `bench-${i}`,
      csrf: null,
      jar: new http.CookieJar(),
    };
    contexts.push(ctx);
    forms.push({
      method: 'GET',
      url: BASE + '/v2/login-form',
      params: { jar: ctx.jar, redirects: 0 },
    });
  }

  const formResponses = http.batch(forms);
  const logins = [];

  for (let i = 0; i < contexts.length; i++) {
    const response = formResponses[i];
    const csrf = csrfFromForm(response);
    const ok = response.status === 200 && !!csrf;
    check(response, { 'login form contains CSRF token': () => ok });
    if (!ok) throw new Error(`Login form failed for ${contexts[i].username}`);

    logins.push({
      method: 'POST',
      url: BASE + '/v2/login',
      body: JSON.stringify({
        username: contexts[i].username,
        password: 'bench',
        csrf,
      }),
      params: params(contexts[i]),
    });
  }

  const loginResponses = http.batch(logins);
  const sessions = [];

  for (let i = 0; i < contexts.length; i++) {
    const ctx = contexts[i];
    if (!finishLogin(ctx, loginResponses[i])) {
      throw new Error(`Login failed for ${ctx.username}`);
    }
    sessions.push({
      username: ctx.username,
      csrf: ctx.csrf,
      cookies: ctx.jar.cookiesForURL(BASE + '/v2/work'),
    });
  }

  return { sessions };
}

let context = null;

function getContext(data) {
  if (context) return context;

  const session = data.sessions[__VU - 1];
  if (!session) throw new Error('No session for VU');

  const jar = new http.CookieJar();
  for (const name in session.cookies) {
    for (const value of session.cookies[name]) {
      jar.set(BASE + '/v2/work', name, value, { path: '/' });
    }
  }

  context = { username: session.username, csrf: session.csrf, jar };
  return context;
}

function renew(ctx) {
  const response = http.post(
    BASE + '/v2/session/renew',
    '{}',
    params(ctx, true)
  );
  rememberCsrf(ctx, response);
  const ok = response.status >= 200 && response.status < 300 && !!ctx.csrf;
  check(response, { 'session renewal succeeded': () => ok });
  return ok;
}

export default function (data) {
  const ctx = getContext(data);
  let authRecoveryUsed = false;
  let rateLimitRetries = 0;

  while (true) {
    const response = http.post(BASE + '/v2/work', '{}', params(ctx, true));
    const body = rememberCsrf(ctx, response);
    const success = response.status === 200 && body && body.ok === true;
    const expired = response.status === 401 && body && body.error === 'expired';
    const revoked = response.status === 401 && body && body.error === 'session';
    const retryAfter = Number(header(response, 'Retry-After'));
    const scheduled429 = response.status === 429 && retryAfter >= 1;

    businessFailure.add(!success && !expired && !scheduled429);
    check(response, { 'work response succeeded': () => !!success });

    if (success) return;

    if (scheduled429 && rateLimitRetries < 4) {
      rateLimitRetries++;
      sleep(retryAfter);
      continue;
    }

    if (!authRecoveryUsed && (expired || revoked)) {
      authRecoveryUsed = true;
      const recovered = expired ? renew(ctx) : freshLogin(ctx);
      if (recovered) continue;
    }

    return;
  }
}
