import os
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

import gevent
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"].rstrip("/")
if BASE_URL != "http://127.0.0.1:8000":
    raise ValueError("BASE_URL must be http://127.0.0.1:8000")

RATE = 5
DURATION = 35
TOTAL_STARTS = RATE * DURATION

_epoch = None
_next_slot = 0
_account_number = 0
_inflight = 0


def json_object(response):
    try:
        value = response.json()
    except (ValueError, TypeError):
        return {}
    return value if isinstance(value, dict) else {}


def csrf_from(value):
    token = value.get("csrf")
    return token if isinstance(token, str) and token else None


class CSRFParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.token = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input" or self.token is not None:
            return
        attributes = dict(attrs)
        if attributes.get("name") == "csrf":
            value = attributes.get("value")
            if value:
                self.token = value

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def safe_location(location, origin_path):
    if not location:
        return None
    absolute = urljoin(BASE_URL + origin_path, location)
    parsed = urlsplit(absolute)
    if (
        parsed.scheme != "http"
        or parsed.hostname != "127.0.0.1"
        or parsed.port != 8000
        or parsed.username is not None
        or parsed.password is not None
    ):
        return None
    return absolute


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        global _account_number
        self.username = "bench-{}".format((_account_number % 16) + 1)
        _account_number += 1
        self.csrf = None
        if not self.login():
            raise StopUser()

    def login(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            if response.status_code != 200:
                response.failure("login form did not return 200")
                return False
            parser = CSRFParser()
            try:
                parser.feed(response.text)
            except Exception:
                response.failure("could not parse login form")
                return False
            form_csrf = parser.token
            if not form_csrf:
                response.failure("login form has no CSRF input")
                return False

        redirect_url = None
        token = None
        with self.client.post(
            "/v2/login",
            name="/v2/login",
            json={
                "username": self.username,
                "password": "bench",
                "csrf": form_csrf,
            },
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            body = json_object(response)
            token = csrf_from(body)
            if response.status_code == 302:
                try:
                    redirect_url = safe_location(
                        response.headers.get("Location"), "/v2/login"
                    )
                except ValueError:
                    redirect_url = None
                if not redirect_url:
                    response.failure("invalid login redirect")
                    return False
            elif response.status_code == 200:
                if not token:
                    response.failure("login response has no CSRF token")
                    return False
            else:
                response.failure("login failed")
                return False

        if redirect_url:
            with self.client.get(
                redirect_url,
                name="/v2/login redirect",
                catch_response=True,
                allow_redirects=False,
                timeout=3,
            ) as response:
                if response.status_code != 200:
                    response.failure("login redirect did not return 200")
                    return False
                token = csrf_from(json_object(response)) or token
                if not token:
                    response.failure("login redirect has no CSRF token")
                    return False

        self.csrf = token
        return True

    def renew(self):
        with self.client.post(
            "/v2/session/renew",
            name="/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            body = json_object(response)
            if response.status_code == 200:
                token = csrf_from(body)
                if not token:
                    response.failure("renewal has no CSRF token")
                    return False
                self.csrf = token
                return True
            if response.status_code == 401 and body.get("error") == "session":
                response.success()
                return self.login()
            response.failure("session renewal failed")
            return False

    def do_work(self):
        recovered = False
        rate_limit_retries = 0

        while True:
            action = None
            delay = None

            with self.client.post(
                "/v2/work",
                name="/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                allow_redirects=False,
                timeout=3,
            ) as response:
                body = json_object(response)
                status = response.status_code

                if status == 200 and body.get("ok") is True:
                    self.csrf = csrf_from(body) or self.csrf
                    return

                if status == 401:
                    error = body.get("error")
                    if error in ("expired", "session") and not recovered:
                        response.success()
                        recovered = True
                        action = error
                    else:
                        response.failure("unexpected or repeated work authentication failure")
                        return

                elif status == 429:
                    try:
                        delay = float(response.headers.get("Retry-After", ""))
                    except (TypeError, ValueError):
                        delay = None
                    if (
                        delay is None
                        or not 1 <= delay <= 60
                        or rate_limit_retries >= 4
                    ):
                        response.failure("invalid or exhausted work rate-limit retry")
                        return
                    response.success()
                    rate_limit_retries += 1
                    action = "retry"

                else:
                    response.failure("unexpected work response or business failure")
                    return

            if action == "expired":
                if not self.renew():
                    return
            elif action == "session":
                if not self.login():
                    return
            elif action == "retry":
                gevent.sleep(delay)

    @task
    def scheduled_work(self):
        global _epoch, _next_slot, _inflight

        if _epoch is None:
            _epoch = time.monotonic()

        slot = _next_slot
        _next_slot += 1

        if slot >= TOTAL_STARTS:
            gevent.sleep(max(0, _epoch + 40 - time.monotonic()))
            raise StopUser()

        due = _epoch + slot / RATE
        gevent.sleep(max(0, due - time.monotonic()))

        if time.monotonic() >= _epoch + DURATION:
            gevent.sleep(max(0, _epoch + 40 - time.monotonic()))
            raise StopUser()

        _inflight += 1
        try:
            self.do_work()
        finally:
            _inflight -= 1


class WorkShape(LoadTestShape):
    def tick(self):
        if _epoch is None:
            if self.get_run_time() >= 9:
                return None
            return (16, 100)

        elapsed = time.monotonic() - _epoch
        if elapsed >= 39 or (elapsed >= DURATION and _inflight == 0):
            return None
        return (16, 100)
