import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final Pattern OK_TRUE =
      Pattern.compile("\"ok\"\\s*:\\s*true\\s*[,}]");

  private static String jsonString(String body, String key) {
    if (body == null) {
      return null;
    }

    Pattern pattern = Pattern.compile(
        "\"" + Pattern.quote(key) + "\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\""
    );
    Matcher matcher = pattern.matcher(body);
    if (!matcher.find()) {
      return null;
    }

    String encoded = matcher.group(1);
    StringBuilder decoded = new StringBuilder();
    for (int i = 0; i < encoded.length(); i++) {
      char c = encoded.charAt(i);
      if (c != '\\') {
        decoded.append(c);
        continue;
      }
      if (++i >= encoded.length()) {
        return null;
      }
      char escaped = encoded.charAt(i);
      switch (escaped) {
        case '"': decoded.append('"'); break;
        case '\\': decoded.append('\\'); break;
        case '/': decoded.append('/'); break;
        case 'b': decoded.append('\b'); break;
        case 'f': decoded.append('\f'); break;
        case 'n': decoded.append('\n'); break;
        case 'r': decoded.append('\r'); break;
        case 't': decoded.append('\t'); break;
        case 'u':
          if (i + 4 >= encoded.length()) {
            return null;
          }
          try {
            decoded.append((char) Integer.parseInt(encoded.substring(i + 1, i + 5), 16));
          } catch (NumberFormatException e) {
            return null;
          }
          i += 4;
          break;
        default:
          return null;
      }
    }
    return decoded.toString();
  }

  private static boolean hasString(String value) {
    return value != null && !value.isEmpty();
  }

  public ModelSimulation() {
    String baseUrl = System.getenv("BASE_URL");
    if (baseUrl == null || baseUrl.isEmpty()) {
      baseUrl = "http://127.0.0.1:8000";
    }

    HttpProtocolBuilder httpProtocol = http
        .baseUrl(baseUrl)
        .disableFollowRedirect();

    ChainBuilder login =
        exec(
            http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name='csrf']", "value").saveAs("formCsrf")
                )
        )
        .exitHereIfFailed()
        .exec(session -> session
            .set("loginBody", "")
            .set("loginLocation", ""))
        .exec(
            http("login")
                .post("/v2/login")
                .asJson()
                .body(StringBody(
                    "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{formCsrf}\"}"
                ))
                .check(
                    status().saveAs("loginStatus"),
                    bodyString().optional().saveAs("loginBody"),
                    header("Location").optional().saveAs("loginLocation"),
                    status().is(session -> {
                      int code = session.getInt("loginStatus");
                      if (code == 200 &&
                          hasString(jsonString(session.getString("loginBody"), "csrf"))) {
                        return 200;
                      }
                      if (code == 302 && hasString(session.getString("loginLocation"))) {
                        return 302;
                      }
                      return -1;
                    })
                )
        )
        .exitHereIfFailed()
        .doIf(session -> session.getInt("loginStatus") == 200)
        .then(
            exec(session ->
                session.set("csrf", jsonString(session.getString("loginBody"), "csrf")))
        )
        .doIf(session -> session.getInt("loginStatus") == 302)
        .then(
            exec(
                http("login redirect")
                    .get("#{loginLocation}")
                    .check(
                        status().is(200),
                        jsonPath("$.csrf").saveAs("csrf")
                    )
            )
        )
        .exitHereIfFailed();

    ChainBuilder renew =
        exec(session -> session.set("renewBody", ""))
        .exec(
            http("session renew")
                .post("/v2/session/renew")
                .header("X-CSRF-Token", "#{csrf}")
                .asJson()
                .body(StringBody("{}"))
                .check(
                    status().saveAs("renewStatus"),
                    bodyString().optional().saveAs("renewBody"),
                    status().is(session -> {
                      int code = session.getInt("renewStatus");
                      String body = session.getString("renewBody");
                      if (code == 200 && hasString(jsonString(body, "csrf"))) {
                        return 200;
                      }
                      if (code == 401 && "session".equals(jsonString(body, "error"))) {
                        return 401;
                      }
                      return -1;
                    })
                )
        )
        .exitHereIfFailed()
        .doIf(session -> session.getInt("renewStatus") == 200)
        .then(
            exec(session ->
                session.set("csrf", jsonString(session.getString("renewBody"), "csrf")))
        )
        .doIf(session -> session.getInt("renewStatus") == 401)
        .then(login)
        .exitHereIfFailed();

    ChainBuilder workAttempt =
        exec(session -> session
            .set("workBody", "")
            .set("retryAfter", ""))
        .exec(
            http("work")
                .post("/v2/work")
                .header("X-CSRF-Token", "#{csrf}")
                .asJson()
                .body(StringBody("{}"))
                .check(
                    status().saveAs("workStatus"),
                    bodyString().optional().saveAs("workBody"),
                    header("Retry-After").optional().saveAs("retryAfter"),
                    status().is(session -> {
                      int code = session.getInt("workStatus");
                      String body = session.getString("workBody");
                      if (code == 200 && OK_TRUE.matcher(body).find()) {
                        return 200;
                      }
                      if (code == 401 && session.getInt("authRetries") < 1) {
                        String error = jsonString(body, "error");
                        if ("expired".equals(error) || "session".equals(error)) {
                          return 401;
                        }
                      }
                      if (code == 429 &&
                          session.getInt("rateRetries") < 4 &&
                          "1".equals(session.getString("retryAfter").trim())) {
                        return 429;
                      }
                      return -1;
                    })
                )
        )
        .exitHereIfFailed()
        .doIf(session -> session.getInt("workStatus") == 200)
        .then(
            exec(session -> {
              String freshCsrf = jsonString(session.getString("workBody"), "csrf");
              if (hasString(freshCsrf)) {
                session = session.set("csrf", freshCsrf);
              }
              return session.set("done", true);
            })
        )
        .doIf(session -> session.getInt("workStatus") == 429)
        .then(
            exec(session ->
                session.set("rateRetries", session.getInt("rateRetries") + 1))
                .pause(Duration.ofSeconds(1))
        )
        .doIf(session -> session.getInt("workStatus") == 401)
        .then(
            exec(session -> session
                .set("authRetries", session.getInt("authRetries") + 1)
                .set("workError", jsonString(session.getString("workBody"), "error")))
                .doIf(session -> "expired".equals(session.getString("workError")))
                .then(renew)
                .doIf(session -> "session".equals(session.getString("workError")))
                .then(login)
        )
        .exitHereIfFailed();

    ScenarioBuilder scenario =
        scenario("authenticated work")
            .exec(session -> session
                .set("username", "bench-" + (Math.floorMod(session.userId(), 16L) + 1))
                .set("authRetries", 0)
                .set("rateRetries", 0)
                .set("done", false))
            .exec(login)
            .repeat(6)
            .on(
                doIf(session -> !session.getBoolean("done"))
                    .then(workAttempt)
            );

    setUp(
        scenario.injectOpen(
            constantUsersPerSec(5.0).during(Duration.ofSeconds(36))
        )
    )
        .protocols(httpProtocol)
        .maxDuration(Duration.ofSeconds(41));
  }
}
