import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '39s',
      preAllocatedVUs: 16,
      maxVUs: 16,
      gracefulStop: '5s',
    },
  },
  noCookiesReset: true,
  maxRedirects: 0,
  thresholds: {
    checks: ['rate==1'],
    business_failure: ['rate<=0.01'],
    dropped_iterations: ['count<=1'],
  },
};

let csrf = null;
let authenticated = false;

function parseJson(response) {
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return response.headers[key];
  }
  return null;
}

function resolveLocation(location, requestUrl) {
  if (!location) return null;
  if (/^https?:\/\//i.test(location)) {
    if (
      location === BASE ||
      location.indexOf(BASE + '/') === 0 ||
      location.indexOf(BASE + '?') === 0
    ) {
      return location;
    }
    return null;
  }
  if (location.indexOf('//') === 0) return null;
  if (location.charAt(0) === '/') return BASE + location;
  const cleanUrl = requestUrl.split('?')[0].split('#')[0];
  if (location.charAt(0) === '?') return cleanUrl + location;
  return cleanUrl.substring(0, cleanUrl.lastIndexOf('/') + 1) + location;
}

function jsonParams(token) {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers['X-CSRF-Token'] = token;
  return { headers, redirects: 0, timeout: '3s' };
}

function login() {
  authenticated = false;
  csrf = null;

  const form = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    timeout: '3s',
  });

  let formCsrf = null;
  if (form.status === 200) {
    try {
      formCsrf = form.html().find('input[name="csrf"]').first().attr('value');
    } catch (_) {
      formCsrf = null;
    }
  }

  if (!check(form, {
    'login form has a CSRF token': () =>
      form.status === 200 && typeof formCsrf === 'string' && formCsrf.length > 0,
  })) {
    return false;
  }

  const username = `bench-${((__VU - 1) % 16) + 1}`;
  const loginUrl = BASE + '/v2/login';
  let response = http.post(
    loginUrl,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    jsonParams(null)
  );

  if (response.status === 302) {
    const location = resolveLocation(header(response, 'Location'), loginUrl);
    if (!check(location, {
      'login redirect has an allowed Location': (value) => !!value,
    })) {
      return false;
    }
    response = http.get(location, { redirects: 0, timeout: '3s' });
  }

  const body = parseJson(response);
  const valid = response.status === 200 &&
    body !== null &&
    typeof body.csrf === 'string' &&
    body.csrf.length > 0;

  check(response, { 'login establishes a session and CSRF token': () => valid });
  if (!valid) return false;

  csrf = body.csrf;
  authenticated = true;
  return true;
}

function renew() {
  const response = http.post(
    BASE + '/v2/session/renew',
    JSON.stringify({}),
    jsonParams(csrf)
  );
  const body = parseJson(response);
  const renewed = response.status === 200 &&
    body !== null &&
    typeof body.csrf === 'string' &&
    body.csrf.length > 0;
  const revoked = response.status === 401 && body !== null && body.error === 'session';

  check(response, {
    'renewal succeeds or reports a revoked session': () => renewed || revoked,
  });

  if (renewed) {
    csrf = body.csrf;
    authenticated = true;
    return true;
  }
  if (revoked) return login();

  authenticated = false;
  return false;
}

export default function () {
  if (!authenticated && !login()) {
    check(false, { 'work completed successfully': (value) => value });
    return;
  }

  let recovered = false;
  let throttleRetries = 0;
  let completed = false;

  // One authentication recovery and at most four scheduled-429 retries.
  for (let attempt = 0; attempt < 6; attempt++) {
    const response = http.post(
      BASE + '/v2/work',
      JSON.stringify({}),
      jsonParams(csrf)
    );
    const body = parseJson(response);
    const success = response.status === 200 && body !== null && body.ok === true;
    const expired = response.status === 401 && body !== null && body.error === 'expired';
    const revoked = response.status === 401 && body !== null && body.error === 'session';
    const retryAfter = header(response, 'Retry-After');
    const scheduled429 = response.status === 429 &&
      retryAfter !== null &&
      Number(retryAfter) === 1;

    businessFailure.add(!(success || expired || scheduled429));
    check(response, {
      'work response is successful or recoverable': () =>
        success || expired || revoked || scheduled429,
    });

    if (success) {
      if (typeof body.csrf === 'string' && body.csrf.length > 0) csrf = body.csrf;
      completed = true;
      break;
    }

    if ((expired || revoked) && !recovered) {
      recovered = true;
      const restored = expired ? renew() : login();
      if (!restored) break;
      continue;
    }

    if (scheduled429 && throttleRetries < 4) {
      throttleRetries++;
      sleep(1);
      continue;
    }

    if (expired || revoked) authenticated = false;
    break;
  }

  check(completed, { 'work completed successfully': (value) => value });
}

