        if not self.login():
            raise StopUser()

    def login(self):
        with self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            timeout=TIMEOUT,
            catch_response=True,
        ) as response:
            if response.status_code != 200:
                response.failure("Login form did not return HTTP 200")
                return False
            parser = CSRFParser()
            try:
                parser.feed(response.text)
                parser.close()
            except Exception:
                response.failure("Could not parse login form")
                return False
            if not valid_token(parser.token):
                response.failure("Login form has no CSRF token")
                return False
            form_token = parser.token

        location = None
        with self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": "bench",
                "csrf": form_token,
            },
            allow_redirects=False,
            timeout=TIMEOUT,
            catch_response=True,
        ) as response:
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    response.failure("Login redirect has no Location")
                    return False
                target = urlsplit(urljoin(self.host.rstrip("/") + "/", location))
                origin = urlsplit(self.host)
                if (target.scheme, target.netloc) != (origin.scheme, origin.netloc):
                    response.failure("Login redirect leaves the configured host")
                    return False
                response.success()
            elif response.status_code == 200:
                body = json_object(response)
                if not valid_token(body.get("csrf")) or body.get("user") is None:
                    response.failure("Login response lacks csrf or user")
                    return False
                self.csrf = body["csrf"]
                return True
            else:
                response.failure("Login failed")
                return False

        with self.client.get(
            location,
            allow_redirects=False,
            timeout=TIMEOUT,
            catch_response=True,
        ) as response:
            body = json_object(response)
            if (
                response.status_code != 200
                or not valid_token(body.get("csrf"))
                or body.get("user") is None
            ):
                response.failure("Login redirect did not complete login")
                return False
            self.csrf = body["csrf"]
            return True

    def renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            timeout=TIMEOUT,
            catch_response=True,
        ) as response:
            body = json_object(response)
            if response.status_code == 200 and valid_token(body.get("csrf")):
                self.csrf = body["csrf"]
                return True
            if response.status_code == 401 and body.get("error") == "session":
                response.success()
                needs_login = True
            else:
                response.failure("Session renewal failed")
                return False

        return self.login() if needs_login else False

    def do_work(self):
        retries_429 = 0
        recovered = False

        while True:
            action = None
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                allow_redirects=False,
                timeout=TIMEOUT,
                catch_response=True,
            ) as response:
                body = json_object(response)

                if response.status_code == 200:
                    if body.get("ok") is not True:
                        response.failure("Work response did not report ok=true")
                        return
                    token = body.get("csrf")
                    if valid_token(token):
                        self.csrf = token
                    return

                if response.status_code == 401:
                    error = body.get("error")
                    if error in ("expired", "session") and not recovered:
                        response.success()
                        action = error
                    else:
                        response.failure("Work authentication failed")
                        return

                elif response.status_code == 429:
                    try:
                        retry_after = float(response.headers.get("Retry-After", ""))
                    except ValueError:
                        retry_after = -1
                    if retry_after != 1.0:
                        response.failure("429 did not provide Retry-After: 1")
                        return
                    response.success()
                    if retries_429 >= 4:
                        return
                    retries_429 += 1
                    action = "retry"

                else:
                    response.failure(f"Unexpected work status: {response.status_code}")
                    return

            if action == "retry":
                gevent.sleep(1.0)
            elif action == "expired":
                recovered = True
                if not self.renew():
                    return
            elif action == "session":
                recovered = True
                if not self.login():
                    return
            else:
                return

    @task
    def scheduled_work(self):
        global _start, _next_start, _active

        now = time.monotonic()
        if _start is None:
            _start = now
            _next_start = now

        due = max(_next_start, now)
        end = _start + DURATION
        if due >= end:
            gevent.sleep(max(0.0, end + 4.9 - time.monotonic()))
            raise StopUser()

        _next_start = due + 1.0 / RATE
        gevent.sleep(max(0.0, due - time.monotonic()))

        _active += 1
        try:
            self.do_work()
        finally:
            _active -= 1


class WorkShape(LoadTestShape):
    def tick(self):
        if _start is None:
            if self.get_run_time() >= 9.0:
                return None
            return USERS, USERS

        elapsed = time.monotonic() - _start
        if elapsed >= DURATION + 4.0:
            return None
        if elapsed >= DURATION + 0.3 and _active == 0:
            return None
        return USERS, USERS
