  private static final AtomicLong START = new AtomicLong();
  private static final AtomicLong NEXT_BASE = new AtomicLong();
  private static final AtomicLong NEXT_RETRY = new AtomicLong();

  private static Session reserve(Session session) {
    long now = System.nanoTime();
    boolean retry = session.getInt("attempt") > 0;

    if (!retry) {
      START.compareAndSet(0L, now);
    }

    long start = START.get();
    AtomicLong schedule = retry ? NEXT_RETRY : NEXT_BASE;
    long interval = retry ? RETRY_INTERVAL : BASE_INTERVAL;
    long notBefore = retry ? session.getLong("retryNotBefore") : now;
    long limit = start + (retry ? DRAIN_END : RUN_LENGTH);

