      long due = Math.max(Math.max(now, notBefore), previous);

      if (due >= limit) {
        Session stopped = session.set("running", false);
        return retry ? stopped.markAsFailed() : stopped;
      }

      if (schedule.compareAndSet(previous, due + interval)) {
        long delay = Math.max(0L, due - System.nanoTime());
        return session.set("delayNanos", delay);
      }
    }
  }

