                        && "expired".equals(s.getString("workError")))
            .then(renew)
            .doIf(
                s ->
                    s.getInt("workStatus") == 401
                        && "session".equals(s.getString("workError")))
            .then(login));

    ScenarioBuilder scenario =
        scenario("paced work")
            .exec(
                s ->
                    s.set("username", "bench-" + USERS.incrementAndGet())
                        .set("running", true))
            .exec(login)
            .asLongAs(s -> s.getBoolean("running"))
            .on(
                exec(
                    s ->
                        s.set("done", false)
                            .set("attempt", 0)
                            .set("recoveries", 0)
                            .set("throttles", 0)
                            .set("retryNotBefore", 0L))
                .asLongAs(s -> s.getBoolean("running") && !s.getBoolean("done"))
                .on(workAttempt));

    setUp(scenario.injectOpen(atOnceUsers(16))).protocols(protocol);
  }
}

