                        status()
                            .transform(code -> code.toString())
                            .in("200", "#{allowed401}", "#{allowed429}"),
                        status()
                            .transform(code -> code == 429 ? "1" : "absent")
                            .saveAs("expectedRetryAfter"),
                        header("Retry-After")
                            .withDefault("absent")
                            .is("#{expectedRetryAfter}"),
                        bodyString()
                            .transform(ModelSimulation::workBodyStatus)
                            .is("#{workStatus}"),
                        bodyString().saveAs("workBody")))
            .exitHereIfFailed()
            .exec(
                s -> {
                  int status = s.getInt("workStatus");
                  String body = s.getString("workBody");
                  Session next = s.set("attempt", s.getInt("attempt") + 1);

                  if (status == 200) {
                    String csrf = jsonString(CSRF_PATTERN, body);
                    if (csrf != null) {
                      next = next.set("csrf", csrf);
                    }
                    return next.set("done", true);
                  }

                  if (status == 429) {
                    return next
                        .set("throttles", s.getInt("throttles") + 1)
                        .set("retryNotBefore", System.nanoTime() + 1_000_000_000L);
                  }

                  return next
                      .set("workError", jsonString(ERROR_PATTERN, body))
                      .set("recoveries", s.getInt("recoveries") + 1)
                      .set("retryNotBefore", System.nanoTime());
                })
            .doIf(
                s ->
                    s.getInt("workStatus") == 401
                        && "expired".equals(s.getString("workError")))
            .then(renew)
            .doIf(
                s ->
                    s.getInt("workStatus") == 401
                        && "session".equals(s.getString("workError")))
            .then(login));

    ScenarioBuilder scenario =
        scenario("paced work")
            .exec(
                s ->
                    s.set("username", "bench-" + USERS.incrementAndGet())
                        .set("running", true))
            .exec(login)
            .asLongAs(s -> s.getBoolean("running"))
            .on(
                exec(
                    s ->
                        s.set("done", false)
                            .set("attempt", 0)
                            .set("recoveries", 0)
                            .set("throttles", 0)
                            .set("retryNotBefore", 0L))
                .asLongAs(s -> s.getBoolean("running") && !s.getBoolean("done"))
                .on(workAttempt));

    setUp(scenario.injectOpen(atOnceUsers(16))).protocols(protocol);
  }
}

import http from 'k6/http';
import { check, sleep } from 'k6';
import { parseHTML } from 'k6/html';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const businessFailure = new Rate('business_failure');
const workStatuses = http.expectedStatuses(200, 401, 429);
const renewalStatuses = http.expectedStatuses(200, 401);

export const options = {
  scenarios: {
    work: {
      executor: 'per-vu-iterations',
      vus: 16,
      iterations: 1,
      maxDuration: '45s',
      gracefulStop: '5s',
    },
  },
};

export function setup() {
  return { start: Date.now() + 3500 };
}

function json(response) {
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function timeout(deadline) {
  return `${Math.max(1, Math.min(2000, Math.floor(deadline - Date.now())))}ms`;
}

function csrfFrom(response, current) {
  const body = json(response);
  return body && typeof body.csrf === 'string' && body.csrf
    ? body.csrf
    : current;
}

function urlForLocation(location) {
  if (!location) return null;
  if (location.startsWith('/') && !location.startsWith('//')) return BASE + location;
  if (location.startsWith(BASE + '/') || location === BASE) return location;
  return null;
}

function login(username, deadline) {
  if (Date.now() >= deadline) return null;

  const form = http.get(`${BASE}/v2/login-form`, {
    redirects: 0,
    timeout: timeout(deadline),
  });
  let formCsrf = null;
  if (form.status === 200 && form.body) {
    try {
      formCsrf = parseHTML(form.body)
        .find('input[name="csrf"]')
        .first()
        .attr('value');
    } catch (_) {
      formCsrf = null;
    }
  }
  if (!check(form, {
    'login form has CSRF': (r) => r.status === 200 && !!formCsrf,
  })) return null;

  if (Date.now() >= deadline) return null;
  const response = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      timeout: timeout(deadline),
    },
  );
  if (!check(response, {
    'login accepted': (r) => r.status === 200 || r.status === 302,
  })) return null;

  let token = csrfFrom(response, null);
  if (response.status === 302) {
    const location = urlForLocation(response.headers.Location);
    if (!check(location, { 'login redirect is local': (v) => !!v })) return null;
    if (Date.now() >= deadline) return null;
    const landing = http.get(location, {
      redirects: 0,
      timeout: timeout(deadline),
    });
    if (!check(landing, { 'login redirect reached': (r) => r.status === 200 })) {
      return null;
    }
    token = csrfFrom(landing, token);
  }

  return check(token, { 'authenticated CSRF available': (v) => !!v })
    ? token
    : null;
}

function renewOrLogin(username, token, reason, deadline) {
  if (reason === 'session') return login(username, deadline);
  if (Date.now() >= deadline) return null;

  const response = http.post(`${BASE}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': token,
    },
    redirects: 0,
    timeout: timeout(deadline),
    responseCallback: renewalStatuses,
  });
  const body = json(response);
  const revoked = response.status === 401 && body && body.error === 'session';
  if (!check(response, {
    'renewal succeeded or session was revoked': (r) => r.status === 200 || revoked,
  })) return null;
  if (revoked) return login(username, deadline);

  const renewed = csrfFrom(response, token);
  return check(renewed, { 'renewed CSRF available': (v) => !!v })
    ? renewed
    : null;
}

function doWork(username, initialToken, deadline) {
  let token = initialToken;
  let recovered = false;
  let rateRetries = 0;

  while (Date.now() < deadline) {
    const response = http.post(`${BASE}/v2/work`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': token,
      },
      redirects: 0,
      timeout: timeout(deadline),
      responseCallback: workStatuses,
    });
    const body = json(response);
    const success = response.status === 200 && body && body.ok === true;
    const expired = response.status === 401 && body && body.error === 'expired';
    const revoked = response.status === 401 && body && body.error === 'session';
    const retryAfter = Number(response.headers['Retry-After']);
    const throttled = response.status === 429 &&
      Number.isFinite(retryAfter) && retryAfter >= 1;

    businessFailure.add(!(success || expired || throttled));
    check(response, {
      'work response is recognized': () => !!(success || expired || revoked || throttled),
    });

    token = csrfFrom(response, token);
    if (success) return { token, ok: true };

    if ((expired || revoked) && !recovered) {
      recovered = true;
      token = renewOrLogin(username, token, revoked ? 'session' : 'expired', deadline);
      if (!token) break;
      continue;
    }

    if (throttled && rateRetries < 4) {
      rateRetries++;
      const wait = Math.max(1, retryAfter);
      if (Date.now() + wait * 1000 >= deadline) break;
      sleep(wait);
      continue;
    }
    break;
  }
  return { token, ok: false };
}

export default function (data) {
  const phase = (__VU - 1) * 125;
  const deadline = data.start + 40000;
  const username = `bench-${__VU}`;

  // Spread authentication, then use a shared absolute schedule.
  sleep(phase / 2000);
  let token = login(username, deadline);
  if (!token) return;

  let slot = data.start + phase;
  const lastSlotBoundary = data.start + 36000;
  while (slot < lastSlotBoundary) {
    const now = Date.now();
    if (now > slot + 125) {
      // Do not make up missed slots with a burst.
      slot += Math.ceil((now - slot - 125) / 2000) * 2000;
      continue;
    }
    if (now < slot) sleep((slot - now) / 1000);

    const result = doWork(username, token, deadline);
    check(result, { 'work journey completed': (r) => r.ok });
    token = result.token;
    if (!token) return;
    slot += 2000;
  }
}

import os
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

import gevent
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


RATE = 8.0
MIN_START_SPACING = 1.0 / 12.0
TOKEN_CAPACITY = 2.0

_tokens = 1.0
_last_refill = time.monotonic()
_last_start = None
_t0 = None
_next_account = 0
_active_journeys = 0


def refill_tokens(now):
    global _tokens, _last_refill
    _tokens = min(TOKEN_CAPACITY, _tokens + (now - _last_refill) * RATE)
    _last_refill = now


def refund_attempt():
    global _tokens
    refill_tokens(time.monotonic())
    _tokens = min(TOKEN_CAPACITY, _tokens + 1.0)


def acquire_start(retry=False):
    global _tokens, _last_start

    while True:
        now = time.monotonic()
        if _t0 is not None:
            deadline = _t0 + (39.0 if retry else 35.0)
            if now >= deadline:
                raise StopUser()
        else:
            deadline = None

        refill_tokens(now)
        token_wait = max(0.0, (1.0 - _tokens) / RATE)
        spacing_wait = (
            0.0 if _last_start is None
            else max(0.0, _last_start + MIN_START_SPACING - now)
        )
        delay = max(token_wait, spacing_wait)

        if delay <= 0.0:
            _tokens -= 1.0
            _last_start = now
            return now

        if deadline is not None:
            delay = min(delay, max(0.0, deadline - now))
        gevent.sleep(delay)


class CSRFParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.token = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input" or self.token is not None:
            return
        attributes = dict(attrs)
        if (
            attributes.get("name") == "csrf"
            and "disabled" not in attributes
            and attributes.get("value")
        ):
            self.token = attributes["value"]

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def json_object(response):
    try:
        value = response.json()
    except (ValueError, TypeError):
        return None
    return value if isinstance(value, dict) else None


class WorkUser(HttpUser):
    host = os.environ["BASE_URL"]

    def wait_time(self):
        return 0

    def on_start(self):
        global _next_account
        _next_account += 1
        self.username = "bench-{}".format(((_next_account - 1) % 16) + 1)
        self.csrf = None
        if not self.login():
            raise StopUser()

    def login(self):
        token = None
        with self.client.get(
            "/v2/login-form", catch_response=True, timeout=4
        ) as response:
            if response.status_code != 200:
                response.failure("login form returned {}".format(response.status_code))
                return False
            parser = CSRFParser()
            try:
                parser.feed(response.text)
                parser.close()
            except Exception:
                response.failure("invalid login form")
                return False
            token = parser.token
            if not token:
                response.failure("login form missing csrf")
                return False

        redirect_url = None
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": token},
            allow_redirects=False,
            catch_response=True,
            timeout=4,
        ) as response:
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    response.failure("login redirect missing Location")
                    return False
                redirect_url = urljoin(response.url, location)
                destination = urlsplit(redirect_url)
                target = urlsplit(self.host)
                if (
                    destination.scheme != target.scheme
                    or destination.netloc != target.netloc
                ):
                    response.failure("login redirect points outside target")
                    return False
            elif response.status_code == 200:
                data = json_object(response)
                if (
                    not data
                    or not isinstance(data.get("csrf"), str)
                    or not data["csrf"]
                    or "user" not in data
                ):
                    response.failure("invalid login response")
                    return False
                self.csrf = data["csrf"]
                return True
            else:
                response.failure("login returned {}".format(response.status_code))
                return False

        with self.client.get(
            redirect_url,
            allow_redirects=False,
            catch_response=True,
            timeout=4,
        ) as response:
            data = json_object(response)
            if (
                response.status_code != 200
                or not data
                or not isinstance(data.get("csrf"), str)
                or not data["csrf"]
                or "user" not in data
            ):
                response.failure("invalid login redirect response")
                return False
            self.csrf = data["csrf"]
            return True

    def renew_or_login(self, reason):
        if reason == "session":
            return self.login()

        revoked = False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            timeout=4,
        ) as response:
            data = json_object(response)
            if response.status_code == 200:
                if (
                    not data
                    or not isinstance(data.get("csrf"), str)
                    or not data["csrf"]
                ):
                    response.failure("renewal missing csrf")
                    return False
                self.csrf = data["csrf"]
                return True
            if response.status_code == 401 and data and data.get("error") == "session":
                response.success()
                revoked = True
            else:
                response.failure("session renewal failed")
                return False

        return self.login() if revoked else False

    @task
    def work(self):
        global _active_journeys, _t0
        _active_journeys += 1
        try:
            retries_429 = 0
            auth_retried = False
            is_retry = False

            while True:
                started = acquire_start(retry=is_retry)
                outcome = None
                reason = None

                with self.client.post(
                    "/v2/work",
                    json={},
                    headers={"X-CSRF-Token": self.csrf},
                    catch_response=True,
                    timeout=4,
                ) as response:
                    data = json_object(response)

                    if response.status_code == 200:
                        if not data or data.get("ok") is not True:
                            response.failure("work response did not confirm success")
                            return
                        if "csrf" in data:
                            if not isinstance(data["csrf"], str) or not data["csrf"]:
                                response.failure("work returned invalid csrf")
                                return
                            self.csrf = data["csrf"]
                        if _t0 is None or started < _t0:
                            _t0 = started
                        return

                    if response.status_code == 429:
                        retry_after = response.headers.get("Retry-After", "").strip()
                        if retry_after != "1" or retries_429 >= 4:
                            response.failure("invalid or exhausted work rate-limit retry")
                            return
                        response.success()
                        outcome = "rate_limit"

                    elif response.status_code == 401:
                        reason = data.get("error") if data else None
                        if reason not in ("expired", "session") or auth_retried:
                            response.failure("unexpected or repeated work authentication failure")
                            return
                        response.success()
                        outcome = "auth"

                    else:
                        response.failure(
                            "unexpected work status {}".format(response.status_code)
                        )
                        return

                refund_attempt()
                is_retry = True

                if outcome == "rate_limit":
                    retries_429 += 1
                    gevent.sleep(1.0)
                else:
                    auth_retried = True
                    if not self.renew_or_login(reason):
                        raise StopUser()
        finally:
            _active_journeys -= 1


class WorkShape(LoadTestShape):
    def tick(self):
        now = time.monotonic()
        if _t0 is None:
            if self.get_run_time() >= 10:
                return None
        else:
            elapsed = now - _t0
            if elapsed >= 39.0:
                return None
            if elapsed >= 35.0 and _active_journeys == 0:
                return None
        return (16, 16)
